  const SUBTITLE_DB = {"v_a000_001.mp3":[["俺，是座敷童子……能让我在这儿住一阵子吗？太好了！那就打扰啦～",0,7.8]],"v_a000_007.mp3":[["呜……刚才那是什么？吓我一跳……",0,8.93]],"v_a000_009.mp3":[["呜啊啊～～！",0,2.02]],"v_a000_010.mp3":[["走吧！",0,1.32]],"v_a000_011.mp3":[["好吃，好吃呀！",0,2.51]],"v_a000_012.mp3":[["喂，喂！",0,0.82]],"v_a000_013.mp3":[["俺也是个男子汉呀。",0,2.63]],"v_a000_014.mp3":[["唔……嘿嘿嘿。",0,2.14]],"v_a000_015.mp3":[["不关我的事！我什么都不知道！",0,3.65]],"v_a000_016.mp3":[["别闹啦！",0,1.12]],"v_a000_017.mp3":[["别过来啊！",0,0.77]],"v_a000_018.mp3":[["我不会输的！",0,1.25]],"v_a000_019.mp3":[["好疼……",0,0.53]],"v_a000_020.mp3":[["我、我控制不住这股力量！",0,3.14]],"v_a000_021.mp3":[["我没那个意思啊。",0,4.35]],"v_a000_025.mp3":[["我是座敷童子。据说只要有我们，家里就会兴旺，所以家家都待我们很好。不过待腻了我们就会走。我们还挺随心所欲的。",0,13.4]],"v_a001_001.mp3":[["有没有坏孩子啊——————！！！哈哈，吓着啦？我是来访神生剥鬼。我会守护大家的。",0,17.92]],"v_a002_001.mp3":[["我是火车！真是受够了这黑心公司！一天只工作八小时！绝不多干一秒——！",0,11.25]],"v_a002_007.mp3":[["这下能连干二十四小时了！害我想起以前上班的地方了。",0,7.145]],"v_a002_010.mp3":[["一下搞定！",0,2.01]],"v_a002_011.mp3":[["什么事啊？",0,1.27]],"v_a002_012.mp3":[["干嘛呀！",0,1.58]],"v_a002_013.mp3":[["哇！你倒是敲门啊！",0,3.94]],"v_a002_014.mp3":[["真是的！",0,5.52]],"v_a002_015.mp3":[["天天干活，就犯了那么一点错，怎么全赖我啊……真是的，这活干不下去了！别想拦我！",0,12.67]],"v_a002_016.mp3":[["这活儿真黑心啊～！",0,2.63]],"v_a002_017.mp3":[["呜呀～～！",0,2]],"v_a002_018.mp3":[["噗呀！",0,1]],"v_a002_019.mp3":[["下手轻点啊！",0,3]],"v_a002_020.mp3":[["哦呀——！",0,2.5]],"v_a002_021.mp3":[["真不行了……工伤保险能给赔吗？",0,6.69]],"v_a002_025.mp3":[["俺是火车，干的是运送死者魂魄的活儿。可世上死的人也太多了，这差事真够黑心的。要是少死点人，俺的活儿也少了，世界也和平了。一下全解决了嘛。",0,20.14]],"v_a003_001.mp3":[["咱叫垢尝。如果是喊咱来，而不是去澡堂的话，咱会很开心的。",0,6.49]],"v_a004_001.mp3":[["我是鸦天狗。暂时就到你那儿待一阵子吧。多多关照啦！",0,7.59]],"v_a005_001.mp3":[["呃、那个，在下是夜行先生。糟了……自己给自己加「先生」也太羞耻了……",0,10.78]],"v_a005_007.mp3":[["其实我只想窝在家里来着。",0,4.056]],"v_a005_009.mp3":[["感觉不错啊……",0,1.71]],"v_a005_010.mp3":[["哦，好厉害……",0,1.97]],"v_a005_011.mp3":[["啊，好。",0,0.82]],"v_a005_012.mp3":[["您在干什么呀？",0,1.13]],"v_a005_013.mp3":[["诶，真的假的？",0,3.07]],"v_a005_014.mp3":[["呜啊～～……",0,1.78]],"v_a005_015.mp3":[["就让你见识见识我夜行真正的本事吧！",0,3.99]],"v_a005_016.mp3":[["好嘞，黑铁！",0,2.16]],"v_a005_017.mp3":[["我还想早点回去呢～！",0,3.55]],"v_a005_021.mp3":[["都说了，我不想出现在别人面前。",0,3.43]],"v_a005_025.mp3":[["好，我是夜行。要是在夜路上遇见我，你就假装没看见，或者把鞋顶在头上趴在地上，我就放你一马。记得照做哦。",0,15.7]],"v_a006_001.mp3":[["祭典在哪呀——哟嘿！！诶？我？我叫鵺哦——这条蛇叫阿沙！",0,7.49]],"v_a006_009.mp3":[["呜诶诶……",0,1.13]],"v_a006_010.mp3":[["砰～～！",0,1.01]],"v_a006_011.mp3":[["对呀，对呀。",0,2.7]],"v_a006_012.mp3":[["大哥！",0,0.75]],"v_a006_013.mp3":[["嘻嘻嘻，呵呵呵……",0,3.41]],"v_a006_014.mp3":[["啊……呜……",0,2.77]],"v_a006_015.mp3":[["谁在碍事啊？看我电得你直哆嗦！",0,3.98]],"v_a006_016.mp3":[["打中吧——！",0,1.43]],"v_a006_017.mp3":[["开心！",0,1.95]],"v_a006_018.mp3":[["呀啊～！……祭典，已经结束了吗？",0,5.92]],"v_a006_025.mp3":[["我是鵺，尾巴上的沙君是我的搭档！人家都说鵺的叫声瘆人，可我听不出来呀！",0,11.37]],"v_a012_001.mp3":[["我是青行灯！来吧来吧，快来和我一起说百物语！",0,6.29]],"v_a018_001.mp3":[["贫僧，信州之灵犬，名叫悉平太郎。回应你的请求，前来助一臂之力！",0,7.93]],"v_a018_007.mp3":[["哦，看来是佛祖保佑啊。",0,4.09]],"v_a019_001.mp3":[["我是白布！总有一天要用我纯白的衣服充满这个世界。嗯，噢噢噢！？　你，体型不错嘛……咕呼，咕呼呼，灵感涌上来了啊！",0,19.38]],"v_awn_000.mp3":[["魂これ！",0,0.85]],"v_awn_001.mp3":[["老板你喊我吗！我是南海道的阿波！既然被雇用了，那可得跳舞跳个痛快呀~！",0,9.48]],"v_awn_002.mp3":[["嘭嘭嘭——！嘿嘿，看到老板惊讶的表情可太开心啦！我还会再来逗你玩的，好好期待吧♪",0,13.2]],"v_awn_003.mp3":[["老板，你也要为关键时候多攒着点哦。等一口气放出来时，那股畅快劲儿可真叫人欲罢不能！",0,9.78]],"v_awn_004.mp3":[["搞定啦～♪ 老板，工作也差不多该收工了吧？来跟咱一起跳支舞嘛♪",0,9.86]],"v_awn_005.mp3":[["哇啊，老板！？突然把咱举起来，咱会害羞的啦～羞羞♪",0,8.23]],"v_awn_006.mp3":[["为了最棒的那一刻，还得多攒一点、再多攒一点～嘿嘿嘿♪",0,7.55]],"v_awn_007.mp3":[["哎哟哟哟……越是难熬的时候，越要跳舞嘛！",0,7.207]],"v_awn_010.mp3":[["老爷，今天可算到了把攒下的东西一口气花光的时候啦！",0,6.54]],"v_awn_015.mp3":[["蛋蛋在水上漂呀漂～",0,4.632]],"v_awn_016.mp3":[["老板～！这回让咱好好伺候你，就当是感谢你平日的照顾啦！用咱的身体搓出泡泡，嘿，这就成了泡泡版阿波舞♪ 蹭呀蹭，搓呀搓～！咱的蛋蛋拿来当海绵也刚刚好吧？嘿嘿♪",0,25.99]],"v_awn_024.mp3":[["老板～，你来啦！今天也辛苦一整天啦。来，让咱的蛋蛋枕头帮你消消疲劳吧！",0,9.93]],"v_awn_025.mp3":[["咱最喜欢变个戏法捉弄人，还有跳舞啦。不过，跟老板一起悠哉悠哉地待着，也一样开心呢～",0,9.65]],"v_awn_026.mp3":[["咱这毛茸茸的尾巴枕头，还有软绵绵的蛋蛋枕头。两种都挺舒服吧？老板想用的话，咱每晚都让你枕哦♪",0,12.4]],"v_awn_027.mp3":[["老板～♪ 要是有什么不开心的事，就来找咱呀！咱会跳个痛快，直到把老板逗笑为止～！",0,10.79]],"v_awn_028.mp3":[["啊，老大！咱可是为了今天攒了个够呢。今天就全部痛痛快快地释放出来吧！",0,15.24]],"v_awn_029.mp3":[["躺在俺身上也行哦，毛茸茸、软乎乎的！",0,6.24]],"v_awn_030.mp3":[["那俺就跟这个舞队一起跳啦。",0,2.67]],"v_awn_051.mp3":[["俺要攒得满满当当呀～！",0,2.47]],"v_awt_000.mp3":[["魂これ！",0,1.01]],"v_awt_001.mp3":[["哟，少年。看来咱们的目标是一致的呢。就让神秘的大哥哥安房来助你一臂之力吧。",0,9.66]],"v_awt_002.mp3":[["看来少年还挺中意我的嘛。啊哈哈哈！",0,6.7]],"v_awt_003.mp3":[["要是发现犬家的人，就把他带到我这里来。",0,4.3]],"v_awt_004.mp3":[["你这表情，还真叫人心动呢。开玩笑的，哈哈哈哈！",0,11.17]],"v_awt_005.mp3":[["别再继续了，少年。不然我可就控制不住自己了。",0,5.19]],"v_awt_006.mp3":[["没什么，只是在看着少年你而已。没关系吧？",0,7.23]],"v_awt_007.mp3":[["别靠近！我现在可没把握能克制住自己。哈、呵呵。",0,8.344]],"v_awt_008.mp3":[["嗯，干得好啊，少年。",0,3.6]],"v_awt_009.mp3":[["大哥哥可真为你骄傲。",0,2.3]],"v_awt_010.mp3":[["这么粗的东西，塞得进去吗？呵呵，开个玩笑。",0,7.23]],"v_awt_012.mp3":[["嗯，少年的力量真让人舒服啊。",0,4.92]],"v_awt_013.mp3":[["这是……唔、唔，啊啊……！",0,3.3]],"v_awt_014.mp3":[["这可……嗯、唔啊……你说我可爱什么的，不许拿大哥哥开玩笑。",0,8.27]],"v_awt_015.mp3":[["不跟大哥哥一起泡吗？呵呵。",0,4.59]],"v_awt_016.mp3":[["少年还真是大胆呢。就让我帮你从头到脚仔仔细细洗个遍吧。呵呵，紧张了吗？",0,13.42]],"v_awt_017.mp3":[["感觉挺好啊。",0,1.6]],"v_awt_018.mp3":[["交给大哥哥吧。",0,2.64]],"v_awt_019.mp3":[["少年喜欢这个啊？要不要凑近点看？",0,7.51]],"v_awt_020.mp3":[["怎么了？",0,2.55]],"v_awt_021.mp3":[["哟，少年。",0,1.39]],"v_awt_022.mp3":[["你这家伙，来得可真不是时候。",0,5.38]],"v_awt_023.mp3":[["嗯……唔、嗯……",0,4.71]],"v_awt_024.mp3":[["欢迎来到我的住处，少年。不过这里可不是你这样的小孩子该来的地方哦。哼哼。",0,8.16]],"v_awt_025.mp3":[["伙伴可是最重要的。值得信赖的人，实在难能可贵。",0,7.44]],"v_awt_026.mp3":[["少年，肚子露出来了哦。这未免太会卖萌了吧。",0,7.35]],"v_awt_027.mp3":[["干什么这么盯着我看？少年是在勾引我吗？哈哈。",0,8.66]],"v_awt_028.mp3":[["接下来可就不是开玩笑的了。不过，既然少年想要的话……",0,10.08]],"v_awt_029.mp3":[["你真的很可爱呢。",0,4.68]],"v_awt_030.mp3":[["哎呀，要是能不拔刀就好了。",0,4.8]],"v_awt_031.mp3":[["哦？可以吗？",0,2.43]],"v_awt_032.mp3":[["呵呵，挺可爱的小东西。",0,2.3]],"v_awt_033.mp3":[["你以为我没察觉？",0,2.3]],"v_awt_034.mp3":[["就顺着魂珠的指引吧。",0,2.38]],"v_awt_035.mp3":[["这股冲动，我怕是压不住了。",0,4.47]],"v_awt_036.mp3":[["哈哈哈哈！",0,1.75]],"v_awt_037.mp3":[["呵呵，就让我试试刀够不够锋利。",0,3.75]],"v_awt_038.mp3":[["好！太好了！",0,2.76]],"v_awt_039.mp3":[["所以呢？",0,1.3]],"v_awt_040.mp3":[["哈哈哈哈！",0,1.3]],"v_awt_041.mp3":[["我开始兴奋起来了。",0,2.38]],"v_awt_042.mp3":[["呵呵，该撤了。",0,2.55]],"v_awt_043.mp3":[["幸好少年没在这儿。刚才可下了一场血雨呢。",0,6.41]],"v_awt_044.mp3":[["呵呵。",0,0.48]],"v_awt_045.mp3":[["哦？",0,1.39]],"v_awt_046.mp3":[["疼吗？",0,1.39]],"v_awt_047.mp3":[["真是个不乖的孩子。",0,1.83]],"v_awt_048.mp3":[["咱们心有灵犀呢。",0,1.39]],"v_awt_049.mp3":[["这样就结束了？",0,1.39]],"v_awt_050.mp3":[["呵呵，多谢你啦。",0,1.92]],"v_awt_051.mp3":[["来，跟大哥哥走吧。",0,2.71]],"v_awt_052.mp3":[["我是房州的安房，犬族的安房。以前，阿波的狸族渡海来到这里，开垦了这片土地，所以两地同音，都叫「阿瓦」。……我觉得，跟三河应该能处得来。",0,19.9]],"v_awt_128.mp3":[["怎么啦，少年？被我的泳装迷住了？",0,5.5]],"v_awt_129.mp3":[["在单独的房间里，和穿着泳装的我两个人独处。哼哼，少年会心跳加速也不奇怪呢。",0,10.1]],"v_awt_130.mp3":[["来吧，少年，一起游泳去。",0,2.3]],"v_awt_131.mp3":[["交给海边的大哥哥吧！",0,3.3]],"v_bic_000.mp3":[["魂之所在！",0,0.746]],"v_bic_001.mp3":[["山阳道的备中……我的兄弟们，没给您添什么麻烦吧……？",0,7.48]],"v_bic_002.mp3":[["咦……您是在叫我吗？要我帮您占卜一下吉凶吗？",0,5.38]],"v_bic_003.mp3":[["只要把这份吉备团子送出去，什么问题都能解决。",0,3.23]],"v_bic_004.mp3":[["我想了个作战计划，可以请您过目吗？",0,3.94]],"v_bic_005.mp3":[["哇啊！只、只是手不小心碰到了而已……对吧……？",0,4.82]],"v_bic_006.mp3":[["这个、那个……那份文件也整理一下吧。好！",0,6]],"v_bic_007.mp3":[["呜……火辣辣地疼。",0,2.712]],"v_bic_008.mp3":[["太出色了。",0,1.24]],"v_bic_009.mp3":[["哦，我觉得这是很出色的战绩。",0,2.79]],"v_bic_010.mp3":[["购物清单呢……咦？！我明明准备好了的！",0,5.179]],"v_bic_012.mp3":[["主人，我有帮上忙吗？",0,2.93]],"v_bic_013.mp3":[["哇啊！",0,1.493]],"v_bic_014.mp3":[["哇啊啊～！哈、哈……比、比想的还厉害……我、我腿软得站不起来了……",0,10.16]],"v_bic_015.mp3":[["啊，感觉像漂在云海上。",0,4.18]],"v_bic_016.mp3":[["主、主人，您也太大胆了！都碰到我了啊。诶，接下来还要继续吗？",0,10.06]],"v_bic_017.mp3":[["我还没做好心理准备……",0,2.11]],"v_bic_018.mp3":[["哇、哇啊……！",0,1.19]],"v_bic_019.mp3":[["现在就穿，对吧？我知道了。",0,3.63]],"v_bic_020.mp3":[["您找我吗？",0,1.062]],"v_bic_021.mp3":[["主人……",0,0.76]],"v_bic_022.mp3":[["啊！别、别看！",0,2.62]],"v_bic_023.mp3":[["啊、啊啊……",0,2.49]],"v_bic_024.mp3":[["我就猜到您差不多该来了。请进吧。",0,3.9]],"v_bic_025.mp3":[["真紧张啊……我有好好把话说清楚吗？",0,4.9]],"v_bic_026.mp3":[["这身衣服是占卜必需的！绝、绝不是因为我喜欢女装……",0,4.43]],"v_bic_027.mp3":[["啊，这个……那个……因为主人靠得这么近……",0,7.51]],"v_bic_028.mp3":[["主人……我想让您再给我更多快乐。",0,7.45]],"v_bic_029.mp3":[["冷、冷静点。我没问题的，一定能做好。",0,4.91]],"v_bic_030.mp3":[["实、实战！我会加油的！",0,2.408]],"v_bic_031.mp3":[["那么大伙儿，就按我的作战计划来哦。",0,2.74]],"v_bic_032.mp3":[["果然和占卜的一样。",0,1.407]],"v_bic_033.mp3":[["那、那是什么？",0,2.12]],"v_bic_034.mp3":[["走这条路，没问题吧？",0,2.69]],"v_bic_035.mp3":[["敌、敌袭！按、按作战计划来！哇啊……",0,3.74]],"v_bic_036.mp3":[["嘿呀！",0,0.86]],"v_bic_037.mp3":[["照练习时那样做，应该能行。",0,2.24]],"v_bic_038.mp3":[["就是这儿！",0,0.94]],"v_bic_039.mp3":[["等等，等等！",0,1.47]],"v_bic_040.mp3":[["我给你团子吃嘛。",0,1.69]],"v_bic_041.mp3":[["有、有话好商量！",0,2.62]],"v_bic_042.mp3":[["果然，我还是不行。",0,2.33]],"v_bic_043.mp3":[["我、我吗？谢谢您，太好了～",0,4.62]],"v_bic_044.mp3":[["成、成功了！",0,1.44]],"v_bic_045.mp3":[["哇啊，我的作战计划……",0,2.32]],"v_bic_046.mp3":[["我要瞄准了。",0,0.84]],"v_bic_047.mp3":[["我来重整阵势。",0,0.93]],"v_bic_048.mp3":[["按计划进行。",0,1.16]],"v_bic_049.mp3":[["大家，只剩一个了！",0,1.59]],"v_bic_050.mp3":[["谢谢您。",0,2.16]],"v_bic_051.mp3":[["啊，等一下，我还没准备好……",0,2.76]],"v_bic_052.mp3":[["我是备州、吉备国的备中。备中国有个著名的故事，说的是桃太郎打鬼。我以后也要当个了不起的剑士……！不、不过……先用吉备团子多招些伙伴吧……",0,17.49]],"v_bic_120.mp3":[["主人，要吃杂煮吗？里面有圆年糕，还有寓意吉祥的鰤鱼。一定会是个好年头的。",0,9.14]],"v_bic_121.mp3":[["主人，您已经去初诣了吗？不介意的话，要不要瞒着大家，就我们两个人一起去？毕、毕竟是新年嘛，偶尔这样也不错……",0,16.25]],"v_bic_122.mp3":[["要吃年糕吗？",0,1.79]],"v_bic_123.mp3":[["过年总有忙不完的事，请务必让我留在您身边。",0,4.53]],"v_bic_128.mp3":[["主人擅长游泳吗？我倒也不算不擅长，只是……果然还是待在陆地上比较安心吧。",0,10.43]],"v_bic_129.mp3":[["真想抛开任务，去水边玩一趟呢。如果主人愿意，我们一起去吧。我也很期待看见主人的泳装。",0,11.43]],"v_bic_130.mp3":[["为什么在泳池边吃的饭，总是这么香呢？",0,4.51]],"v_bin_000.mp3":[["魂これ！",0,0.82]],"v_bin_001.mp3":[["哟！主人！咱是山阳道的备后！往后可要多关照啦！",0,5.59]],"v_bin_002.mp3":[["主人！咱刚好想到了个有趣的玩法！一起来玩嘛！",0,6.22]],"v_bin_003.mp3":[["玩什么呀？难道是现在流行的游戏？也教教老夫吧！",0,8.3]],"v_bin_004.mp3":[["主人，衣服已经洗好啦。我也帮您好好叠起来了。",0,5.64]],"v_bin_005.mp3":[["好、好痒呀。咦，这是……色色的事情吗？那、那可不行呀！",0,14.9]],"v_bin_006.mp3":[["好闲啊，好闲啊，主人！",0,5.83]],"v_bin_007.mp3":[["受伤？这也用得着操心？",0,3.144]],"v_bin_008.mp3":[["任务做完啦。走，下一个！",0,3.46]],"v_bin_009.mp3":[["嗯嗯，主人真厉害呀。",0,5.14]],"v_bin_010.mp3":[["有主人上回提到的那个玩具吗？",0,3.15]],"v_bin_012.mp3":[["哦，主人觉得怎么样？俺变强了吗？",0,5.69]],"v_bin_013.mp3":[["嗯啊啊……",0,3.12]],"v_bin_014.mp3":[["呜啊……哈……俺、俺什么都不知道。主人也赶紧忘了吧！",0,8.74]],"v_bin_015.mp3":[["俺不爱泡澡，得乖乖待着不动呢。",0,4.27]],"v_bin_016.mp3":[["主人，这实在有点难为情……唔，老夫不太擅长这种事啊。",0,12.55]],"v_bin_017.mp3":[["唔！你在干啥！",0,2.28]],"v_bin_018.mp3":[["感觉怪怪的啊。",0,2.81]],"v_bin_019.mp3":[["这就试穿！先脱光……嗯，主人，你怎么啦？",0,9.46]],"v_bin_020.mp3":[["在！",0,0.48]],"v_bin_021.mp3":[["主人！",0,0.84]],"v_bin_022.mp3":[["没有什么啦！",0,3.99]],"v_bin_023.mp3":[["唔……啊——！",0,2.4]],"v_bin_024.mp3":[["啊，主人，带好玩的东西来了吗？今晚可是要通宵喽！",0,5.52]],"v_bin_025.mp3":[["嗯嗯，点心和夜宵全都准备齐了，放心吧！",0,7.15]],"v_bin_026.mp3":[["怎么啦？……像这样紧紧抱住你，就会暖和起来啦。",0,9.89]],"v_bin_027.mp3":[["锵锵！我特制的大阪烧做好啦！主人，来吃吧！",0,6.58]],"v_bin_028.mp3":[["主、主人！我、我才没有发出那种奇怪的声音呢！不准说出去！",0,14.69]],"v_bin_029.mp3":[["主人，别挠我啦！咯吱咯吱咯吱～",0,5.54]],"v_bin_030.mp3":[["看俺去大闹一场！",0,2.83]],"v_bin_031.mp3":[["全都跟上俺！",0,3.05]],"v_bin_032.mp3":[["是俺发现的！",0,1.47]],"v_bin_033.mp3":[["好像挺有意思！",0,2.4]],"v_bin_034.mp3":[["走这边！",0,0.82]],"v_bin_035.mp3":[["俺第一个上！",0,2.11]],"v_bin_036.mp3":[["就是那儿！",0,2.03]],"v_bin_037.mp3":[["接招吧！",0,1.27]],"v_bin_038.mp3":[["你这家伙，在搞什么啊！",0,1.44]],"v_bin_039.mp3":[["没用没用！",0,1.61]],"v_bin_040.mp3":[["呜哦！",0,0.63]],"v_bin_041.mp3":[["俺要狠狠揍你一顿！",0,2.5]],"v_bin_042.mp3":[["好累……让我歇歇。",0,3.91]],"v_bin_043.mp3":[["嘎哈哈！俺可强啦！才不输给那几个哥哥呢！",0,6.05]],"v_bin_044.mp3":[["哦！",0,0.99]],"v_bin_045.mp3":[["那也没辙。",0,1.27]],"v_bin_046.mp3":[["给我躺下！",0,1.18]],"v_bin_047.mp3":[["你这家伙啊！",0,1.54]],"v_bin_048.mp3":[["集中攻击！",0,2.14]],"v_bin_049.mp3":[["交给俺吧！",0,1.8]],"v_bin_050.mp3":[["可帮大忙了！",0,1.32]],"v_bin_051.mp3":[["主人，快来一起玩吧！",0,3.55]],"v_bin_052.mp3":[["俺是备州、吉备国后部的备后！说到备后，那就是帝释峡、尾道，还有御好烧！好东西多着呢。不过几个兄弟里，俺才是最高大的！",0,17.17]],"v_bin_106.mp3":[["出门玩啦！看看最新电影，尝尝流行美食，再去游戏中心玩一玩！真期待啊！",0,10.69]],"v_bin_107.mp3":[["我想去主人家乡看看呢。带我去嘛！最后还想去主人家里玩！",0,9.72]],"v_bin_111.mp3":[["哼哼，看来没忘带东西呢。",0,3.35]],"v_bin_128.mp3":[["主人，我能在院子里烤肉吗？趁主人工作的时候，我来烤肉，再做点大阪烧！",0,10.21]],"v_bin_129.mp3":[["我对那个叫水上滑梯的游戏挺感兴趣。不过在海边玩也很棒呢。主人更喜欢哪个？",0,11.96]],"v_bin_130.mp3":[["大家一起烤肉吧！",0,2]],"v_biz_000.mp3":[["魂これ！",0,0.93]],"v_biz_001.mp3":[["噔噔——！山阳道，备前，华丽登场！一起冲向顶峰吧！大——将！",0,9.11]],"v_biz_002.mp3":[["叭嘭！再次登场！大将，你果然有眼光啊！",0,6.21]],"v_biz_003.mp3":[["尽管大大方方地摸嘛，比如这里。",0,5.74]],"v_biz_004.mp3":[["我才是老大心中的第一名，对吧？",0,2.71]],"v_biz_005.mp3":[["哈哈，憋坏了？那就干脆痛快地来上一发吧！",0,4.76]],"v_biz_006.mp3":[["文书工作烦死了，找别人来干吧。",0,4.72]],"v_biz_007.mp3":[["快点好起来吧，我还想做点好事儿呢。",0,3.11]],"v_biz_010.mp3":[["大将，都买下来吧！痛痛快快地买个够！",0,4.08]],"v_biz_015.mp3":[["喂，大家一块儿泡吧！",0,3.408]],"v_biz_016.mp3":[["瞧瞧，我的身体很柔软吧？嗯？哎呀，老大还挺精神的嘛！好，就这么进行到底吧！",0,14.26]],"v_biz_020.mp3":[["轮到我出场了？",0,1.48]],"v_biz_024.mp3":[["啊，老大，过来过来。对，老大的位置就在我身边。",0,6.77]],"v_biz_025.mp3":[["喂，哪个更华丽、更像我呢？",0,5.14]],"v_biz_026.mp3":[["执行任务时捡到了个不得了的东西！想看吗？一起看吧？",0,5.71]],"v_biz_027.mp3":[["老大，我们一起唱歌吧！告诉我你喜欢什么歌。",0,4.26]],"v_biz_028.mp3":[["我……只有跟老大在一起，心才会跳得这么快。来，快点吧！",0,8.76]],"v_biz_029.mp3":[["老大，在装睡吗？身体明明有反应嘛。",0,7.22]],"v_biz_030.mp3":[["我站中间啊。",0,1.42]],"v_biz_051.mp3":[["要轰轰烈烈地开场啦！",0,1.61]],"v_boss1017_000.mp3":[["一定要在这里阻止那家伙失控。东山道下野，开始执行任务。",0,7.67]],"v_boss1017_001.mp3":[["为什么就是不明白？",0,1.12]],"v_boss1017_002.mp3":[["为什么还要站起来？",0,1.85]],"v_boss1017_003.mp3":[["还没结束。",0,1.12]],"v_boss1017_004.mp3":[["损耗轻微。可以继续战斗。",0,4.03]],"v_boss1017_005.mp3":[["到此为止。",0,1.49]],"v_boss1017_006.mp3":[["在你理解之前，我会一次又一次地迎战。",0,5.74]],"v_bun_000.mp3":[["魂之所在，喵！",0,1.628]],"v_bun_001.mp3":[["丰之国、两丰之一的丰后就是我喵。我最讨厌做无用功了喵。不过，有病人的话，我还是会给他看看病情的喵。",0,10.46]],"v_bun_002.mp3":[["喵！？我正在学习呢喵！活着就是要不断学习喵！那我先回去啦喵！",0,8.23]],"v_bun_003.mp3":[["主人，与其花时间玩，不如拿来学习喵。",0,5.81]],"v_bun_004.mp3":[["喵！？你累了，想让俺帮你消除疲劳？那就给你打一针大蒜注射吧喵！",0,10.46]],"v_bun_005.mp3":[["哼，你要摸就摸吧，不过做没意义的事就是浪费时间喵。",0,8.55]],"v_bun_006.mp3":[["吃饭只要能补充营养就够了。啊，其实我更喜欢鱼啦。",0,6.92]],"v_bun_007.mp3":[["应急处理，我已经自己做过了喵。先照顾重伤的人吧喵……",0,6.818]],"v_bun_008.mp3":[["已经消过毒喵！",0,1.63]],"v_bun_009.mp3":[["别回头看过去喵，往前走喵。",0,4.31]],"v_bun_010.mp3":[["书可是知识的宝库喵～",0,3.13]],"v_bun_012.mp3":[["原来如此喵，嗯嗯。看来还有进步的余地喵。",0,5.39]],"v_bun_013.mp3":[["呀、呀啊～！",0,2.804]],"v_bun_014.mp3":[["喵、喵啊～～！哈、哈……不、不许看，笨蛋喵！我这就回去！",0,6.58]],"v_bun_015.mp3":[["赶紧弄完喵。",0,2.19]],"v_bun_016.mp3":[["喵、喵！？主人怎么进来了喵！我正在疗伤呢！……算了，随你便吧喵。",0,13.63]],"v_bun_017.mp3":[["喵啊啊啊～～！",0,2.63]],"v_bun_018.mp3":[["呵呵呵……得做手术喵。",0,4.16]],"v_bun_019.mp3":[["得穿好点的内裤喵。",0,2.15]],"v_bun_020.mp3":[["嗯喵？",0,1.129]],"v_bun_021.mp3":[["主人喵。",0,1.13]],"v_bun_022.mp3":[["喵、喵喵，别看喵～！",0,4.14]],"v_bun_023.mp3":[["喵、喵～～！",0,3.13]],"v_bun_024.mp3":[["开始诊察喵。今天哪里不舒服？装病可不行喵。",0,7.32]],"v_bun_025.mp3":[["希望你别在夜里跑来见我……嗯，也不是说会给我添麻烦啦。",0,7.83]],"v_bun_026.mp3":[["嗯……怎么样喵？嘿嘿，效果立竿见影喵！让主人恢复精神，对医生来说易如反掌喵！",0,14.59]],"v_bun_027.mp3":[["别老摸我，害我没法集中精神看书……唉，你根本没在听喵。",0,10.78]],"v_bun_028.mp3":[["喵！？要做触诊喵？俺身上哪儿都没毛病喵！啊，主人……换俺给你检查检查喵。",0,16.21]],"v_bun_029.mp3":[["这种时候，是不是该牵个手什么的喵？",0,5.94]],"v_bun_030.mp3":[["我也随军喵！",0,1.629]],"v_bun_031.mp3":[["让你们见识一下赤猫的骨气喵！",0,2.63]],"v_bun_032.mp3":[["没用的东西就不要了喵。",0,2.129]],"v_bun_033.mp3":[["哪有笨蛋会中那种招喵。",0,2.63]],"v_bun_034.mp3":[["不许绕路喵。",0,2.13]],"v_bun_035.mp3":[["开始做手术喵！",0,1.629]],"v_bun_036.mp3":[["给你处理一下喵。",0,1.13]],"v_bun_037.mp3":[["消毒喵！",0,1.13]],"v_bun_038.mp3":[["把你打成筛子喵！",0,1.63]],"v_bun_039.mp3":[["呜喵喵喵！",0,1.13]],"v_bun_040.mp3":[["怎么会这样喵～！？",0,1.61]],"v_bun_041.mp3":[["别乱动喵！乖乖让我给你治喵！",0,4.19]],"v_bun_042.mp3":[["这可真是大夫不懂保养喵……丢人了喵。",0,3.66]],"v_bun_043.mp3":[["赶紧给伤员处理伤口喵。请求支援物资喵。",0,5.18]],"v_bun_044.mp3":[["没问题喵。",0,1.13]],"v_bun_045.mp3":[["该撤了喵？",0,1.63]],"v_bun_046.mp3":[["解决掉你喵！",0,1.13]],"v_bun_047.mp3":[["看见了喵！",0,1.13]],"v_bun_048.mp3":[["我要瞄准喵！",0,1.13]],"v_bun_049.mp3":[["给我沉下去喵！",0,1.13]],"v_bun_050.mp3":[["谢了喵。",0,1.13]],"v_bun_051.mp3":[["下一位病人在哪儿？",0,2.24]],"v_bun_052.mp3":[["我是西海道、丰国的丰州丰后喵。以前也叫「丰国之道后」喵。出名的别府温泉乡，泉眼数量和涌出量都是日本第一喵。我还分给过伊予呢。真、真的喵！",0,21.36]],"v_bun_057.mp3":[["广告宣传就拜托啦喵。",0,1.63]],"v_bun_128.mp3":[["医生偶尔也要享受休假喵。主人也别忘了做好防晒喵。",0,7.98]],"v_bun_129.mp3":[["主人，身体这么僵硬就去游泳很危险喵。好好放松开，我会从后面推着你的喵。",0,9.76]],"v_bun_130.mp3":[["海里也有很多危险喵。",0,2.13]],"v_ckg_000.mp3":[["魂これ！",0,2.14]],"v_ckg_001.mp3":[["我是西海道的筑后！总有一天，我也要像哥哥那样受欢迎……喂，主人！你有在听吗！？",0,8.66]],"v_ckg_002.mp3":[["是筑后哟！等、等等等，主人！这边这边！喂——！",0,5.64]],"v_ckg_003.mp3":[["喂，你有在听吗？",0,3.64]],"v_ckg_004.mp3":[["今天也要练习帅气的招牌姿势！",0,2.63]],"v_ckg_005.mp3":[["啊呜……这就是恋爱话题里说的摸摸吗？",0,5.74]],"v_ckg_006.mp3":[["我明明一直都在这里……啊，他没发现。",0,6.76]],"v_ckg_007.mp3":[["下回，筑后大显身手……要真能这样就好啦。嘿嘿。",0,5.686]],"v_ckg_008.mp3":[["做好啦，主——人——！",0,3.64]],"v_ckg_009.mp3":[["我也要一步一步努力！",0,2.64]],"v_ckg_010.mp3":[["啊，哥哥还托我买东西来着。",0,3.63]],"v_ckg_012.mp3":[["这样大伙儿会注意到我吗？",0,3.13]],"v_ckg_013.mp3":[["啊啊啊！",0,2.03]],"v_ckg_014.mp3":[["啊啊，主人，再多看看我……啊，好高兴……",0,8.79]],"v_ckg_015.mp3":[["我去把自己打扮成漂漂亮亮的筑后啦！",0,2.19]],"v_ckg_015_1.mp3":[["我去把自己打扮成漂漂亮亮的筑后啦！",0,2.18]],"v_ckg_016.mp3":[["主、主人！被您看见那种地方，我会害羞的！……这也是为了引人注目的训练？我、我知道了！",0,13.95]],"v_ckg_016_1.mp3":[["主、主人！被您看见那种地方，我会害羞的！……这也是为了引人注目的训练？我、我知道了！",0,13.94]],"v_ckg_017.mp3":[["大家需要我啦！",0,2.7]],"v_ckg_018.mp3":[["感受我的存在吧！",0,3.31]],"v_ckg_019.mp3":[["知道啦。我现在就换衣服，你要看着哦！",0,5.07]],"v_ckg_020.mp3":[["在！在！",0,1.7]],"v_ckg_021.mp3":[["主人！主人——！",0,2.63]],"v_ckg_022.mp3":[["怎、怎么偏偏在这种时候……",0,3.94]],"v_ckg_023.mp3":[["啊——！",0,1.13]],"v_ckg_024.mp3":[["欢迎光临，主人！我会好好表现的！",0,2.66]],"v_ckg_025.mp3":[["所以啊，后来呢……咦？怎么光是我在说话？因为太开心啦。",0,9.07]],"v_ckg_026.mp3":[["被主人这样注视着……我很开心哦。",0,4.35]],"v_ckg_027.mp3":[["真想听主人讲讲恋爱故事呀。",0,3.63]],"v_ckg_028.mp3":[["啊！该是展示练习成果的时候了。加油啊，筑后！",0,5.98]],"v_ckg_029.mp3":[["在这种情况下，你竟然还没注意到我吗？",0,4.44]],"v_ckg_030.mp3":[["大家，也带上我吧！",0,3.14]],"v_ckg_031.mp3":[["嘿嘿嘿，我终于要登上大舞台啦！",0,4.17]],"v_ckg_032.mp3":[["大伙儿，看那边！",0,2.13]],"v_ckg_033.mp3":[["轮到我上场了，交给我吧！",0,2.45]],"v_ckg_034.mp3":[["大伙儿，别往那边走！",0,4.63]],"v_ckg_035.mp3":[["跟着我走——喂，别丢下我啊！",0,4.96]],"v_ckg_036.mp3":[["有破绽！",0,1.13]],"v_ckg_037.mp3":[["该不会没注意到我吧？",0,3.19]],"v_ckg_038.mp3":[["好好瞧瞧这守火的本领吧！",0,2.85]],"v_ckg_039.mp3":[["啊呜！",0,0.63]],"v_ckg_040.mp3":[["等等！",0,1.13]],"v_ckg_041.mp3":[["啊，我才不要这样引人注目。",0,5.29]],"v_ckg_042.mp3":[["就这样撤退，谁也没注意到我啊……",0,4.65]],"v_ckg_043.mp3":[["大伙儿快看！我在发光耶！",0,5.43]],"v_ckg_044.mp3":[["成功！",0,1.63]],"v_ckg_045.mp3":[["诶？骗人的吧？",0,1.43]],"v_ckg_046.mp3":[["就是这儿！",0,1.13]],"v_ckg_047.mp3":[["我来保护你！",0,1.63]],"v_ckg_048.mp3":[["我也来，我也来！",0,1.63]],"v_ckg_049.mp3":[["大伙儿，瞧好了！",0,2.13]],"v_ckg_050.mp3":[["谢、谢谢！",0,2.62]],"v_ckg_051.mp3":[["咦？主人，你就这么走过去啦！？",0,3.3]],"v_ckg_052.mp3":[["我是西海道、筑州的筑后。这里原本叫筑紫国，后来才分成哥哥和我。哥哥又显眼又帅气，我也想多被大家注意一点呀。",0,16.05]],"v_ckg_128.mp3":[["主人，天气真好呀。我想和你一起去游泳池！虽然我不太会游泳，但我会套着游泳圈漂在水上，主人能牵着我的手吗？",0,15.22]],"v_ckg_129.mp3":[["嘿咻！啊，主人，我正在练习打腿呢。那个……可以帮我活动一下双腿吗？嘿咻、嘿咻。只要主人看着，我就更有干劲！",0,20.37]],"v_ckg_130.mp3":[["夏天……是恋爱的季节！",0,6.31]],"v_ckz_000.mp3":[["魂これ啦！",0,1.5]],"v_ckz_001.mp3":[["咱就是传唱黑田节的筑前！耍枪唱歌天下第一！算是西海道扛把子吧♪多关照嗷！",0,13.15]],"v_ckz_002.mp3":[["闻到祭典味儿啦！　……啥？是主人啊？要是派活儿咱可不接嗷！但要是祭典任务，咱屁颠屁颠就去！",0,14.36]],"v_ckz_003.mp3":[["那么，接下来开始准备祭典啦！……喂，来这边！",0,5.86]],"v_ckz_004.mp3":[["主人！做事认真点！想玩就放开了玩，认认真真地玩！",0,7.49]],"v_ckz_005.mp3":[["噢！黄瓜和女人虽然不太对我的胃口，不过主人是男人，那就没问题啦！来吧来吧！",0,7.51]],"v_ckz_006.mp3":[["主人不在吗？偷偷喝上一杯……真好喝啊！",0,12.34]],"v_ckz_007.mp3":[["健康第一！受伤的时候就该好好休息嘛。嗯！",0,5.97]],"v_ckz_008.mp3":[["主人，你工作得太拼命了！",0,6.72]],"v_ckz_009.mp3":[["嘿！你该不会在数跟我一起出去玩的次数吧？",0,5.62]],"v_ckz_010.mp3":[["我正在为下一次祭典省钱呢。主人就尽管买自己喜欢的东西吧！",0,7.57]],"v_ckz_015.mp3":[["哈啊……冻凉的屁股总算暖和过来了……",0,7.143]],"v_ckz_016.mp3":[["咦？主人，突然把那东西亮出来是要干嘛？行啊，就让我喝个痛快吧！我可擅长一口气喝光了。那就开动啦！",0,20.69]],"v_ckz_024.mp3":[["主人，进来吧！今天只有咱俩，就当是在过祭典，挺好的嘛！",0,8.86]],"v_ckz_025.mp3":[["酒喝光了，我得叫筑后去买点回来。啊，主人有什么想顺便买的吗？",0,7.46]],"v_ckz_026.mp3":[["主人，你在担心什么？还不用回去吧。把其他人也叫来，再多陪我玩一会儿嘛！",0,10.66]],"v_ckz_027.mp3":[["主人，帮我系一下兜裆布吧。拉紧点……好！主人也越来越熟练了嘛。",0,8.78]],"v_ckz_028.mp3":[["喝上一杯才叫舒服嘛。主人，我也可以嘴对嘴喂你喝哦。",0,9.37]],"v_ckz_029.mp3":[["主人！醒醒醒醒，还要再喝呢！",0,8.27]],"v_ckz_030.mp3":[["哎，没办法。先喝一杯再走吧。",0,5.91]],"v_ckz_051.mp3":[["主人，你干啥呢？快过来，跟俺一块儿玩吧！",0,5.33]],"v_ecg_000.mp3":[["魂これ！",0,0.65]],"v_ecg_001.mp3":[["我是北陆道的越后！师父！我想跟您一起修炼！",0,4.98]],"v_ecg_002.mp3":[["师父！！！我太高兴了！为了表达谢意，我这就再去修炼一番！",0,4.69]],"v_ecg_003.mp3":[["啊，工作之前，我已经把身体热好了！",0,4.19]],"v_ecg_004.mp3":[["无论是谁遇到困难都要伸出援手。这就是“义”的精神！",0,3.76]],"v_ecg_005.mp3":[["呜哇！我、我可是发誓终生……的啊！",0,4.99]],"v_ecg_006.mp3":[["嗯……肚子饿了。不过越是这种时候越要耐心、耐心！",0,6.79]],"v_ecg_007.mp3":[["这点伤，完全没事儿！",0,2.355]],"v_ecg_008.mp3":[["活儿已经干完啦。",0,1.45]],"v_ecg_009.mp3":[["挺不错啊。",0,1.46]],"v_ecg_010.mp3":[["这袋米就让我来搬吧。",0,2.2]],"v_ecg_012.mp3":[["特训结束啦。咦，我……变强了！",0,5.86]],"v_ecg_013.mp3":[["唔……呜哇啊！",0,3.13]],"v_ecg_014.mp3":[["呜、呜啊啊～！哈、哈……为、为了能再请师父给我指导，我会加油的！",0,10.69]],"v_ecg_015.mp3":[["我去冲个澡。",0,1.25]],"v_ecg_016.mp3":[["师、师父！原、原来如此，这也是一种试炼吗？唔……忍耐，忍耐！",0,13.27]],"v_ecg_017.mp3":[["可恶啊！！",0,1.13]],"v_ecg_018.mp3":[["要是只来一下的话……",0,1.61]],"v_ecg_019.mp3":[["穿好了！啊，要慢一点……重穿一遍吗？",0,5.13]],"v_ecg_020.mp3":[["哟！",0,0.5]],"v_ecg_021.mp3":[["师父！",0,0.67]],"v_ecg_022.mp3":[["什么事啊？",0,2.87]],"v_ecg_023.mp3":[["呜啊啊……嗯。",0,1.98]],"v_ecg_024.mp3":[["吃太饱有点困了……师父，您慢慢休息！",0,5.26]],"v_ecg_025.mp3":[["我绝对会遵守和师父的约定！",0,3.84]],"v_ecg_026.mp3":[["那个……可以牵一下您的手吗？啊，师父！",0,7.18]],"v_ecg_027.mp3":[["师父，怎么了？想靠一下的话，我的胸膛随时借您！",0,4.38]],"v_ecg_028.mp3":[["我睡着后不管别人做什么都不会醒的。嗯……好困啊。",0,9.6]],"v_ecg_029.mp3":[["和师父两个人独处……这难道就是约会？呜哇哇！",0,7.3]],"v_ecg_030.mp3":[["该亮出特训的成果了！",0,2.44]],"v_ecg_031.mp3":[["师父，您看好了！",0,1.78]],"v_ecg_032.mp3":[["有人想要吗？",0,1.88]],"v_ecg_033.mp3":[["那是什么啊？",0,1.98]],"v_ecg_034.mp3":[["嗯……是走这边吧。",0,2.34]],"v_ecg_035.mp3":[["我会堂堂正正地上！",0,1.82]],"v_ecg_036.mp3":[["力量全开！",0,1.27]],"v_ecg_037.mp3":[["用尽全力才是礼数！",0,2.27]],"v_ecg_038.mp3":[["毗沙门天啊，赐我力量！",0,2.07]],"v_ecg_039.mp3":[["还差得远呢。",0,0.84]],"v_ecg_040.mp3":[["好一击啊！",0,1.17]],"v_ecg_041.mp3":[["厉害。接下来换我进攻了。",0,2.96]],"v_ecg_042.mp3":[["嗯……运气只能听天由命啊。",0,4.57]],"v_ecg_043.mp3":[["只有继续练下去啦！",0,1.26]],"v_ecg_044.mp3":[["看穿啦！",0,0.61]],"v_ecg_045.mp3":[["真的假的？",0,0.93]],"v_ecg_046.mp3":[["最后一击！",0,1]],"v_ecg_047.mp3":[["竟敢这样！",0,0.88]],"v_ecg_048.mp3":[["我也跟上！",0,1.05]],"v_ecg_049.mp3":[["用不着手下留情。",0,1.13]],"v_ecg_050.mp3":[["谢啦！",0,0.9]],"v_ecg_051.mp3":[["想请你陪我练练！",0,1.2]],"v_ecg_052.mp3":[["我是越国的越后！我们那儿有好吃的大米，还有那位给敌军送盐、出了名的上杉谦信！我也要多吃多练，做个有情有义的男子汉！",0,13.429]],"v_ecg_106.mp3":[["师父，圣诞快乐！今天我帮忙装饰圣诞树，还准备了晚上的宴会。好期待和师父一起干杯！",0,11.34]],"v_ecg_107.mp3":[["圣诞夜啊，那个……是个特别的夜晚吧？不过我已经有点困了……啊，怎么办，快睡着了……",0,19.98]],"v_ecg_111.mp3":[["这是神圣的夜晚啊！",0,2.47]],"v_ecg_120.mp3":[["师父，待会儿要不要一起做点锻炼？新年很容易让身体松懈嘛。之后如果还能一起去初诣，我会很开心的！",0,11.61]],"v_ecg_121.mp3":[["哦，肩膀很僵硬呢。来，师父，躺下吧。今天让我帮您从头到脚好好按摩。新年就该悠闲地休息嘛。揉揉、揉揉。",0,16.52]],"v_ecg_122.mp3":[["请尝尝越后的年糕！",0,2.33]],"v_ecg_128.mp3":[["师父，工作结束后，一起去游泳放松一下吧！放心，有我陪着您！",0,8.64]],"v_ecg_129.mp3":[["我正在做游泳前的热身，师父……能帮我扶一下身体吗？之后我也会帮您哦。",0,13.15]],"v_ecg_130.mp3":[["即使在水里也要耐心、耐心！",0,2.64]],"v_ecz_000.mp3":[["魂これ！",0,0.8]],"v_ecz_001.mp3":[["我是北陆道的越前。来吧，任命我为队长吧！我会大显身手的。",0,7.7]],"v_ecz_002.mp3":[["对我寄予了厚望啊。好啊。我会拿出成果来的。",0,5.23]],"v_ecz_003.mp3":[["人尽其才、各尽其用。要懂得用人。要不要我教教你？",0,6.48]],"v_ecz_004.mp3":[["主人，敌人的动向我已经掌握了。",0,3.46]],"v_ecz_005.mp3":[["等一下，先由我来碰你。主人，放松……对，就这样。",0,9.91]],"v_ecz_006.mp3":[["主人怎么会和其他家伙做那种事……不，别在意。",0,6.33]],"v_ecz_007.mp3":[["受了伤的我也很有魅力吧？",0,2.352]],"v_ecz_010.mp3":[["全买回去吧！",0,1.68]],"v_ecz_015.mp3":[["那我去泡一泡，回来更帅点儿。",0,2.352]],"v_ecz_016.mp3":[["哦，主人，你来啦？我帮你脱衣服。别乱动……真乖，小猫咪。",0,10.49]],"v_ecz_024.mp3":[["主人，你是来看我的吧？来，进来吧。",0,5.36]],"v_ecz_025.mp3":[["收拾得很整齐吧？打扫可是我的日常功课，所以你随时来都行。",0,6.62]],"v_ecz_026.mp3":[["能看到我这副模样的……只有主人一个人哦。",0,3.81]],"v_ecz_027.mp3":[["主人待在这里，就让我觉得你只属于我……啊，没什么。",0,6.16]],"v_ecz_028.mp3":[["今天就让你随心所欲好了。特别待遇哦。想做什么都可以。",0,7.7]],"v_ecz_029.mp3":[["主人，喂，主人！你有没有听我说话？现在只准看着我一个！",0,11.51]],"v_ecz_030.mp3":[["大伙儿，听我说！",0,2.32]],"v_ecz_051.mp3":[["来，开始吧！",0,1.67]],"v_ecz_120.mp3":[["啊，主人！嗯？被我穿和服的样子迷住了吗？新年一开始就被你热烈注视，感觉真好。来，去捣年糕吧！",0,13.05]],"v_ecz_121.mp3":[["主人，待会儿一起去初诣吧。只有我们两个人的话，许愿也更容易说出真心话吧。我希望……今后能一直和主人一起仰望那片天空。",0,18.25]],"v_ecz_122.mp3":[["大吉！哼，凭我的运气，这不是理所当然的嘛！",0,5.45]],"v_har_000.mp3":[["是魂これ呀！哇呜！",0,3.12]],"v_har_001.mp3":[["我、我是山阳道的播磨……呜汪……那、那个……我、我一定会拼命努力的……！",0,11.03]],"v_har_002.mp3":[["主人，这是我平时受您照顾的一点谢礼……！给！是粗粗的骨头零食！真的特别好吃哦！",0,9.1]],"v_har_003.mp3":[["能帮上主人的忙……啊呜，我真开心！",0,7.1]],"v_har_004.mp3":[["啊……想尿尿了。不过我还在工作……汪呜，我能忍住的！",0,12.06]],"v_har_005.mp3":[["汪呜，这是命令吗？虽然害羞……但我已经做好心理准备了。",0,11.34]],"v_har_006.mp3":[["您是我唯一的主人……我想让您更开心、更开心！汪！",0,10.09]],"v_har_007.mp3":[["不管遇到什么，只要能帮上主人，我……呜呜……",0,8.012]],"v_har_008.mp3":[["主人，请收下这个。",0,2.82]],"v_har_009.mp3":[["哇呜～主人，您好厉害呀～！",0,5.52]],"v_har_010.mp3":[["哇！这根骨头好粗，对吧！",0,7.58]],"v_har_012.mp3":[["哇呜！！我能比以前更好地保护主人啦！",0,8.02]],"v_har_013.mp3":[["呀...啊....噢....",0,4.77]],"v_har_014.mp3":[["呀、哈啊……哇呜！哈、哈……主人……还要、还要……！",0,9.22]],"v_har_015.mp3":[["哇呜！？……呜，我踩到肥皂了……",0,5.81]],"v_har_016.mp3":[["汪呜，主、主人！虽然我很开心，不过我也想帮主人洗洗身体呀！",0,10.61]],"v_har_017.mp3":[["哇呜呜呜～～！",0,3.3]],"v_har_018.mp3":[["哇呜！我会加油的！",0,2.42]],"v_har_019.mp3":[["哇呜，我穿上试了。您觉得怎么样！？",0,5.02]],"v_har_020.mp3":[["哇呜……",0,2.3]],"v_har_021.mp3":[["主人！",0,2.3]],"v_har_022.mp3":[["为、为什么？主人，怎么会？",0,3.83]],"v_har_023.mp3":[["呀……呜……哇啊啊～！",0,4.63]],"v_har_024.mp3":[["嗯，果然和我想的一样。感觉主人会来，所以我已经收拾得干干净净啦。",0,7.08]],"v_har_025.mp3":[["嚼啊嚼啊，就会平静下来。嚼啊嚼。",0,4.77]],"v_har_026.mp3":[["主人，您身上好像有股好闻的味道。嗅嗅……是从这边飘来的。嗅嗅。",0,9.65]],"v_har_027.mp3":[["主人，要去洗手间吗？我、我也一起去！",0,5.83]],"v_har_028.mp3":[["主人，我好像也快要……了！汪呜！",0,8.14]],"v_har_029.mp3":[["汪呜，漏出来了！我马上收拾……呜……",0,5.7]],"v_har_030.mp3":[["哇，洒出来了。我这就收拾……",0,5.7]],"v_har_030_1.mp3":[["汪！我会努力的！",0,2.3]],"v_har_031.mp3":[["我想到了一个好战法。",0,3.15]],"v_har_032.mp3":[["哇呜？这是什么呀……嗅嗅。",0,5.07]],"v_har_033.mp3":[["我、我好像知道了……",0,3.37]],"v_har_034.mp3":[["哇呜～好香……",0,3.31]],"v_har_035.mp3":[["大家，为了主人加油呀。",0,3.92]],"v_har_036.mp3":[["我要上啦～！",0,1.3]],"v_har_037.mp3":[["弱点在这儿吗？",0,1.96]],"v_har_038.mp3":[["我要瞄准要害啦！",0,1.94]],"v_har_039.mp3":[["哇、哇呜……",0,1.62]],"v_har_040.mp3":[["我被打中了。",0,1.43]],"v_har_041.mp3":[["偏偏在这种时候，我快憋不住尿了。",0,4.96]],"v_har_042.mp3":[["呜哇，主人，对不起。",0,4.91]],"v_har_043.mp3":[["主、主人！我、我……！哇呜～～！",0,6.48]],"v_har_044.mp3":[["和我想的一样。",0,1.35]],"v_har_045.mp3":[["哇呜！？",0,0.61]],"v_har_046.mp3":[["和作战计划一样呢。",0,1.53]],"v_har_047.mp3":[["危险呀！",0,1.08]],"v_har_048.mp3":[["我饶不了你。",0,1.45]],"v_har_049.mp3":[["一锤定音！",0,1.24]],"v_har_050.mp3":[["谢谢您。",0,1.09]],"v_har_051.mp3":[["主人，快点，快点呀！",0,5.92]],"v_har_052.mp3":[["我是山阳道、播州的播磨！我们有名的是不战之城白鹭城，也就是姬路城！还有、还有，我最崇拜那四十七位义士！他们为报主仇而战……我也想当那样的忠犬！",0,21.88]],"v_har_120.mp3":[["汪呜！新年有好多想做的事呢。首先要和主人一起抽神签！一定能抽到大吉！",0,11.42]],"v_har_121.mp3":[["汪呜，主人！我明明下定决心，今年一定要好好忍住的……结果第一次做新年梦，就尿出来了！",0,13.85]],"v_har_122.mp3":[["新年快乐汪！",0,1.82]],"v_har_123.mp3":[["主人，我也想穿新年衣服。然后、然后，想跟您一起去新年参拜。",0,9.55]],"v_har_128.mp3":[["游泳圈真厉害呀！就算进了水也不会沉下去！",0,5.35]],"v_har_129.mp3":[["光是漂在水上就很好玩了！汪！",0,5.84]],"v_har_130.mp3":[["哇，缝隙……要淹死啦！",0,3.77]],"v_har_131.mp3":[["就算不会游泳也没关系呀。",0,2.09]],"v_hit_000.mp3":[["魂これ！",0,0.92]],"v_hit_001.mp3":[["东海道，常陆。……………………没别的可说了。",0,8.49]],"v_hit_002.mp3":[["……又选了我啊………………算了，我就陪陪你吧。",0,6.83]],"v_hit_003.mp3":[["嗯？什么事？",0,2.08]],"v_hit_004.mp3":[["是我的毛发乱了吗？",0,2.38]],"v_hit_005.mp3":[["住手。趁大鲶鱼还没闹腾起来之前……",0,5.74]],"v_hit_006.mp3":[["哦，肚子饿了。",0,2.92]],"v_hit_007.mp3":[["这点连伤都算不上。",0,1.293]],"v_hit_008.mp3":[["结束了。",0,0.72]],"v_hit_009.mp3":[["结果并不代表一切。把精神提起来。",0,2.93]],"v_hit_010.mp3":[["能吃的东西……哦，还真有啊。",0,4.22]],"v_hit_012.mp3":[["还……不够……再来！",0,4.37]],"v_hit_013.mp3":[["唔、唔……",0,1.93]],"v_hit_014.mp3":[["唔……我在最深处感受到了你。求你，再多一点。",0,9.24]],"v_hit_015.mp3":[["热水溢出来了。",0,2.55]],"v_hit_016.mp3":[["抱歉，太挤了吗？过来，我抱着你。这样如何？",0,13.27]],"v_hit_017.mp3":[["……来吧。",0,0.63]],"v_hit_018.mp3":[["要上了。",0,0.69]],"v_hit_019.mp3":[["不知道穿不穿得下。",0,1.68]],"v_hit_020.mp3":[["嗯。",0,0.55]],"v_hit_021.mp3":[["是你啊。",0,0.73]],"v_hit_022.mp3":[["什……干、干什么？",0,2.38]],"v_hit_023.mp3":[["唔、呃……",0,0.87]],"v_hit_024.mp3":[["主人，先脱鞋。嗯，随便坐……给。",0,9.72]],"v_hit_025.mp3":[["你真的喜欢这样的我吗？真的？……是吗。",0,8.73]],"v_hit_026.mp3":[["想看远处的话，我可以让你骑在肩上。",0,4.35]],"v_hit_027.mp3":[["你的身体……真小，又柔软。",0,4.94]],"v_hit_028.mp3":[["唔……刺激太强了。",0,4.01]],"v_hit_029.mp3":[["要是闲着，不如去筑波山参加歌垣吧？",0,5.14]],"v_hit_030.mp3":[["知道了。",0,0.74]],"v_hit_031.mp3":[["走吧。",0,0.53]],"v_hit_032.mp3":[["带回去。",0,0.76]],"v_hit_033.mp3":[["别动。",0,0.7]],"v_hit_034.mp3":[["这边。",0,0.63]],"v_hit_035.mp3":[["堂堂正正决胜负吧。",0,2.47]],"v_hit_036.mp3":[["哈啊！",0,0.85]],"v_hit_037.mp3":[["你这混蛋！",0,0.92]],"v_hit_038.mp3":[["斩！",0,0.6]],"v_hit_039.mp3":[["唔。",0,0.53]],"v_hit_040.mp3":[["啧！",0,0.72]],"v_hit_041.mp3":[["真正的较量现在才开始。",0,0.84]],"v_hit_042.mp3":[["抱歉……",0,0.67]],"v_hit_043.mp3":[["给我……？哦、哦……给别人吧。",0,6.09]],"v_hit_044.mp3":[["好！",0,0.65]],"v_hit_045.mp3":[["唔！",0,0.54]],"v_hit_046.mp3":[["就从你开始！",0,1.03]],"v_hit_047.mp3":[["别松懈。",0,0.85]],"v_hit_048.mp3":[["收尾还差得远呢！",0,1.07]],"v_hit_049.mp3":[["最后一下。",0,0.73]],"v_hit_050.mp3":[["好啊！",0,0.48]],"v_hit_051.mp3":[["嗯，走吧。",0,1.62]],"v_hit_052.mp3":[["我是常州、衣手的常陆。这里的纳豆很出名。古代这里是朝廷戒备北方的最前线，位置很重要。我和下总打交道很久了，鹿岛和香取还有鲶鱼的传说。要石的形状……？纯属巧合。",0,28.78]],"v_hit_120.mp3":[["风吹得不错。出去吧，我们去放风筝。别担心，我会扶着你的。",0,14.47]],"v_hit_121.mp3":[["还要再添一碗杂煮吗？新年就由我来下厨。还有吉祥的配菜。怎么样，好吃吧？",0,11.59]],"v_hit_122.mp3":[["恭贺新年……嗯……",0,3.62]],"v_hit_128.mp3":[["这就是泳装啊……冷静点。什么？别老盯着我看。",0,9.31]],"v_hit_129.mp3":[["哼，差不多该走了。嗯？当然是去海边。快去准备。",0,10.24]],"v_hit_130.mp3":[["游泳……",0,0.97]],"v_hiz_000.mp3":[["魂これ！",0,1]],"v_hiz_001.mp3":[["你好呀，主人。我是西海道的肥前。放心吧！我一定会把主人照顾得妥妥帖帖的。",0,10.25]],"v_hiz_002.mp3":[["哇哇，你穿的这是什么样子呀！果然主人没我照顾就不行呢。",0,6.46]],"v_hiz_003.mp3":[["主人，小心别让小脚趾撞到桌角哦。",0,4.57]],"v_hiz_004.mp3":[["吵架这种事，我绝对不能坐视不管！",0,2.65]],"v_hiz_005.mp3":[["啊！你在摸哪里呀？！",0,2.5]],"v_hiz_006.mp3":[["趁现在把杂务处理掉吧。",0,2.21]],"v_hiz_007.mp3":[["大家都怎么样了？",0,2.97]],"v_hiz_008.mp3":[["主人的工作得到认可了哦。",0,2.5]],"v_hiz_009.mp3":[["别得意，一步一步踏实来……对吧！",0,3.59]],"v_hiz_010.mp3":[["进口货也很重要呢。",0,1.6]],"v_hiz_012.mp3":[["主人的安危就交给我守护。",0,3.02]],"v_hiz_013.mp3":[["呜哇啊啊！",0,2.21]],"v_hiz_014.mp3":[["呜哇～～！唔、呼……是挺害羞的……可我对主人您，已经没什么好隐瞒的了。",0,15]],"v_hiz_015.mp3":[["能把水调凉一点吗……",0,2.86]],"v_hiz_016.mp3":[["啊……我好像有点兴奋了。是因为和主人离得这么近吗？",0,11.64]],"v_hiz_017.mp3":[["对我温柔点哦。",0,2.72]],"v_hiz_018.mp3":[["要、要是疼的话，就告诉我哦。",0,3.19]],"v_hiz_019.mp3":[["小心别露出来……",0,2.49]],"v_hiz_020.mp3":[["怎么了？",0,1.3]],"v_hiz_021.mp3":[["哟，主人。",0,2.02]],"v_hiz_022.mp3":[["哇啊！",0,0.85]],"v_hiz_023.mp3":[["哈啊……！",0,1.31]],"v_hiz_024.mp3":[["主人，来我的房间好好放松一下吧。",0,3.45]],"v_hiz_025.mp3":[["主人，把手伸出来。我来给你涂点乳霜吧。",0,4.86]],"v_hiz_026.mp3":[["又长又粗，还这么气派……真有那么好吗？我这鼻子。",0,7.01]],"v_hiz_027.mp3":[["啊，主人，内裤露出来了！嗯，好了。仪容仪表可得整理好哦。",0,8.47]],"v_hiz_028.mp3":[["呜……我、我还不习惯……说不定会忍不住一下子喷出来……！",0,7.93]],"v_hiz_029.mp3":[["能够照顾主人，我真的很幸福。",0,4.81]],"v_hiz_030.mp3":[["好，大家排好队。",0,2.349]],"v_hiz_031.mp3":[["我来带领大家。",0,1.55]],"v_hiz_032.mp3":[["好像派得上用场。",0,0.93]],"v_hiz_033.mp3":[["提高警惕。",0,0.83]],"v_hiz_034.mp3":[["没落下东西吧？走啦。",0,3.05]],"v_hiz_035.mp3":[["小心别受伤哦。",0,1.4]],"v_hiz_036.mp3":[["瞄准完毕，开火！",0,2.07]],"v_hiz_037.mp3":[["嘿呀！",0,0.78]],"v_hiz_038.mp3":[["哇啊，我忍不了了！",0,3.04]],"v_hiz_039.mp3":[["呜啊！",0,0.59]],"v_hiz_040.mp3":[["住手啊！",0,0.87]],"v_hiz_041.mp3":[["我不想这样互相伤害啊。",0,4.62]],"v_hiz_042.mp3":[["呜……先撤退一阵吧。",0,4.14]],"v_hiz_043.mp3":[["谢谢。不过可以的话，我还是想阻止这场战斗。",0,5.81]],"v_hiz_044.mp3":[["搞定了！",0,1.07]],"v_hiz_045.mp3":[["大家冷静一下！",0,1.26]],"v_hiz_046.mp3":[["就是你！",0,0.79]],"v_hiz_047.mp3":[["没受伤吧？",0,0.92]],"v_hiz_048.mp3":[["我来掩护射击。",0,1.24]],"v_hiz_049.mp3":[["再加把劲。",0,0.91]],"v_hiz_050.mp3":[["谢谢！",0,0.83]],"v_hiz_051.mp3":[["来，先做个腹式呼吸吧。",0,4.12]],"v_hiz_052.mp3":[["我是火之国的肥前。「萨长土肥」里的「肥」就是我。我最先在日本发展出不少技术，也曾被称作幕末最强的军事力量。武藏好像也挺认可我的，我很高兴哦。",0,18.28]],"v_hiz_128.mp3":[["大象很擅长游泳哦。在水里也能把鼻子伸出水面。下次展示给你看！",0,10.36]],"v_hiz_129.mp3":[["主人也要去游泳吗？那得先涂防晒油，再伸展身体。万一溺水可不得了，游泳圈也得准备好！",0,13.56]],"v_hiz_130.mp3":[["在水边跑来跑去会受伤哦。",0,2.5]],"v_hou_000.mp3":[["魂これ！",0,1.22]],"v_hou_001.mp3":[["哦，老子就是山阴道的伯耆。你这家伙……身材挺不错的嘛。看来以后有不少乐子了。嘿嘿嘿。",0,11.48]],"v_hou_002.mp3":[["都说了别来拜托老子！啧——麻烦死了。不过既然这样，相应的报酬，老子可以期待一下吧？　嘿嘿。",0,10.44]],"v_hou_003.mp3":[["哎呀，抱歉抱歉，不小心碰到你了。嗯？你这家伙还真有一对好东西嘛。嘿嘿嘿。",0,9.87]],"v_hou_004.mp3":[["先说好，我只会为了自己而行动。",0,6.21]],"v_hou_005.mp3":[["哦，困意一下就没了！你也挺喜欢这种事嘛。来，好好享受吧！",0,9]],"v_hou_006.mp3":[["偷懒时抽上一口，简直爽翻了。",0,8.61]],"v_hou_007.mp3":[["别、别这样！别用那种怜悯的眼神看我！我才不稀罕别人帮忙呢！",0,8.407]],"v_hou_010.mp3":[["啧，真麻烦。嗯？这不就是把好刀吗？",0,6.19]],"v_hou_015.mp3":[["有没有可爱的小家伙帮我洗洗呀？",0,3.255]],"v_hou_016.mp3":[["怎么，你要帮我洗身子？嗯……你比想象中主动嘛，受不了啦！就这样一起裹满泡泡吧！",0,17.81]],"v_hou_024.mp3":[["先说好，我这里可脏得很，不过就是个工坊。要是不嫌弃的话，可以来我身边坐。",0,12.02]],"v_hou_025.mp3":[["喂，再靠近点嘛。怎么样？你不是很喜欢这样吗？",0,8.2]],"v_hou_026.mp3":[["想事情时，最适合一边生火一边摆弄手里的活儿。别碰我的工具啊，弄伤了可别怪我。",0,9.77]],"v_hou_027.mp3":[["哈……真想只做开心的事，一直这么活下去啊。",0,6.99]],"v_hou_028.mp3":[["痛快了，我要睡啦。晚安。",0,11.59]],"v_hou_030.mp3":[["真的啊？行，那就拜托了。",0,4.94]],"v_hou_051.mp3":[["啊，不是要开始了吗？真是的，报酬就让你用身体来付吧。嘿嘿。",0,8.89]],"v_hyu_000.mp3":[["魂これ！",0,1.48]],"v_hyu_001.mp3":[["哎呀呀……我是西海道的日向。为了庆祝我们的相遇，喝一杯怎么样？My master。",0,11.39]],"v_hyu_002.mp3":[["多次相逢……这或许是命运的安排呢。我是这么觉得的。",0,9.04]],"v_hyu_003.mp3":[["请抬起头来。那种表情可不适合您。",0,6.14]],"v_hyu_004.mp3":[["我这就为您准备一杯特别的饮品。",0,3.39]],"v_hyu_005.mp3":[["哎呀，若是连这点事都承受不了，岂不是有损绅士的名声？来，请到这边。",0,9.36]],"v_hyu_006.mp3":[["差不多该到下午茶时间了吧。",0,2.61]],"v_hyu_007.mp3":[["唔，不行了……我只能到这儿了……没能帮上忙，实在抱歉……",0,10.503]],"v_hyu_010.mp3":[["请问这里有酒吗？",0,2.34]],"v_hyu_015.mp3":[["小小的浴池，真让人放松啊……",0,4.056]],"v_hyu_016.mp3":[["我亲爱的主人，我已经用毛发把肥皂搓出泡沫了。来吧，让我将您全身轻轻包裹起来。",0,11.42]],"v_hyu_024.mp3":[["您来到我的房间，就意味着……可以吧？看来今晚会很愉快呢。",0,8.67]],"v_hyu_025.mp3":[["来喝一杯如何？至少在这一杯酒的时间里，能把您留在身边。",0,6.51]],"v_hyu_026.mp3":[["这可不妙，难得喝得有些醉了。毕竟正和你单独相处，倒也难怪。",0,11.3]],"v_hyu_027.mp3":[["来，枕着我的手臂吧。睡得舒服吗？",0,4.36]],"v_hyu_028.mp3":[["主人可真有精神……我的体力倒是要撑不住了，真抱歉。",0,10.82]],"v_hyu_029.mp3":[["这样一张天真无邪的睡脸，竟然是拯救世界的主人……真令人怜爱。",0,11.02]],"v_hyu_030.mp3":[["是要打仗吗？",0,2.14]],"v_hyu_051.mp3":[["大人的时间开始了呢。",0,2.98]],"v_hyu_106.mp3":[["欢迎光临日向酒吧。能够穿着正装迎接您，我很高兴。",0,9.29]],"v_hyu_107.mp3":[["请再来一杯。这杯我请客。啊，酒是不是太烈了？",0,11.33]],"v_hyu_111.mp3":[["欢迎光临。",0,1.29]],"v_hyu_128.mp3":[["阳光好像很刺眼呢。要我帮您涂防晒油吗，我的主人？",0,7.64]],"v_hyu_129.mp3":[["真想喝杯冰啤酒啊。来，轮到您了。让我也看看您可爱的泳装吧。",0,9.24]],"v_hyu_130.mp3":[["抱歉，我的腿抽筋了。",0,3.03]],"v_iga_000.mp3":[["魂これ！",0,1.2]],"v_iga_001.mp3":[["我是东海道的伊贺。你就是我的主人？拿多少工资，我就做多少事。好了，契约成立。",0,12.79]],"v_iga_002.mp3":[["这是……加薪？可以。与这份薪水相称的工作表现，就请拭目以待吧。",0,7.3]],"v_iga_003.mp3":[["需要的情报我已经全部搜集好了。",0,3.2]],"v_iga_004.mp3":[["只要报酬合适，什么服务我都可以考虑哦。",0,4.68]],"v_iga_005.mp3":[["接下来的部分可要另收费了。不过我保证能让主人满意。",0,8.42]],"v_iga_006.mp3":[["吃饭啦……嗯……啊，好幸福。",0,8.37]],"v_iga_007.mp3":[["干砸的那份，就从我工钱里扣吧。",0,4.202]],"v_iga_008.mp3":[["嗯。",0,1.2]],"v_iga_009.mp3":[["文件在这里。",0,1.74]],"v_iga_010.mp3":[["啊，好香，闻起来真好吃……",0,8.29]],"v_iga_012.mp3":[["这倒是……不错。",0,3.28]],"v_iga_013.mp3":[["嗯、嗯嗯……",0,3.26]],"v_iga_014.mp3":[["唔……怎么样，我的房中术？……嗯……下次也请叫我来。",0,8.22]],"v_iga_015.mp3":[["我马上洗好出来。",0,1.25]],"v_iga_016.mp3":[["报酬确实收到了。来，在那里躺好，我会替您仔仔细细洗干净的。原来这里最舒服啊。",0,12.38]],"v_iga_017.mp3":[["就照这样。",0,2.2]],"v_iga_018.mp3":[["怎么样？",0,1.2]],"v_iga_019.mp3":[["主人，您的品味真特别。",0,2.25]],"v_iga_020.mp3":[["什么事？",0,1.2]],"v_iga_021.mp3":[["主人？",0,1.2]],"v_iga_022.mp3":[["啊，呃，这个、那个……",0,4.5]],"v_iga_023.mp3":[["哈呜……",0,1.2]],"v_iga_024.mp3":[["不是谁都能进来的。因为主人是特别的嘛。",0,5.21]],"v_iga_025.mp3":[["要和你发展超出工作的关系，我有点害怕……不过，如果是你的话……",0,7.69]],"v_iga_026.mp3":[["我觉得……即使为你豁出性命也值得。我是认真的。",0,10.41]],"v_iga_027.mp3":[["今天……你想怎样都可以。",0,3.72]],"v_iga_028.mp3":[["工作的事……现在都不重要了。请……过来。",0,10.11]],"v_iga_029.mp3":[["啊，肚子饿了。",0,5.09]],"v_iga_030.mp3":[["多谢。",0,1.2]],"v_iga_031.mp3":[["我不会饶过叛徒。明白了吗？",0,3.9]],"v_iga_032.mp3":[["那我就收下了。",0,1.2]],"v_iga_033.mp3":[["先看看情况吧。",0,1.2]],"v_iga_034.mp3":[["临兵斗者皆阵列在前。走这边。",0,4.48]],"v_iga_035.mp3":[["确认目标，任务开始。",0,2.76]],"v_iga_036.mp3":[["你的首级，我收下了。",0,2.34]],"v_iga_037.mp3":[["请你去死。",0,1.2]],"v_iga_038.mp3":[["再见。",0,1.2]],"v_iga_039.mp3":[["没有问题。",0,1.2]],"v_iga_040.mp3":[["唔！",0,1.2]],"v_iga_041.mp3":[["这差事可真不划算。",0,2.2]],"v_iga_042.mp3":[["我下次再来。",0,1.2]],"v_iga_043.mp3":[["这是不是说，我能拿奖金了？",0,3.55]],"v_iga_044.mp3":[["忍法，替身术。",0,2.34]],"v_iga_045.mp3":[["就这点程度。",0,1.2]],"v_iga_046.mp3":[["到此为止了。",0,1.2]],"v_iga_047.mp3":[["不。",0,1.2]],"v_iga_048.mp3":[["这边。",0,1.2]],"v_iga_049.mp3":[["你是最后一个。",0,1.5]],"v_iga_050.mp3":[["请收下这份谢礼。",0,1.2]],"v_iga_051.mp3":[["钱我确实收到了。",0,1.36]],"v_iga_052.mp3":[["我是伊州的伊贺。从畿内走东海道，必定会经过伊贺国，所以大家以前都会到这里雇忍者。唯独尾张，就算拿再多钱来，我也没法跟他和好。",0,19.3]],"v_iga_120_1.mp3":[["我在新年礼服下面藏了各种暗器，您可以放心。想检查一下也没关系哦。",0,9.82]],"v_iga_121_1.mp3":[["主人，难得过新年，慢慢休息吧。我带了好多年糕来。我也会陪着你的。",0,15.67]],"v_iga_122_1.mp3":[["新年快乐。",0,2.21]],"v_iga_128.mp3":[["我的家乡虽然在内陆，但水中训练可没落下。还有各种操纵水的忍术呢。所以……来，让你淋个透湿吧！",0,15.24]],"v_iga_129.mp3":[["主人，海里有很多危险哦。要是主人遇到溺水事故，嗯，那个……我也能做人工呼吸……要、要试试看吗？",0,20.3]],"v_iga_130.mp3":[["水遁之术！不，应该说是水蜘蛛之术吧？",0,5.3]],"v_iki_000.mp3":[["魂これ！",0,0.68]],"v_iki_001.mp3":[["久等啦。我是西海道的壹岐！冒险的准备都做好啦。快点出发吧，团长！",0,9.92]],"v_iki_002.mp3":[["团长，我回来啦！刚才到各处冒险了一番哦。有很多想给你看看的东西呢！嘿嘿。",0,9.62]],"v_iki_003.mp3":[["团长，我把找到的东西摆在这里啦！我要把工作室变成宝物堆成的山！",0,8.12]],"v_iki_004.mp3":[["有什么我能帮忙的吗？早点完成工作，我们一起出去玩嘛！",0,5.84]],"v_iki_005.mp3":[["团、团长……那、那个……不，果然你的手法有点奇怪吧？唔……",0,12.42]],"v_iki_006.mp3":[["为了让团长随时都能出发冒险，我先把行李收拾好吧！",0,5.89]],"v_iki_007.mp3":[["呜呜，疼疼疼疼……唉，不过冒险哪能没点危险呢。",0,8.656]],"v_iki_010.mp3":[["对了，得补点冒险用的消耗品！这个、还有这个……嗯，齐活啦！",0,9.86]],"v_iki_015.mp3":[["啊，好暖和……全身都放松下来了。",0,7.236]],"v_iki_015_1.mp3":[["啊，好暖和……全身都放松下来了。",0,7.27]],"v_iki_016.mp3":[["团长，一起进来吧！诶，要帮我揉脚吗？啊，脚……好痛啊！哈哈！",0,14.16]],"v_iki_024.mp3":[["团长，欢迎来到我的房间！这里到处都是我喜欢的东西，你一定会玩得开心！",0,7.81]],"v_iki_025.mp3":[["这是我的冒险记录本，里面也记下了和团长一起的回忆。有点不好意思，不过要看看吗？嘿嘿。",0,11.79]],"v_iki_026.mp3":[["我头上那些尖尖的……其实是海胆胸针啦。团长想要的话就送你！哦，很适合嘛！",0,11.08]],"v_iki_027.mp3":[["唔，为了下一次冒险，得好好休息。团长也一起睡嘛，把我当枕头也没关系……嗯，好像能睡着了。",0,21.9]],"v_iki_028.mp3":[["这种事我不太懂……但并不讨厌。因为对象是团长吧。嗯。",0,12.62]],"v_iki_029.mp3":[["下次去哪里好呢？我要找个团长会喜欢的地方！",0,5.68]],"v_iki_030.mp3":[["会有怎样的冒险呢？",0,2.18]],"v_iki_051.mp3":[["团长，一起去冒险吧！",0,3.45]],"v_iki_120.mp3":[["团长，新年到啦！我想吃年节菜、去初诣，还有好多想做的事。先干什么好呢？嘿嘿！",0,13.61]],"v_iki_121.mp3":[["偶尔不冒险，悠闲地睡上一觉也不错嘛，尤其是过年。团长，挨着我一起睡吧……",0,20.03]],"v_iki_122.mp3":[["恭贺新年！",0,1.35]],"v_ina_000.mp3":[["魂これ啦！",0,1.15]],"v_ina_001.mp3":[["我是山阴道的因幡！呃、那个、那个……总、总之请多关照啦！",0,8.56]],"v_ina_002.mp3":[["那个……你又叫我来，我真的很高兴啦！",0,2.93]],"v_ina_003.mp3":[["我该干什么？你来决定吧！",0,3.85]],"v_ina_004.mp3":[["咦？我只是一直在看着你而已。",0,2.4]],"v_ina_005.mp3":[["啊，那种事可不行……嗯，不过，果然还是可以啦！",0,8.62]],"v_ina_006.mp3":[["真希望有人教我，怎么才能帮上更多忙！",0,3.72]],"v_ina_007.mp3":[["到底怎么才能变强呢？真让人发愁。",0,3.799]],"v_ina_008.mp3":[["这是什么呀？主人，来这边。",0,3.11]],"v_ina_009.mp3":[["那个，这、这算是好结果吗？",0,9.73]],"v_ina_010.mp3":[["嗯……我也不知道想要哪个。",0,3.27]],"v_ina_012.mp3":[["发、发、发生什么了？好厉害啊！",0,5.3]],"v_ina_013.mp3":[["呜……唔……",0,2.28]],"v_ina_014.mp3":[["嗯、啊……呼、哈……脑袋还迷迷糊糊的。主人，真舒服啊，谢谢你。",0,13.66]],"v_ina_015.mp3":[["先泡再洗，还是先洗再泡呢……阿嚏！",0,7.39]],"v_ina_016.mp3":[["原来主人喜欢从那里开始洗啊。也要帮我洗全身？那我就全交给你啦！",0,7.85]],"v_ina_017.mp3":[["嘿嘿嘿，真厉害啊……",0,2.52]],"v_ina_018.mp3":[["怎、怎么样？",0,2.08]],"v_ina_019.mp3":[["你觉得这件更好，那就这件吧。",0,2.91]],"v_ina_020.mp3":[["怎么啦？",0,1.03]],"v_ina_021.mp3":[["主人——！",0,1.03]],"v_ina_022.mp3":[["你要是能装作没看见，我就太高兴啦。",0,3.59]],"v_ina_023.mp3":[["呜哇～！",0,0.97]],"v_ina_024.mp3":[["主人……呃，总之先请进吧！",0,4.55]],"v_ina_025.mp3":[["你总是夸奖我……真的让我很感动。",0,3.43]],"v_ina_026.mp3":[["啊……只要和你在一起，做什么都开心！",0,8.29]],"v_ina_027.mp3":[["啊啊，有点困了。我一向早睡早起嘛。",0,8.37]],"v_ina_028.mp3":[["主、主人……呃，接下来做什么，由你来决定就好啦……诶嘿。",0,10.9]],"v_ina_029.mp3":[["交给主人决定就好了吧？嘿嘿。",0,2.88]],"v_ina_030.mp3":[["主人让我加入这支队伍……",0,1.95]],"v_ina_031.mp3":[["当队长该做点什么呢？",0,3.95]],"v_ina_032.mp3":[["嗯……该怎么办才好？",0,3.02]],"v_ina_033.mp3":[["喂，那个是什么呀？",0,2]],"v_ina_034.mp3":[["走哪边呢？投票决定吧。",0,4.91]],"v_ina_035.mp3":[["原来是这样的战术啊。我觉得不错！",0,3.36]],"v_ina_036.mp3":[["果然还是选这边吧。",0,2.07]],"v_ina_037.mp3":[["我可以攻击了吗？",0,2.12]],"v_ina_038.mp3":[["明白了！我瞄准这家伙！",0,2.13]],"v_ina_039.mp3":[["好疼！",0,1.23]],"v_ina_040.mp3":[["哇啊！",0,0.75]],"v_ina_041.mp3":[["我是不是该遮一遮？",0,4.27]],"v_ina_042.mp3":[["抱歉。我还想再变强一点。",0,4.47]],"v_ina_043.mp3":[["太好了！我下次会更努力的！",0,3.28]],"v_ina_044.mp3":[["太好啦！",0,1.71]],"v_ina_045.mp3":[["怎么办呀。",0,1.04]],"v_ina_046.mp3":[["嗯...哼",0,1.06]],"v_ina_047.mp3":[["这样啊。",0,1.09]],"v_ina_048.mp3":[["就是这个。",0,1.28]],"v_ina_049.mp3":[["接下来就……",0,0.905]],"v_ina_050.mp3":[["谢谢！",0,0.89]],"v_ina_051.mp3":[["要、要开始啦！",0,2.47]],"v_ina_052.mp3":[["我是山阴道、因州的因幡！人们说因幡多雨，这儿有个很有名的「伞舞」呢！我跟伯耆关系很好哦！",0,10.51]],"v_ina_120.mp3":[["谨贺新年！希望主人过个好年，我会一直守护着你的！",0,10.97]],"v_ina_121.mp3":[["主人去初诣许了什么愿？我想了好多，写满了一张纸，却不知道选哪个。主人觉得哪个比较好？",0,12.53]],"v_ina_122.mp3":[["新年快乐！",0,1.56]],"v_ina_123.mp3":[["主人，今年是兔年呀。所以、那个……能让我穿那件衣服吗？嘿嘿。",0,13.08]],"v_ina_128.mp3":[["主人，天气真好！那个……要、要是你愿意，一起去游泳吧！嘿嘿。",0,15.2]],"v_ina_129.mp3":[["哇，主人，你都晒脱皮了！这时候涂点药膏就好啦。来，我帮你涂，不疼的！",0,13.5]],"v_ina_130.mp3":[["大家一起去游泳吧！",0,2.11]],"v_iwm_000.mp3":[["魂これ！",0,0.73]],"v_iwm_001.mp3":[["呼——！俺是山阴道的石见。那，咱要从哪儿开挖？",0,5.67]],"v_iwm_002.mp3":[["哟，你又叫俺来了啊。那就不辜负你的期待，俺要铆足劲儿挖啦！",0,6.5]],"v_iwm_003.mp3":[["好！今天就从这里挖洞。你站那儿危险，退后点。",0,6.32]],"v_iwm_004.mp3":[["你的工作我来搭把手吧。没什么，就当回报你平时的照顾。",0,5.73]],"v_iwm_005.mp3":[["哈哈，你摸哪里呢？喂，要开始啦！",0,5.57]],"v_iwm_006.mp3":[["出了不少汗，脱下来凉快凉快吧。",0,3.76]],"v_iwm_007.mp3":[["嗯？俺可没那么娇气，这点伤还犯不着嚎呢。",0,4.361]],"v_iwm_008.mp3":[["嗯，好像已经干完了。",0,2.18]],"v_iwm_009.mp3":[["你挺努力的嘛。",0,2.51]],"v_iwm_010.mp3":[["哇，最新的工具真有派头啊。",0,5.22]],"v_iwm_012.mp3":[["哦，这感觉可真不错啊。",0,4.14]],"v_iwm_013.mp3":[["啊，等、等一下，不行……啊啊啊……！",0,4.67]],"v_iwm_014.mp3":[["啊！等等，不行……啊啊！哈、哈……哎，这种事真吓到俺了。……别跟别人讲哦。",0,9.95]],"v_iwm_015.mp3":[["啊，好舒服的澡。脚能踩到底，真是太好了。",0,7.23]],"v_iwm_016.mp3":[["能帮我搓搓背吗？谢啦！……怎么净摸那些奇怪的地方呀？",0,7.8]],"v_iwm_017.mp3":[["啊啊～～！",0,2.24]],"v_iwm_018.mp3":[["俺要挖喽。",0,1]],"v_iwm_019.mp3":[["多谢啊。看，俺脱好了，这就试穿新的。",0,5.15]],"v_iwm_020.mp3":[["咋了？",0,0.52]],"v_iwm_021.mp3":[["是你啊。",0,0.94]],"v_iwm_022.mp3":[["真难为情啊。",0,4.7]],"v_iwm_023.mp3":[["哇！？啊哈哈，怪难为情的啊。",0,3.29]],"v_iwm_024.mp3":[["哟，你来啦！别客气，进来吧，慢慢坐着歇会儿！",0,5.09]],"v_iwm_025.mp3":[["在房间里我就穿这条兜裆布，别在意。要喝点什么吗？",0,6.5]],"v_iwm_026.mp3":[["啊，对了，下次大家要一起出去玩，你也来吧？",0,6.2]],"v_iwm_027.mp3":[["怎么啦？老盯着那种地方看……我也会害羞的啊。",0,7.65]],"v_iwm_028.mp3":[["嗯？干嘛摸那里？咱们关系这么好，倒也不是不行啦。",0,9.65]],"v_iwm_029.mp3":[["和主人待在一起的时候，至少也该把灰尘掸掉吧？我去洗把脸。",0,6.48]],"v_iwm_030.mp3":[["好嘞，从哪儿开挖呢？",0,1.79]],"v_iwm_031.mp3":[["那我去去就回来。",0,2.26]],"v_iwm_032.mp3":[["挖到啦？",0,1.8]],"v_iwm_033.mp3":[["那边的地面有点不对劲啊。",0,2.85]],"v_iwm_034.mp3":[["俺这挖矿人的直觉。",0,2]],"v_iwm_035.mp3":[["打仗啦。大伙儿，提起精神。",0,3.73]],"v_iwm_036.mp3":[["俺来收拾你。",0,1.3]],"v_iwm_037.mp3":[["赶紧回去吧。",0,1.6]],"v_iwm_038.mp3":[["正是挖你的好时候啊。",0,1.9]],"v_iwm_040.mp3":[["没碍事。",0,1.6]],"v_iwm_041.mp3":[["是有点累了，可俺还挖得动呢。",0,3.28]],"v_iwm_042.mp3":[["呜……矿山要关了……",0,3.44]],"v_iwm_043.mp3":[["嗯，这点事儿算不了什么。",0,3.41]],"v_iwm_044.mp3":[["好！",0,1]],"v_iwm_045.mp3":[["能行啊。",0,1.64]],"v_iwm_046.mp3":[["就是这儿吧。",0,1.3]],"v_iwm_047.mp3":[["住手。",0,1.3]],"v_iwm_048.mp3":[["好嘞！",0,1]],"v_iwm_049.mp3":[["再见啦！",0,1.3]],"v_iwm_050.mp3":[["多谢啊。",0,1.01]],"v_iwm_051.mp3":[["来，你也跟俺一块儿挖洞吧。",0,3.63]],"v_iwm_052.mp3":[["俺是石州的石见。说起石见，果然还是银山。鼎盛时，日本出产的银差不多占全世界三分之一，其中大部分都来自石见，所以才有了「银矿王国」的称呼。伯耆是俺以前共事过的老朋友。",0,25.64]],"v_iwm_120.mp3":[["今年也想和你留下好多新的回忆。一定会是个好年头的，我可是这么祈祷着呢。",0,8.54]],"v_iwm_121.mp3":[["大过年的，赖床也不错。来，我给你当臂枕，躺过来……咦，怎么反倒是我自己困了呢？",0,19.83]],"v_iwm_122.mp3":[["去抽个神签吧？",0,2.04]],"v_iwm_123.mp3":[["恭贺新年！过年也一块儿挖洞吧！",0,4.73]],"v_iwm_128.mp3":[["我绝对不会下水的，不过穿成这样也没关系吧？",0,5.51]],"v_iwm_129.mp3":[["我穿这样一泡水，肯定会溺水的！",0,7.35]],"v_iwm_130.mp3":[["我只练习把脸浸到水里。",0,4.15]],"v_iwm_131.mp3":[["俺现在可以从水里出来了吗？",0,3.06]],"v_iyo_000.mp3":[["魂これ呀！",0,1.11]],"v_iyo_001.mp3":[["哟，主人！南海道的伊予，报到！那我出任务去啦——……等等，我还没问要去哪儿呢！",0,10.97]],"v_iyo_002.mp3":[["啊，发现主人啦！嘿咻！走，一起出去玩啦！跟着我来——！",0,9.03]],"v_iyo_003.mp3":[["哦，主人，出汗了吧？差不多该洗澡啦，走，洗澡去！",0,8.81]],"v_iyo_004.mp3":[["喂喂，待会儿我能去主人房间玩吗？我也叫上其他人哦！",0,8.18]],"v_iyo_005.mp3":[["好耶！这可是要加倍奉还的！来呀来呀来呀！",0,6.78]],"v_iyo_006.mp3":[["主人怎么这么安静？该不会不舒服吧？等着，我马上找医生来！",0,9.36]],"v_iyo_007.mp3":[["这就是光荣负伤嘛！这点失误，我才不放在心上！",0,5.925]],"v_iyo_008.mp3":[["这边的任务看来也快完了。走，下一个！",0,4.56]],"v_iyo_009.mp3":[["别光看文件啦，来玩吧。",0,5.15]],"v_iyo_010.mp3":[["到商店啦！咦？我怎么把主人落在后头啦～",0,7.79]],"v_iyo_012.mp3":[["呜～～好、好痒啊！我可以动了吗？",0,5.85]],"v_iyo_013.mp3":[["嗯嗯嗯……",0,3.62]],"v_iyo_014.mp3":[["刚才好厉害呀。喂，再来一次嘛，就一次。",0,9.29]],"v_iyo_015.mp3":[["喂，快脱呀～！来嘛，来嘛！",0,4.68]],"v_iyo_016.mp3":[["别客气啦，来，脱掉脱掉！哦，主人脱得真干脆！那我也脱，你看好啦。嘿咻！怎么样？",0,16.58]],"v_iyo_017.mp3":[["哇啊～～！？",0,2.11]],"v_iyo_018.mp3":[["不，不是那样啦！",0,2.74]],"v_iyo_019.mp3":[["那主人就来一起换衣服吧！一、二！嘿嘿，怎么样呀？",0,7.64]],"v_iyo_020.mp3":[["呀～～！",0,1.46]],"v_iyo_021.mp3":[["哟，主人！",0,1.41]],"v_iyo_022.mp3":[["等一下嘛。",0,2.93]],"v_iyo_023.mp3":[["好厉害呀！",0,3.12]],"v_iyo_024.mp3":[["哦，主人！我正想去找你玩呢。算啦，进来吧！",0,6.83]],"v_iyo_025.mp3":[["这房间有点热吧？脱掉也行哦。嘿嘿，别害羞嘛！",0,9.22]],"v_iyo_026.mp3":[["那么，主人，准备好了吗？出局！安全！嘿哟嘿哟！咦，再来一次！",0,11.09]],"v_iyo_027.mp3":[["跟主人一起玩，时间一眨眼就过去了。不过再多待一会儿也行吧？",0,9.84]],"v_iyo_028.mp3":[["主人，光让你看我也太狡猾了！你的也让我仔细看看嘛！啊！",0,12.29]],"v_iyo_029.mp3":[["主人？主人？睡着啦？那我可要偷偷帮你脱掉喽。",0,8.97]],"v_iyo_030.mp3":[["这就出发啦！咦，还没到时候吗？",0,4.91]],"v_iyo_031.mp3":[["大伙儿，来赛个跑吧！别掉队哦！",0,4.73]],"v_iyo_032.mp3":[["嗯？顺手就捡起来了呀。",0,3.33]],"v_iyo_033.mp3":[["喂，那里有什么东西！",0,2.79]],"v_iyo_034.mp3":[["大家太慢啦！",0,2.62]],"v_iyo_035.mp3":[["先手必胜呀！",0,1.61]],"v_iyo_036.mp3":[["快打！",0,1.38]],"v_iyo_037.mp3":[["我把你扒个精光呀！",0,1.82]],"v_iyo_038.mp3":[["哟嘿、哟嘿，起！",0,2.14]],"v_iyo_039.mp3":[["哇啊！？",0,0.88]],"v_iyo_040.mp3":[["一点事儿都没有啦！",0,1.33]],"v_iyo_041.mp3":[["呜哇！要脱的是我吗！？",0,2.31]],"v_iyo_042.mp3":[["我去泡个澡呀。",0,2.16]],"v_iyo_043.mp3":[["菜鸟闪开，菜鸟闪开，再来几个！啊，真痛快！",0,5.86]],"v_iyo_044.mp3":[["安全！",0,0.81]],"v_iyo_045.mp3":[["出局啦。",0,1.32]],"v_iyo_046.mp3":[["早就看穿啦！",0,1.42]],"v_iyo_047.mp3":[["你还好吗！？",0,0.98]],"v_iyo_048.mp3":[["要上啦！",0,1.11]],"v_iyo_049.mp3":[["就此分出胜负吧！",0,1.01]],"v_iyo_050.mp3":[["谢啦。",0,0.91]],"v_iyo_051.mp3":[["主人，我拿软乎乎的毛巾给你擦擦身子吧。",0,5.43]],"v_iyo_052.mp3":[["我是予州的伊予。据说伊予是「冒出温泉」的意思呀。想了解我，最好去道后温泉。我会用最得意的毛巾给你擦背哦！",0,17.19]],"v_iyo_057.mp3":[["哦，这份支援……主人，一直以来谢谢你啦。",0,5.65]],"v_iyo_106.mp3":[["哟，主人！今天工作、约定什么的全都放一边，出去玩吧！感觉今天能玩出无数个花招！",0,11.8]],"v_iyo_107.mp3":[["今天练习也很努力哦！哎呀，又把裤子弄破了……膝盖也擦伤了。主人，帮我贴个创可贴吧！",0,15.03]],"v_iyo_111.mp3":[["哇哇！滑板停不下来啦！",0,3.55]],"v_iyo_120.mp3":[["主人，嘿嘿！新年礼服我已经穿上啦，今年也请多关照！先去初诣吧，抽到大吉才罢休！",0,16.26]],"v_iyo_121.mp3":[["我做了个超棒的初梦！在脱衣猜拳里一直赢，把六原的人全都扒了个精光！嘿嘿！来吧主人，新年第一场就和我决胜负！",0,18.85]],"v_iyo_122.mp3":[["新年快乐啦！",0,2.94]],"v_iyo_128.mp3":[["主人，出发啦！去哪儿还用问吗？当然是游泳，游到精疲力尽为止！",0,10.39]],"v_iyo_129.mp3":[["我也想看看主人的泳装嘛。这里又没有别人，干脆就在这儿换吧！",0,8.36]],"v_iyo_130.mp3":[["哇啊，要翻船啦！咕噜咕噜咕噜……",0,4.84]],"v_iyo_131.mp3":[["夏天可有好多好玩的呀！",0,3.12]],"v_izu_000.mp3":[["魂これ！",0,0.87]],"v_izu_001.mp3":[["哟！　我是东海道的伊豆！我最喜欢在户外活动身体，或者在海里游泳！大将，你也要一起出出汗吗？",0,10.7]],"v_izu_002.mp3":[["又呼唤我了，难道说……大将喜欢我吗……？　嘿嘿……",0,8.62]],"v_izu_003.mp3":[["我身上可没有晒痕！因为我游泳时都光着身子嘛！",0,5.93]],"v_izu_004.mp3":[["老大，可以让我摸一下吗？我就是想知道是什么感觉。",0,5.16]],"v_izu_005.mp3":[["我们互相看看吧！……嗯，老大，你可真厉害！",0,6.91]],"v_izu_006.mp3":[["工作已经干不动了！好想去太阳底下活动活动身子。",0,8.5]],"v_izu_007.mp3":[["不行啦，电池耗光啦……",0,3.504]],"v_izu_010.mp3":[["好多看着就好玩的东西！",0,2.02]],"v_izu_015.mp3":[["这泉水好像对伤口挺管用……嗯，味道也不错嘛！",0,7.152]],"v_izu_016.mp3":[["怎么啦老大，别遮遮掩掩的。我可是完全不在乎！",0,5.28]],"v_izu_024.mp3":[["老大，你来了我真开心！来来，坐这边！",0,4.94]],"v_izu_025.mp3":[["有绿植真舒服啊。这里阳光好，我就在这里种药草。",0,5.35]],"v_izu_026.mp3":[["老大，有没有哪里受伤？来，脱下来让我看看。嘿嘿，糟糕，我什么心思都写在脸上了。",0,10.97]],"v_izu_027.mp3":[["好嘞！来一起干吧！",0,3.22]],"v_izu_028.mp3":[["啊，真舒服。老大？老大？睡着了吗？再不醒来我可要亲你了哦。",0,15.58]],"v_izu_029.mp3":[["啊，真舒服。老大？老大？睡着了吗？再不醒来我可要亲你了哦。",0,15.58]],"v_izu_030.mp3":[["多关照啦！",0,1.61]],"v_izu_051.mp3":[["预备——跑！",0,1.68]],"v_kag_000.mp3":[["魂これ！",0,0.62]],"v_kag_001.mp3":[["北陆道，加贺。想使唤我这位“加贺百万石”，主人也得有相应的智慧才行哦。",0,7]],"v_kag_002.mp3":[["哼——？居然叫了我这么多次。算了，感觉倒也不坏。",0,5.99]],"v_kag_003.mp3":[["吃饭就要全套大餐。别忘了撒金箔哦。",0,3.81]],"v_kag_004.mp3":[["喂，我正在看书呢。",0,2.85]],"v_kag_005.mp3":[["这、这种事……得彼此信任才做得来嘛。",0,5.19]],"v_kag_006.mp3":[["我怎么可能说得出口……还想再来一次什么的。",0,3.36]],"v_kag_007.mp3":[["我明明是靠脑子的啊……",0,2.286]],"v_kag_008.mp3":[["任务已经完成喽。",0,1.27]],"v_kag_009.mp3":[["再加把劲哦。",0,1.23]],"v_kag_010.mp3":[["都说一流的人才懂什么叫一流嘛。",0,2.43]],"v_kag_012.mp3":[["我的力量可不止百万石！",0,3.23]],"v_kag_013.mp3":[["啊啊啊……！",0,3.3]],"v_kag_014.mp3":[["我想你心里有数，不过今天的事可不许告诉任何人哦。",0,10.72]],"v_kag_015.mp3":[["泡汤疗养是基本功嘛。",0,1.56]],"v_kag_016.mp3":[["主人，想挨着我泡的话就来吧。啊……可以牵着你的手吗？",0,12.12]],"v_kag_017.mp3":[["等等，等等！",0,2.1]],"v_kag_018.mp3":[["我可得加把劲！",0,1.627]],"v_kag_019.mp3":[["喂，你先转过身去呀。",0,2.43]],"v_kag_020.mp3":[["嗯。",0,0.38]],"v_kag_021.mp3":[["哟，主人。",0,0.79]],"v_kag_022.mp3":[["你怎么在这儿？",0,3.21]],"v_kag_023.mp3":[["嗯唔～～！",0,1.06]],"v_kag_024.mp3":[["欢迎来到我的房间。",0,2.39]],"v_kag_025.mp3":[["摸来摸去就那么好玩吗？嗯……那我也摸你一下。",0,8.52]],"v_kag_026.mp3":[["不用找了，我可没藏什么奇怪的书。",0,2.78]],"v_kag_027.mp3":[["喏，今天的书。主人也得多读点书才行啊。",0,4.48]],"v_kag_028.mp3":[["这都是主人的错哦。你会负起责任的吧？",0,8.96]],"v_kag_029.mp3":[["要是你睡着了，我或许就能稍微坦率一点说话了吧。喂，主人……",0,8.19]],"v_kag_030.mp3":[["我可不怎么喜欢动粗……",0,2.26]],"v_kag_031.mp3":[["居然要我当队长？",0,2.03]],"v_kag_032.mp3":[["我都说好了，那当然是好东西啦。",0,2.95]],"v_kag_033.mp3":[["我怎么可能漏看嘛？",0,2.01]],"v_kag_034.mp3":[["当然走这边了吧。",0,1.97]],"v_kag_035.mp3":[["有敌人？没办法，打吧。",0,4.09]],"v_kag_036.mp3":[["一点审美都没有！",0,1.56]],"v_kag_037.mp3":[["别靠近我！",0,1.22]],"v_kag_038.mp3":[["你顶多也就一万石吧。",0,2.68]],"v_kag_039.mp3":[["唔。",0,0.82]],"v_kag_040.mp3":[["真烦人……",0,1.51]],"v_kag_041.mp3":[["所以我才讨厌打架啊！",0,2.98]],"v_kag_042.mp3":[["人总有擅长和不擅长的事嘛！",0,3.92]],"v_kag_043.mp3":[["加贺百万石！",0,2.02]],"v_kag_044.mp3":[["呵呵。",0,0.54]],"v_kag_045.mp3":[["啊、啊唔……",0,1.62]],"v_kag_046.mp3":[["就是你。",0,0.64]],"v_kag_047.mp3":[["受伤了？！",0,0.7]],"v_kag_048.mp3":[["给你最后一击。",0,1]],"v_kag_049.mp3":[["还有一人……！",0,0.76]],"v_kag_050.mp3":[["你可帮了大忙。",0,0.74]],"v_kag_051.mp3":[["这样就开始了？",0,1.99]],"v_kag_052.mp3":[["我是天下书府、加州的加贺。加贺国号称百万石，是个文化兴盛的地方。能别把我跟北陆其他那几个相提并论吗？",0,12.36]],"v_kag_128.mp3":[["这就是现代的泳装啊。确实贴身，应该很好游泳……但果然还是害羞。喂，别那么盯着看啦！",0,14.34]],"v_kag_129.mp3":[["啊，水真冷啊。披条毛巾吧。嗯？主人也冷？真拿你没办法，过来呀。再靠近些，不然罩不住你。",0,22.03]],"v_kag_130.mp3":[["这是不是有点透了？",0,2.1]],"v_kai_000.mp3":[["魂之所在！",0,0.753]],"v_kai_001.mp3":[["我是东海道的甲斐。你谁啊？咿！？老、老大？啊，您好，我叫甲斐！嘿嘿，我会努力干活的！",0,13.77]],"v_kai_002.mp3":[["老大！您尽管多叫甲斐来呀，越多越好！嘿嘿。",0,5.72]],"v_kai_003.mp3":[["只要被老大摸着，甲斐就……甲斐就……",0,5.71]],"v_kai_004.mp3":[["力气活就交给我吧！",0,2.12]],"v_kai_005.mp3":[["啊，随时欢迎来找我聊天哦。",0,4.3]],"v_kai_006.mp3":[["老大，别丢下我……",0,5.28]],"v_kai_007.mp3":[["摸摸我的头，痛痛就会飞走啦。",0,3.471]],"v_kai_008.mp3":[["活儿干完了，要不要跟甲斐做点好玩的？",0,3.58]],"v_kai_009.mp3":[["您可真肯下功夫呀～",0,3.82]],"v_kai_010.mp3":[["把你们店里最好的东西拿来！来来，老大，您请！",0,4.98]],"v_kai_012.mp3":[["翻越山岭，甲斐变得更强了！",0,3.7]],"v_kai_013.mp3":[["老大～！",0,1.884]],"v_kai_014.mp3":[["老大～～……嗯啊，老大的按摩太厉害了……甲斐都快化掉啦～～",0,14.87]],"v_kai_015.mp3":[["老大的秘汤啊～",0,2.71]],"v_kai_016.mp3":[["老大也一起进来嘛！泡澡时还可以做各种事情哦，嘿嘿。",0,7.49]],"v_kai_017.mp3":[["我、我还有老大啊……",0,2.82]],"v_kai_018.mp3":[["我可要好好疼你。",0,1.82]],"v_kai_019.mp3":[["您居然把决胜内裤送给我啦～",0,2.95]],"v_kai_020.mp3":[["嗯？",0,1]],"v_kai_021.mp3":[["老大——！",0,1.04]],"v_kai_022.mp3":[["不、不能看啊。",0,2.92]],"v_kai_023.mp3":[["嗯～啊啊～！",0,1.8]],"v_kai_024.mp3":[["欢迎光临，老大！来，把外套脱掉，再多脱一点嘛！",0,4.83]],"v_kai_025.mp3":[["水果、点心，还有甲斐，都是最可口的时候哦。",0,4.48]],"v_kai_026.mp3":[["现在应该没人看着吧？",0,3.51]],"v_kai_027.mp3":[["老大，我现在连这样公主抱你都做得到哦！",0,4]],"v_kai_028.mp3":[["不管扮演哪一种角色，甲斐都能让老大满意哦！",0,4.71]],"v_kai_029.mp3":[["老大，请把甲斐的肚子当枕头吧！",0,2.3]],"v_kai_030.mp3":[["我可是老大亲自安排进来的。",0,3.002]],"v_kai_031.mp3":[["那些弱小的家伙，我来照看。",0,2]],"v_kai_032.mp3":[["我闻到金子的味道了。",0,1.664]],"v_kai_033.mp3":[["喂，来个人，去看看那个！",0,1.89]],"v_kai_034.mp3":[["这边吧。",0,0.83]],"v_kai_035.mp3":[["冲进去！喝啊！",0,2.11]],"v_kai_036.mp3":[["碎掉吧！",0,1.02]],"v_kai_037.mp3":[["你打算怎么了结这笔账？啊？",0,2.74]],"v_kai_038.mp3":[["风林火山！",0,1.32]],"v_kai_039.mp3":[["好疼！",0,1.15]],"v_kai_040.mp3":[["老大该担心了啊！",0,2.13]],"v_kai_041.mp3":[["混账！绝饶不了你！",0,4.03]],"v_kai_042.mp3":[["我要去告诉老大～～！",0,3.48]],"v_kai_043.mp3":[["老大！你的甲斐办到了！",0,4.34]],"v_kai_044.mp3":[["未来！",0,1.08]],"v_kai_045.mp3":[["哎哎哎……！",0,1.55]],"v_kai_046.mp3":[["躺下！",0,1.07]],"v_kai_047.mp3":[["我来守护！",0,1.29]],"v_kai_048.mp3":[["交给我吧！",0,0.97]],"v_kai_049.mp3":[["坚持到最后，别松懈！",0,3.6]],"v_kai_050.mp3":[["你还真派得上用场！",0,1.57]],"v_kai_051.mp3":[["啊，谁？啊，老大，我、我这就准备！",0,6.31]],"v_kai_052.mp3":[["我是甲州的甲斐！这里被险峻的群山隔开，古人以为这儿在阴阳两界之间，也留下了些独特的风俗。对吧，老大！",0,13.62]],"v_kai_057.mp3":[["老大的心意，甲斐收到了。",0,4.32]],"v_kai_120.mp3":[["老大，年糕来啦！请尝尝甲斐拼命捣出来的软糯年糕！",0,7.25]],"v_kai_121.mp3":[["啊，绳子松了。老大，能帮我重新穿好衣服吗？要先全部解开也可以哦，嘿嘿嘿！",0,15.98]],"v_kai_122.mp3":[["想吃年糕的，都过来吧！",0,3.19]],"v_kai_123.mp3":[["老大！我想穿着这身袴陪您开开心心打年糕！今年也请多关照！",0,9.15]],"v_kai_128.mp3":[["倒不是我怕游泳，只是甲斐国不靠海，所以总有点不安。老大要是陪着我，那肯定没问题！",0,16.31]],"v_kai_129.mp3":[["老大，别去大海了，去个能踩到底的浅水池吧！那样就能安心和甲斐一起玩水啦。而且天黑后……气氛会特别好哦。",0,16.29]],"v_kai_130.mp3":[["夏天真热啊。",0,2.77]],"v_kaw_000.mp3":[["魂これ！",0,1.2]],"v_kaw_001.mp3":[["咱是畿内的河内！可像豹子一样凶猛咧！喵——！……嗯？这时候你该笑才对呀……？",0,11.1]],"v_kaw_002.mp3":[["咱是畿内的河内！像豹子一样……啥？你说之前听过？这叫重复包袱啦！重、复、包、袱！",0,11.94]],"v_kaw_003.mp3":[["放松点肩膀，轻松上阵嘛！",0,2.66]],"v_kaw_004.mp3":[["你在说啥呀？老大当然最了不起啦……大概吧！嘻嘻。",0,6.31]],"v_kaw_005.mp3":[["嗯？我可会当真的哦，这样也行？",0,5.02]],"v_kaw_006.mp3":[["不行啊，完全没人笑！得做本新的段子笔记啦。",0,5.24]],"v_kaw_007.mp3":[["呜……要死了……这回可没在说段子啊。",0,6.241]],"v_kaw_008.mp3":[["结束了啊",0,3.09]],"v_kaw_009.mp3":[["挺有男子气概嘛。",0,1.7]],"v_kaw_010.mp3":[["给我买个猫咪摆件嘛～",0,3.48]],"v_kaw_012.mp3":[["我这下蜕了一层皮啦！咦，我原本不就蜕过皮了吗？开个玩笑啦。",0,6.74]],"v_kaw_013.mp3":[["不行啦啊啊！",0,2.57]],"v_kaw_014.mp3":[["唔嗯，不行啦！呼、呼……这下真是一点不剩了。诶？还要再来一次！？",0,8.64]],"v_kaw_015.mp3":[["怎么样，河内的前方后圆坟～！哈哈，真好玩！",0,6.53]],"v_kaw_016.mp3":[["哎呀，老大，都碰到了！好，我也回敬你一下。来来！咦，你脸红啦？",0,12.34]],"v_kaw_017.mp3":[["我虽然挺喜欢猫啦！",0,2.09]],"v_kaw_018.mp3":[["我就负责吐槽吧。",0,2.25]],"v_kaw_019.mp3":[["这顶帽子挺帅嘛，戴着也舒服。瞄一眼～",0,6.38]],"v_kaw_020.mp3":[["咋样？",0,0.72]],"v_kaw_021.mp3":[["大将！",0,1.44]],"v_kaw_022.mp3":[["怎、怎么回事啦！",0,2.15]],"v_kaw_023.mp3":[["真是的！",0,1.13]],"v_kaw_024.mp3":[["老大，刚才门口好像有只猫呢。",0,3.98]],"v_kaw_025.mp3":[["喂，你盯着我看太久了吧……倒也没关系啦。",0,4.86]],"v_kaw_026.mp3":[["可以让我表演个新段子吗？先对大家保密哦！",0,5.56]],"v_kaw_027.mp3":[["老大，一起在房间里做章鱼烧吧！只有我们两个也行哦。",0,5.82]],"v_kaw_028.mp3":[["咱身体健康得很，指压按摩什么的根本不……啊啊啊～！",0,8.13]],"v_kaw_029.mp3":[["好耶！老大笑啦！就是这个感觉！",0,5.05]],"v_kaw_030.mp3":[["这阵容挺不错嘛。",0,1.67]],"v_kaw_031.mp3":[["尽管把梗抛给我！",0,2.46]],"v_kaw_032.mp3":[["我捡走啦。",0,1.31]],"v_kaw_033.mp3":[["拿这个来玩即兴答题吧。",0,1.88]],"v_kaw_034.mp3":[["冲上去！",0,1.2]],"v_kaw_035.mp3":[["开场挺抓人的嘛。",0,1.76]],"v_kaw_036.mp3":[["想挨揍啊？",0,1.35]],"v_kaw_037.mp3":[["哪有这回事啊！",0,1.67]],"v_kaw_038.mp3":[["差不多得了！",0,1.26]],"v_kaw_039.mp3":[["哇啊！",0,1.16]],"v_kaw_040.mp3":[["这挑的毛病可真够狠的～",0,2.13]],"v_kaw_041.mp3":[["唔……要、要露出来啦！",0,2.396]],"v_kaw_042.mp3":[["我回去重整，再来过。",0,1.78]],"v_kaw_043.mp3":[["搞什么啦！好，谢谢大家～～！",0,4.81]],"v_kaw_044.mp3":[["就是这样的！",0,0.77]],"v_kaw_045.mp3":[["这下不妙吧？",0,1.15]],"v_kaw_046.mp3":[["我要收包袱喽～",0,1.25]],"v_kaw_047.mp3":[["好吃啊。",0,1.7]],"v_kaw_048.mp3":[["接着我的梗来！",0,1.36]],"v_kaw_049.mp3":[["决定了！",0,0.96]],"v_kaw_050.mp3":[["开心啊。",0,1.22]],"v_kaw_051.mp3":[["装傻的和吐槽的，你想演哪个？",0,2.57]],"v_kaw_052.mp3":[["我是畿内的河州、河内！这里在畿内也是个农业兴盛的地方，默默撑起了京城的粮食供应。我弟弟小鲷老黏着我，可爱得不得了！对吧，小鲷～～！",0,18.97]],"v_kaw_128.mp3":[["嗯！刚刚那不是在练游泳……啊啊，不行，要淹死啦！我也好想学会游泳啊！",0,14.38]],"v_kaw_129.mp3":[["……反正我也不会游泳。要不就躺在老大膝盖上睡个觉？偷瞄。",0,15.12]],"v_kaw_130.mp3":[["咱现在可是喜剧之神附体啦……！",0,4.27]],"v_kaw_131.mp3":[["好嘞，大将笑了。照这个势头来！",0,5.06]],"v_kaz_000.mp3":[["魂これ！",0,0.8]],"v_kaz_001.mp3":[["主人，您好。我是东海道的上总。下总那孩子有乖乖听话吗？",0,11.18]],"v_kaz_002.mp3":[["晚上好，主人。看起来……有点累了呢。要是不嫌弃，可以把我的膝盖借给您枕一会儿哦。",0,9.41]],"v_kaz_003.mp3":[["主人看起来精神不错，真是太好了。",0,4.42]],"v_kaz_004.mp3":[["啊，糟糕！我竟然弄坏了……明明也没怎么用力呀。",0,10.32]],"v_kaz_005.mp3":[["真是的，主人，这样可不行哦。光着身子可没法出去见人呀。",0,8.76]],"v_kaz_006.mp3":[["下次去哪儿玩呢？每个地方都有独特的魅力，真难选呀。",0,6.1]],"v_kaz_007.mp3":[["别盯着看呀。我会赶快把伤治好的。",0,4.786]],"v_kaz_008.mp3":[["有您的来信，我给您放这儿了。",0,4.23]],"v_kaz_009.mp3":[["您这手艺真是出色。",0,2.06]],"v_kaz_010.mp3":[["东西从全国各地送来，光看着就让人兴奋呢。",0,5.2]],"v_kaz_012.mp3":[["谢谢",0,2.06]],"v_kaz_013.mp3":[["哇——！哈、哈……",0,3.17]],"v_kaz_014.mp3":[["呜……啊……呵呵，我刚才可舒服了哦。",0,7.27]],"v_kaz_015.mp3":[["我就先去泡澡了哦。",0,2.16]],"v_kaz_016.mp3":[["主人，我不太习惯被人这么看……啊，但也不是讨厌哦。请来这边吧。",0,14.62]],"v_kaz_017.mp3":[["真好啊。",0,2.06]],"v_kaz_018.mp3":[["呵呵……我来帮你夹住哦。",0,3.06]],"v_kaz_019.mp3":[["主人，不准偷看。……不、可、以，知道了吗？",0,6.37]],"v_kaz_020.mp3":[["呵呵呵。",0,1.05]],"v_kaz_021.mp3":[["主人。",0,1.12]],"v_kaz_022.mp3":[["哎呀，这可怎么办。",0,3.36]],"v_kaz_023.mp3":[["不可以。",0,2.46]],"v_kaz_024.mp3":[["哎呀，主人，请进。喝杯热茶可以吗？",0,7.45]],"v_kaz_025.mp3":[["这是给下总准备的点心……要不我们两个先吃掉吧？",0,8.02]],"v_kaz_026.mp3":[["要是遇到什么事，尽管向我撒娇哦。我会像这样抱住你的。",0,8.34]],"v_kaz_027.mp3":[["啊，主人，您应该知道吧，我可不会产奶哦。",0,7.41]],"v_kaz_028.mp3":[["啊，主人，请把灯关掉哦。",0,5.86]],"v_kaz_029.mp3":[["和主人两个人一起旅行，一定很开心吧。呵呵呵。",0,6.7]],"v_kaz_030.mp3":[["请多关照哦。",0,2.06]],"v_kaz_031.mp3":[["让我当总长吗？呵呵，真让人期待。",0,5.84]],"v_kaz_032.mp3":[["哎呀呀。",0,1.06]],"v_kaz_033.mp3":[["大家都小心些哦。",0,3.06]],"v_kaz_034.mp3":[["我已经测量过了。",0,2.06]],"v_kaz_035.mp3":[["哎呀呀，我要去找他们算账喽。",0,3.7]],"v_kaz_036.mp3":[["可不许捣蛋哦。",0,1.42]],"v_kaz_037.mp3":[["我就避开脸好了。",0,1.47]],"v_kaz_038.mp3":[["我就赤手空拳上了哦。",0,1.59]],"v_kaz_039.mp3":[["我们就往那边走吧。",0,2.06]],"v_kaz_040.mp3":[["哎呀，真是个淘气鬼。",0,1.15]],"v_kaz_041.mp3":[["快洒出来了。",0,3.06]],"v_kaz_042.mp3":[["失陪了，请容我先退下。",0,4.15]],"v_kaz_043.mp3":[["呵呵呵，不知怎么热血沸腾了呢。",0,3.06]],"v_kaz_044.mp3":[["好！",0,1.06]],"v_kaz_045.mp3":[["这就有点难办了呢。",0,1.62]],"v_kaz_046.mp3":[["找到了。",0,1.06]],"v_kaz_047.mp3":[["这样可不行哦。",0,1.06]],"v_kaz_048.mp3":[["请交给我吧。",0,1.06]],"v_kaz_049.mp3":[["对不起。",0,1.06]],"v_kaz_050.mp3":[["谢谢您。",0,2.06]],"v_kaz_051.mp3":[["呵呵，主人，我等你好久了。",0,4.51]],"v_kaz_052.mp3":[["我是总州的上总。下总和安房本来该是总国的兄弟。不过下总的建国时间和我们不同，安房又算是养大了总国……叫他们两个弟弟合不合适呢？这关系真难理清。",0,27.24]],"v_kaz_128.mp3":[["我不太擅长穿暴露的衣服，还是得披件外套呢。",0,6.31]],"v_kaz_129.mp3":[["去海边旅行，也许不错呢。呵呵，好期待呀。",0,7.33]],"v_kaz_130.mp3":[["是谁已经往我身上泼水啦？",0,3.37]],"v_kaz_131.mp3":[["我很擅长游泳哦。",0,4.55]],"v_kii_000.mp3":[["魂これ！",0,1.23]],"v_kii_001.mp3":[["嘎哈哈哈！咱是南海道的纪伊！小主人，你尽管叫我一声“叔叔”，不用客气！",0,14.5]],"v_kii_002.mp3":[["喔喔！小主人又叫咱来了……！咱的爱意……是不是已经传达到了呢……！！",0,10.97]],"v_kii_003.mp3":[["嚯，你可真攒了不少啊！好嘞，叔叔就来搭把手！来，和叔叔一起试试吧！",0,14.2]],"v_kii_004.mp3":[["主人亲，给你带吃的来啦！一起吃南高梅饭团吧。嗯，好吃吗？那就好，那就好！",0,16.89]],"v_kii_005.mp3":[["哎呀！主人亲竟然主动向叔叔示好！叔叔太感动了！那叔叔要把满满的爱都送给你哦！",0,16.47]],"v_kii_006.mp3":[["啊，好热啊……抱歉，叔叔要脱一脱啦。",0,11.14]],"v_kii_007.mp3":[["嘶……这也是通往开悟的一环。在老夫的爱面前，这可算不上什么阻碍。嘎哈哈哈哈！",0,12.738]],"v_kii_008.mp3":[["主人酱的工作成果，能让大叔也看看吗？",0,5.86]],"v_kii_009.mp3":[["喔哦～！真不愧是主人酱！感觉真不错啊～",0,6.64]],"v_kii_010.mp3":[["店员，瞧，这就是咱家引以为傲的主人！嗯～真帅啊～",0,10.86]],"v_kii_012.mp3":[["呜哦哦～～！靠着我对主人酱的爱，老夫变强啦～～！！",0,10.23]],"v_kii_013.mp3":[["啊、主人酱！呜哦……够、够啦……！",0,11.18]],"v_kii_014.mp3":[["啊、主人酱～！喔呵呵……呜、哈……大叔感受到主人酱满满的爱，一直进到心坎里啦！",0,17.47]],"v_kii_015.mp3":[["呼～…好温暖…果然，水里头最让人安心呢～",0,10.75]],"v_kii_016.mp3":[["来，主人亲，躺在这里。叔叔用这比大海还宽广的身体把你包起来，帮你洗得干干净净！嘎哈哈哈！",0,18.46]],"v_kii_017.mp3":[["呜哦哦～～！撞、撞到一块儿了！？",0,3.13]],"v_kii_018.mp3":[["唔，交给大叔吧。",0,4.12]],"v_kii_019.mp3":[["啊，主人酱送的礼物！大叔太高兴啦！我、我一定会好好穿的！",0,11.15]],"v_kii_020.mp3":[["哦～～！",0,1.13]],"v_kii_021.mp3":[["主人酱！",0,1.63]],"v_kii_022.mp3":[["啊、啊，主主人？",0,4.39]],"v_kii_023.mp3":[["啊……啊啊……呜哦哦！",0,5.97]],"v_kii_024.mp3":[["主人亲，欢迎欢迎！快，别客气，进来进来！要不叫点外卖？",0,12.64]],"v_kii_025.mp3":[["主人亲，辛苦啦！今天就和叔叔一起尽情玩吧！",0,9.81]],"v_kii_026.mp3":[["那个……叔叔在房间里都是光着身子的，脱掉也没关系吧？",0,9.49]],"v_kii_027.mp3":[["主人亲，叔叔一直都在这里。所以无论发生什么，都放心吧。",0,11.61]],"v_kii_028.mp3":[["主人亲，不难受吧？放心，放松身体就好，叔叔会紧紧抱着你的。",0,19.18]],"v_kii_029.mp3":[["主人亲，困了就在叔叔身上睡吧。冰凉凉、晃悠悠的天然水床哦！嘎哈哈哈！",0,15.14]],"v_kii_030.mp3":[["就让我积些功德吧。",0,2.66]],"v_kii_031.mp3":[["纪州惣国成立啦！嘎哈哈哈！",0,5.45]],"v_kii_032.mp3":[["真是有功德啊",0,2.67]],"v_kii_033.mp3":[["就把这也当做学习的机会吧。",0,4.03]],"v_kii_034.mp3":[["去哪呢……先让鸡来战斗看看嘛",0,6.06]],"v_kii_035.mp3":[["无明的迷惘，由我来解开吧",0,4.71]],"v_kii_036.mp3":[["业障消除，诸魔降伏。",0,3.13]],"v_kii_037.mp3":[["愿佛祖庇佑。",0,1.63]],"v_kii_038.mp3":[["流转轮回，济度一切众生！",0,2.76]],"v_kii_039.mp3":[["南无！",0,0.63]],"v_kii_040.mp3":[["算得了什么？",0,1.13]],"v_kii_041.mp3":[["无论什么事，都要走实践实验之路",0,3.4]],"v_kii_042.mp3":[["看来修行还不够。",0,2.13]],"v_kii_043.mp3":[["感恩报恩。那就来点护摩火吧。",0,4.27]],"v_kii_044.mp3":[["好！",0,1.13]],"v_kii_045.mp3":[["别着急。",0,1.63]],"v_kii_046.mp3":[["放心吧！",0,1.13]],"v_kii_047.mp3":[["迷途之人啊。",0,1.63]],"v_kii_048.mp3":[["老夫去！",0,1.13]],"v_kii_049.mp3":[["超越它吧！",0,1.13]],"v_kii_050.mp3":[["多谢，多谢。",0,1.63]],"v_kii_051.mp3":[["众生无边誓愿度，烦恼无尽誓愿断。",0,6.04]],"v_kii_052.mp3":[["老夫是纪州的纪伊。纪伊国有好几座势力强盛的寺社，就像许多宗教领地聚在一处。无论有什么过往，只要进了寺里，便一概不追究。老夫也想有那样的胸襟啊。",0,28.49]],"v_kii_057.mp3":[["哎呀，主人酱，一直以来多谢你支持啦。",0,6.1]],"v_kii_106.mp3":[["乖乖的主人亲，圣诞老人有礼物给你哦！瞧，叔叔抱枕！叔叔随时都能陪你睡。嘎哈哈！",0,17.24]],"v_kii_107.mp3":[["和主人亲一起悠闲地过圣诞，叔叔太高兴了，还准备了蛋糕呢。啊，张嘴……嗯，好吃吗？只看你的笑容，叔叔就心满意足啦！",0,22.08]],"v_kii_111.mp3":[["吼吼吼！给乖孩子准备了好多礼物哟！",0,7.15]],"v_kii_120.mp3":[["小主人，跟叔叔一起去参加尼拉仓祭吧？只穿一条兜裆布打泥地相扑，可有意思啦！",0,10.53]],"v_kii_121.mp3":[["主人亲，还吃得下年糕吗？难得过年，多烤一点吧！杂煮也还有得添哦！",0,14.54]],"v_kii_122.mp3":[["白味噌配圆年糕……说起新年杂煮，果然就是这个味道啊。",0,9.51]],"v_kii_128.mp3":[["主人亲，爬上叔叔的背！好嘞，在水里尽情游一圈吧！",0,10.02]],"v_kii_129.mp3":[["啊，叔叔这可是伸缩式的！你看，像这样就会鼓得满满的啦！嘎哈哈哈！",0,11.16]],"v_kii_130.mp3":[["叔叔要喷水啦～！",0,3.67]],"v_mik_000.mp3":[["魂これ！",0,0.87]],"v_mik_001.mp3":[["东海道的上国，三河。你的贴身护卫就交给我吧。",0,8.6]],"v_mik_002.mp3":[["又来听我的声音了吗。才、才没有高兴呢……",0,10.88]],"v_mik_003.mp3":[["只要是我能做到的，尽管吩咐。",0,2.43]],"v_mik_004.mp3":[["我去巡视一圈。",0,1.06]],"v_mik_005.mp3":[["被你摸……也没有问题。",0,5.92]],"v_mik_006.mp3":[["该去给院子里的番茄浇水了。",0,2.61]],"v_mik_007.mp3":[["我没事，任务要紧。",0,3.475]],"v_mik_008.mp3":[["任务完成。",0,1.17]],"v_mik_009.mp3":[["这是主人的记录。嗯，还不错。",0,5.87]],"v_mik_010.mp3":[["省点伙食费，就能买东西了。",0,2.405]],"v_mik_012.mp3":[["还要……变得更强……我是……主人的刀……",0,7.81]],"v_mik_013.mp3":[["唔……嗯……",0,3.16]],"v_mik_014.mp3":[["一、一想到是主人的手在碰我，我就静不下来。",0,8.35]],"v_mik_015.mp3":[["我不太习惯洗澡。",0,2.79]],"v_mik_016.mp3":[["啊，主人……既、既然没人看见，一起泡也没关系，我不介意。",0,11.71]],"v_mik_017.mp3":[["嗯啊，不、不能那样用手……",0,3.06]],"v_mik_018.mp3":[["这里舒服吗？",0,2.33]],"v_mik_019.mp3":[["我穿平时那件就行。",0,3.23]],"v_mik_020.mp3":[["啊……",0,0.65]],"v_mik_021.mp3":[["主人。",0,0.64]],"v_mik_022.mp3":[["什……主、主人……！？",0,2.21]],"v_mik_023.mp3":[["唔、嗯啊……",0,1.61]],"v_mik_024.mp3":[["进来吧。这里能上网，也能玩游戏，很有趣。",0,8.2]],"v_mik_025.mp3":[["种的蔬菜可以收获了。要不要……一起吃？",0,6.51]],"v_mik_026.mp3":[["我担心……这样和你共度的时光，会不会让我变得软弱。",0,7.7]],"v_mik_027.mp3":[["我……现在不是工作时间。再稍微……这样待一会儿。",0,9.91]],"v_mik_028.mp3":[["我、我只是主人的工具。你想怎么用都行……",0,10.02]],"v_mik_029.mp3":[["我……只要能待在主人身边，就已经……",0,4.16]],"v_mik_030.mp3":[["我听主人的。",0,2.48]],"v_mik_031.mp3":[["兵法指南派得上用场。",0,2.21]],"v_mik_032.mp3":[["存起来吧。",0,1.25]],"v_mik_033.mp3":[["小心，有东西。",0,2.36]],"v_mik_034.mp3":[["站在十字路口，往手杖倒下的方向走。嗯，这边。",0,6.43]],"v_mik_035.mp3":[["已经准备好了。剩下的，就是打倒而已。",0,5.6]],"v_mik_036.mp3":[["按计划行事。",0,1.22]],"v_mik_037.mp3":[["脏活儿由我来做也没关系。",0,1.84]],"v_mik_038.mp3":[["为三河武士之名！",0,1.94]],"v_mik_039.mp3":[["唔。",0,0.34]],"v_mik_040.mp3":[["可恶……",0,1.17]],"v_mik_041.mp3":[["这点风险早就在预料之内。",0,2.45]],"v_mik_042.mp3":[["经历过失败，才能变强。",0,5.16]],"v_mik_043.mp3":[["我才没高兴。",0,3.02]],"v_mik_044.mp3":[["好！",0,0.5]],"v_mik_045.mp3":[["不好了。",0,1.01]],"v_mik_046.mp3":[["最后一击！",0,0.99]],"v_mik_047.mp3":[["没事吧？",0,0.96]],"v_mik_048.mp3":[["交给我。",0,0.79]],"v_mik_049.mp3":[["你是最后一个。",0,1.24]],"v_mik_050.mp3":[["帮大忙了。",0,0.71]],"v_mik_051.mp3":[["我会保护主人。",0,2.74]],"v_mik_052.mp3":[["我是东海道、三州的三河。昔日，效忠于开创太平盛世的家康公的三河武士，最看重忠义。我也想像他们那样。尾张？让那家伙打他的年糕去吧。",0,24.19]],"v_mik_106.mp3":[["穿这身衣服，不管去超市还是唱卡拉 OK，我都能陪你。无论去哪儿……我都能保护主人。",0,12.36]],"v_mik_107.mp3":[["我刚去运动了一会儿。穿着这件衣服就想活动身体。主人……怎么样？",0,13.09]],"v_mik_111.mp3":[["要不要去买午饭？",0,1.66]],"v_mik_128.mp3":[["水里也有危险。以防万一……我也学会了人工呼吸。",0,12.06]],"v_mik_129.mp3":[["主人……喜欢游泳吗？如果主人喜欢，那我也喜欢。",0,13.1]],"v_mik_130.mp3":[["皮肤要晒伤了……",0,3.24]],"v_mus_000.mp3":[["啊，魂之所在～！",0,2.059]],"v_mus_001.mp3":[["嘿！论义理人情，老子天下第一！论汪汪叫，东海第一！地魂男儿里最厉害的救火好汉，就是我武藏！",0,10.64]],"v_mus_002.mp3":[["怎么啦，大将？还需要我再多出点力？包在我身上！",0,5.53]],"v_mus_003.mp3":[["男人就该挺起胸膛，堂堂正正的！",0,2.38]],"v_mus_004.mp3":[["老大，有什么需要我帮忙的吗？尽管交给我！",0,5.43]],"v_mus_005.mp3":[["哇！老大，你这么突然……好歹让我有个心理准备啊！",0,4.19]],"v_mus_006.mp3":[["趁现在把坏掉的零件修好吧。",0,2.91]],"v_mus_007.mp3":[["哪有工夫叫苦啊……疼疼疼！",0,3.356]],"v_mus_008.mp3":[["好像已经办完了。",0,1.38]],"v_mus_009.mp3":[["你很努力嘛。好样的，好样的！",0,2.6]],"v_mus_010.mp3":[["俺的钱可不留过夜！痛痛快快地花吧！",0,3.25]],"v_mus_012.mp3":[["既然这么看得起我，我可不能辜负你的期待啊。",0,3.48]],"v_mus_013.mp3":[["啊……唔……",0,2.064]],"v_mus_014.mp3":[["啊、唔……啊，啊，大将真厉害。这一下直击心口呢……",0,6.36]],"v_mus_015.mp3":[["这澡温度可真是有够烫的。",0,4.03]],"v_mus_016.mp3":[["老大，你贴得这么紧的话……你看，瞧啊！",0,6.91]],"v_mus_017.mp3":[["那里……啊……",0,2.39]],"v_mus_018.mp3":[["好，我下定决心了！",0,2.98]],"v_mus_019.mp3":[["大、大将送我的。我当然开心啦，不过……",0,4.67]],"v_mus_020.mp3":[["哦！",0,0.582]],"v_mus_021.mp3":[["哟，大将！",0,0.97]],"v_mus_022.mp3":[["哇哇哇，怎么回事啊！？",0,1.5]],"v_mus_023.mp3":[["哇啊……！",0,0.98]],"v_mus_024.mp3":[["欢迎光临！来来，老大，快进来！",0,3.77]],"v_mus_025.mp3":[["哎呀，毛发被夸奖的话，我也会害羞啊。",0,4.05]],"v_mus_026.mp3":[["老大，尽管交给我！别看我这样，手可巧着呢。",0,4.97]],"v_mus_027.mp3":[["就让我这潇洒汉子抱抱你吧！再靠近些！",0,6.29]],"v_mus_028.mp3":[["嘿嘿，就这样继续吧。我早就在等着啦，老大！",0,6.94]],"v_mus_029.mp3":[["睡觉的时候果然还是得光着身子啊。",0,2.12]],"v_mus_030.mp3":[["那当然啦！",0,0.883]],"v_mus_031.mp3":[["交给我吧！",0,1.13]],"v_mus_032.mp3":[["这东西看着能派上用场。",0,1.425]],"v_mus_033.mp3":[["还挺风雅啊。",0,1.68]],"v_mus_034.mp3":[["我的鼻子告诉我，该走这边。",0,2.49]],"v_mus_035.mp3":[["来放一场大烟花吧！",0,2.73]],"v_mus_036.mp3":[["干啥，干啥？",0,1.21]],"v_mus_037.mp3":[["接好了！",0,0.89]],"v_mus_038.mp3":[["我把炮弹全打出去！",0,1.76]],"v_mus_039.mp3":[["可恶！",0,1.4]],"v_mus_040.mp3":[["混账！",0,0.93]],"v_mus_041.mp3":[["呼啊，看着黑乎乎的嘛。",0,2.74]],"v_mus_042.mp3":[["该死！先撤退！",0,3.11]],"v_mus_043.mp3":[["哟，大将！奖赏的话，我想吃头茬鲣鱼！",0,3.38]],"v_mus_044.mp3":[["那还用说！",0,1.05]],"v_mus_045.mp3":[["开什么玩笑。",0,1.1]],"v_mus_046.mp3":[["小兔崽子。",0,0.88]],"v_mus_047.mp3":[["你这个笨蛋！",0,1.25]],"v_mus_048.mp3":[["我配合你！",0,0.97]],"v_mus_049.mp3":[["交给我吧！",0,1.1]],"v_mus_050.mp3":[["帮大忙啦！",0,0.91]],"v_mus_051.mp3":[["这就开干吧！",0,1.34]],"v_mus_052.mp3":[["我是武州的武藏。江户城以前老是起火，所以才有「火灾和打架是江户之花」这句话。到了战场，我也要以救火队的身份大显身手！",0,11.08]],"v_mus_106.mp3":[["老大有什么想要的吗？圣夜特快配送，什么都能给你送到！",0,7.29]],"v_mus_107.mp3":[["来，跟老大两个人过圣诞吧！武藏圣诞快递最后一件货物，瞧，是一桌大餐！老大，今天尽管吃饱喝足！嘿嘿。",0,13.98]],"v_mus_111.mp3":[["武藏圣诞快递，欢迎惠顾！",0,2.88]],"v_mus_128.mp3":[["老大，西瓜已经冰好了！等凉透了一起吃吧！",0,5.38]],"v_mus_129.mp3":[["从海里上岸，得意的毛发都变得硬邦邦的。老大，不好意思，可以帮我涂点护毛霜吗？",0,11.45]],"v_mus_130.mp3":[["唔！哇啊，沙子钻进鼻子里了！",0,4.06]],"v_mus_131.mp3":[["狗刨式游泳就交给我吧！",0,2.24]],"v_n000_001.mp3":[["总会有办法的吧。",0,1.68]],"v_n000_002.mp3":[["我是猫乃屋。",0,1.68]],"v_n000_003.mp3":[["哟，后辈。",0,1.39]],"v_n000_004.mp3":[["谢啦。",0,1.39]],"v_n000_005.mp3":[["喂喂。",0,1.95]],"v_n000_006.mp3":[["哇，好厉害！",0,3.29]],"v_n000_007.mp3":[["有什么不懂的，尽管来问我这个前辈！",0,2.59]],"v_n000_008.mp3":[["去吃饭吧！吃肉、吃肉！",0,3.72]],"v_n000_009.mp3":[["哦，你意外地喜欢这种事啊。嘿嘿，要不要偷偷溜去别的地方？",0,10.51]],"v_n000_010.mp3":[["哟，我亲爱的后辈！给你带工作来啦！",0,5.93]],"v_n000_011.mp3":[["真是个工作狂，跟我一个样啊。喂，你那什么表情？",0,7.22]],"v_n000_012.mp3":[["嘿嘿，后辈长大了嘛。看来都是我教得好呀！",0,6.91]],"v_n000_014.mp3":[["啊，是后辈啊。让我再睡会儿。",0,10.59]],"v_n000_015.mp3":[["怎么，想跟我撒娇？真拿你没办法，过来嘛。嘿嘿。",0,8.76]],"v_n000_016.mp3":[["哟，后辈。今天吃什么？我想吃顿扎实的。咱们查查有什么店吧。",0,8.4]],"v_n000_017.mp3":[["糟了，明明已经累了……我的身子倒挺诚实的。",0,8.95]],"v_n000_018.mp3":[["糟了，口袋里怎么有红豆？怪不吉利的，扔了吧。",0,6]],"v_n000_030.mp3":[["哦，那我先进去了啊。你也快来！",0,5.521]],"v_n000_031.mp3":[["啊，果然赤裸相见很重要嘛。喂喂，别害羞，不就是身体接触吗？哦，你也挺有感觉啊。交给前辈吧，嘿嘿。",0,18.96]],"v_n001_001.mp3":[["先帮我查一下哦。",0,1]],"v_n001_002.mp3":[["我是夏人。",0,0.83]],"v_n001_003.mp3":[["怎么样？",0,1.06]],"v_n001_004.mp3":[["真靠得住。",0,1.05]],"v_n001_005.mp3":[["等一下！",0,1.52]],"v_n001_006.mp3":[["这样……",0,1.73]],"v_n001_007.mp3":[["管理好身体也是任务的一部分，记得休息哦。",0,4.02]],"v_n001_008.mp3":[["我的工作就是支持你，有事尽管依靠我。",0,3.95]],"v_n001_009.mp3":[["你也一样，工作时间禁止乱摸哦。",0,3.09]],"v_n001_010.mp3":[["那么，开始简报吧。详情都写在资料里。",0,5.13]],"v_n001_011.mp3":[["我暂时会待在这里，有事就叫我。",0,3.5]],"v_n001_012.mp3":[["谢谢，我也信赖你。",0,3.54]],"v_n001_014.mp3":[["欢迎！我刚泡了咖啡，一起来一杯吗？",0,4.1]],"v_n001_015.mp3":[["累不累？我可以给你按摩哦。",0,2.57]],"v_n001_016.mp3":[["一紧张就出汗了。抱歉，身上黏糊糊的。",0,4.93]],"v_n001_017.mp3":[["真的可以是我吗？我知道了。那、那就开始吧。",0,9.2]],"v_n001_018.mp3":[["原来也有这样的幸福吗……",0,3.931]],"v_n001_030.mp3":[["哈啊……平日的疲劳都消了。",0,4.571]],"v_n001_031.mp3":[["哇，这个入浴剂让水变得又起泡又滑溜呢。哇，脚碰到啦！滑溜溜的，感觉好奇怪……喂，别凑上来，不行啦！哇！",0,20]],"v_n002_001.mp3":[["我忘带东西了。",0,2.55]],"v_n002_002.mp3":[["我是猪森。",0,1.61]],"v_n002_003.mp3":[["呀！",0,0.94]],"v_n002_004.mp3":[["你帮大忙了。",0,2.16]],"v_n002_005.mp3":[["呜哇哇！",0,1.49]],"v_n002_006.mp3":[["哈啊～～……",0,1.99]],"v_n002_007.mp3":[["喝完营养饮料继续研究、研究！哪有时间睡觉啊！",0,6.24]],"v_n002_008.mp3":[["咦？笔呢？明明带来了啊。",0,5.52]],"v_n002_009.mp3":[["诶？你觉得适合我？其、其实我昨天还没洗澡呢……",0,11.54]],"v_n002_010.mp3":[["早上好！今天也想请你帮忙……哇哇，资料掉了！",0,8.38]],"v_n002_011.mp3":[["还有别的事想拜托你。呃，咦？明明带过来了……稍等一下。",0,11.02]],"v_n002_012.mp3":[["活动了一下，脑袋清醒多了。",0,7.08]],"v_n002_014.mp3":[["哎，稍等我一下。地上的文件挪到这边，这个拿开……好了，你坐吧。",0,11.35]],"v_n002_015.mp3":[["我、我不太知道约会该怎么做……唔，能不能握你的手？",0,13.13]],"v_n002_016.mp3":[["你喜欢历史吗？要是能跟你一起去看看各个时代，一定很有意思。",0,9.63]],"v_n002_017.mp3":[["啊，你、你来之前我倒是洗过澡了。不过我那个……没多少经验……",0,14.16]],"v_n002_018.mp3":[["如果是和你一起……一定……",0,10.18]],"v_n002_030.mp3":[["知、知道了。今天我会洗澡的。",0,6.312]],"v_n002_031.mp3":[["哇，我自己会洗啦！唔……不过难得有机会，就拜托你吧。嗯，好痒啊！哇、哇！连那种地方也要洗吗？！啊啊！",0,22.2]],"v_n002_032.mp3":[["泳装布料好少，稍微……那个，有点害羞，我不太习惯。那、那么……任务就拜托你了。",0,16.03]],"v_n002_033.mp3":[["哇，防晒霜！谢谢！啊，别一边涂一边按摩……好痒呀！",0,15.91]],"v_n002_034.mp3":[["好热，出汗了……",0,2.81]],"v_n003_001.mp3":[["感觉怎么样？",0,1.95]],"v_n003_002.mp3":[["我是羽鸟。",0,1.13]],"v_n003_003.mp3":[["看起来挺有精神嘛。",0,3.33]],"v_n003_004.mp3":[["谢谢你。",0,1.26]],"v_n003_005.mp3":[["咦？这可真是……",0,3.08]],"v_n003_006.mp3":[["能稍等我一下吗？",0,4.3]],"v_n003_007.mp3":[["差不多该休息了吧？我从喜欢的蛋糕店买了新品，要不要一起吃？",0,9.65]],"v_n003_008.mp3":[["为了这件艺术品，已经有许多人失去生命。也正因如此，它才显得美丽吧。",0,9.01]],"v_n003_009.mp3":[["啊，嗯嗯，很有男孩子气，也挺健康的……可是非得现在做吗？",0,9.02]],"v_n003_010.mp3":[["准备好了？嗯……差不多开始吧。",0,7.07]],"v_n003_011.mp3":[["今天要结束了吗？也是呢……还得再加把劲。我很期待你的表现哦。",0,13.14]],"v_n003_014.mp3":[["欢迎，来得正好。我备了蛋糕，这就去泡红茶，你坐着等一下哦。",0,9.41]],"v_n003_015.mp3":[["我觉得，生命还在的时候和生命消逝的时候，都很美。",0,11.43]],"v_n003_016.mp3":[["啊哈哈，好痒。想起我在大学教书的时候，也常被学生们这么碰呢。",0,10.86]],"v_n003_017.mp3":[["被你抱着真安心。没事的。来吧……",0,11.62]],"v_n003_018.mp3":[["连你的睡脸都那么温暖。我也想看看那双眼睛映出的世界啊。",0,9.81]],"v_n003_030.mp3":[["哈啊……水温真好。要不要一起泡？",0,5.2]],"v_n003_031.mp3":[["啊，背上还有泡沫吗？谢谢。我摘了眼镜就看不太清。不过那里应该已经冲干净了呀……你真是的，帮我留意着点，别让别人过来哦。",0,23.71]],"v_n004_001.mp3":[["我有兴趣！",0,1.13]],"v_n004_002.mp3":[["我是百太哦！",0,1.22]],"v_n004_003.mp3":[["前辈！",0,0.74]],"v_n004_004.mp3":[["谢啦！",0,1.08]],"v_n004_005.mp3":[["好嘞——！",0,1.07]],"v_n004_006.mp3":[["那里……好舒服啊！",0,2.43]],"v_n004_007.mp3":[["想问一下，前辈喜欢什么类型的人啊？",0,5.34]],"v_n004_008.mp3":[["咳咳……采访时经常有人摸我的头呢，真叫人害羞。",0,4.87]],"v_n004_009.mp3":[["喂，我可什么都没往里塞啊！",0,3.44]],"v_n004_010.mp3":[["今天也让我贴身采访吧！哦，抱得太紧会觉得热吗？",0,7.53]],"v_n004_011.mp3":[["哦，这是前辈活跃事迹的新一页！我要全身心地感受，再好好记下来！",0,9.49]],"v_n004_014.mp3":[["我刚在整理采访笔记。多亏有前辈呢。",0,5.67]],"v_n004_015.mp3":[["一待在自己房间，我就想把衣服脱了呢。",0,3.5]],"v_n004_016.mp3":[["哇！嘿嘿嘿……我全身都挺敏感的……",0,6.18]],"v_n004_017.mp3":[["那里可以看，不过前辈可别吓一跳哦。",0,8.18]],"v_n004_018.mp3":[["诶，你闻到了？我这就去把垃圾桶清空！",0,4.63]],"v_n004_030.mp3":[["哈啊……暖和得不得了。",0,4.843]],"v_n004_031.mp3":[["前辈，我已经搓了好多泡沫哦！让我帮您从头到脚洗干净，这里也要仔细洗。这样洗怎么样？哦，前辈看起来很舒服嘛，我一眼就看出来了。嘿嘿嘿！",0,30.39]],"v_n005_001.mp3":[["喂喂，拜托啦！",0,2.98]],"v_n005_002.mp3":[["我是陆。",0,1.49]],"v_n005_003.mp3":[["哥！",0,1.66]],"v_n005_004.mp3":[["哇，谢谢！",0,1.99]],"v_n005_005.mp3":[["呜哇啊啊——！",0,0.99]],"v_n005_006.mp3":[["哇啊！",0,1.49]],"v_n005_007.mp3":[["今天也教我好多东西吧！真期待！",0,3.41]],"v_n005_008.mp3":[["因为光待在家里实在太无聊了嘛。",0,3.98]],"v_n005_009.mp3":[["学校里也很流行摸小鸡鸡哦。",0,4.99]],"v_n005_010.mp3":[["哥哥，今天你休息吧？那你就没理由拒绝我的请求啦。",0,7.75]],"v_n005_011.mp3":[["哥哥真厉害！接下来给我看什么呢？嗯……那就这个！",0,8.54]],"v_n005_014.mp3":[["没人能找到这里。这儿是咱俩的秘密基地啊。",0,5.67]],"v_n005_015.mp3":[["哥哥平时总关照我。要是我也能为哥哥做点什么就好了。",0,5.02]],"v_n005_016.mp3":[["就我们两个在一起的时候，我觉得像有了个亲哥哥一样，特别开心！",0,6.67]],"v_n005_017.mp3":[["锵锵！哥也跟朋友比过吗？我可是赢过不少次呢！",0,8.02]],"v_n005_018.mp3":[["这椅子可以放倒靠背哦。哥也过来嘛，我们一起睡午觉。",0,7.35]],"v_n005_030.mp3":[["哥哥，帮我洗洗身子嘛。",0,3]],"v_n005_031.mp3":[["一起泡澡嘛！哥哥也过来挨着我。背上到屁股都暖洋洋的，真舒服！啊，嘿嘿嘿……哥哥全都被看光了！我也是！嘿嘿！",0,27.07]],"v_n006_001.mp3":[["哟，我来了。",0,2.31]],"v_n006_002.mp3":[["我是 B。",0,1.4]],"v_n006_003.mp3":[["嗯？是你啊。",0,2.88]],"v_n006_004.mp3":[["挺有本事嘛。",0,1.91]],"v_n006_005.mp3":[["笨蛋……！",0,3.46]],"v_n006_006.mp3":[["什……！",0,2.68]],"v_n006_007.mp3":[["烦死了，别这么自来熟地吵吵！都说了我不是你朋友！",0,7.08]],"v_n006_008.mp3":[["答案又不止一个，自己好好想吧。",0,5.62]],"v_n006_009.mp3":[["你、你干什么啊！吓我一跳！",0,7.49]],"v_n006_010.mp3":[["喂，赶紧把门关上！被人看见后更麻烦的是你吧？",0,7.8]],"v_n006_011.mp3":[["没必要知道委托人是谁。那样对我也更方便。",0,6.58]],"v_n006_014.mp3":[["嗯？是你啊。嗯，我用得挺自在。多余的东西可别乱碰。",0,9.27]],"v_n006_015.mp3":[["就、就算只有咱俩，也别黏着我啊……",0,5.76]],"v_n006_016.mp3":[["哦，你也懂这毛茸茸的好处啊？",0,6.94]],"v_n006_017.mp3":[["你这笨蛋！你到底……可恶，我都不知道怎么接你这话了。",0,9.31]],"v_n006_018.mp3":[["跟这家伙在一起，真让人乱了节奏。算了，偶尔这样也不错。",0,13.15]],"v_n006_030.mp3":[["借你家浴池用一下啊。",0,1.559]],"v_n006_031.mp3":[["啊，糟了，泡太久，身体都有点发软了。干嘛，我正要出去呢！喂，借我肩膀扶一下……谢了。等、等等，你在摸哪里啊，混蛋！",0,29.77]],"v_n007_001.mp3":[["唰唰，唰唰。",0,1.128]],"v_n007_002.mp3":[["我就是小豆洗！",0,1.9]],"v_n008_007.mp3":[["有什么需要帮忙的吗？在下什么都能做！",0,5]],"v_n008_008.mp3":[["啊！我刚才太入迷了……这东西实在太好吃啦！嘿嘿！",0,14.23]],"v_n008_009.mp3":[["呜……干嘛老摸那种地方啊？害我都觉得怪怪的了。",0,8.38]],"v_n008_030.mp3":[["我去洗成一只香喷喷、毛茸茸的小熊。",0,2.793]],"v_n008_031.mp3":[["呼～真舒服的热水呢。嗯？被你这么盯着那种地方看，我也会害羞的啊。那么，我也回敬一下。盯——嘿嘿。",0,26.04]],"v_n009_007.mp3":[["嗯，盯着我看也没好处。你这样妨碍我工作了，回自己岗位去。要是抽烟休息，我倒可以陪你。",0,17.32]],"v_n009_008.mp3":[["执行程序……好，运行正常。等数据积累起来之前，先吃碗泡面吧。",0,11.87]],"v_n009_009.mp3":[["啊！喂……嗯，男人有时候也会这样吧。要是当研究对象我倒可以陪你……不，至少别在这里！",0,16.39]],"v_n009_030.mp3":[["泡澡啊……有点麻烦，不过正好能想想事情。",0,7.532]],"v_n009_031.mp3":[["喂，这地方挤两个男人也太窄了吧，进来前就该知道！可恶！我把脚搭你身上啊……好，这样总算宽敞点。喂，你在偷看什么？……算了，随你便。",0,31.67]],"v_n009_036.mp3":[["希望今年研究能出成果啊。你有什么目标吗？那就一起努力吧。",0,12.44]],"v_n009_037.mp3":[["我只是个凡人，新年也不能一直懒懒散散地休息。不过，陪你吃点东西还是可以的。嗯，真好吃！",0,15.16]],"v_n009_038.mp3":[["新年快乐。虽然也没什么好庆祝的。",0,4.86]],"v_n011_007.mp3":[["啊，不知道什么时候发工资！下次买点什么好呢？真让人期待！",0,10.59]],"v_n011_008.mp3":[["呼、呼……每次做完那项工作都累得不行。果然我还是更喜欢活动身体的工作。",0,12.22]],"v_n011_009.mp3":[["唔，那个……现在还在工作，而且您是客人，所以……我之后再来！",0,12.67]],"v_n011_010.mp3":[["老板，做点什么吧！把您制作东西的讲究都教教我！",0,6.78]],"v_n011_011.mp3":[["要是还要多做点，我可以继续努力！听说这样打工费也会增加！",0,9.87]],"v_n011_030.mp3":[["我去冲个澡，很快就回来。",0,2.112]],"v_n011_031.mp3":[["老板，你要帮我搓背？哎呀，真舒服！平时泡澡我总是很快就出来，今天干脆请你帮我从头到脚洗干净吧。待会儿我也会回报你的！",0,19.58]],"v_nag_000.mp3":[["魂これ！",0,0.81]],"v_nag_001.mp3":[["你终于呼唤了我的名字，主人。山阳道，长门。我们的故事就由此开始吧！",0,9.16]],"v_nag_002.mp3":[["又来找我了吗？不愧是你，主人。你隐藏的力量……就让我把它引导出来吧。来，握住我的手！",0,11.2]],"v_nag_003.mp3":[["守护世界的任务啊，挺浪漫的嘛。不过主人，细小的工作也不能马虎哦。",0,10.75]],"v_nag_004.mp3":[["我喜欢有气魄的大男人。主人，你也要成为了不起的人啊！",0,5.58]],"v_nag_005.mp3":[["喂，主人，你跳过太多步骤了！首先应该通过书信互诉心意，这才是常识吧！",0,11.94]],"v_nag_006.mp3":[["喂，你有在听吗？真是的，算了……嗯？什么，果然还是感兴趣吧！哼，知道了知道了，我继续说。话说……",0,24.18]],"v_nag_007.mp3":[["唔……为了做成大事，这点伤算不了什么！",0,5.763]],"v_nag_010.mp3":[["为了将来需要做些什么，你应该很清楚。",0,4.51]],"v_nag_015.mp3":[["水温正好。主人，待会儿见。",0,4.728]],"v_nag_016.mp3":[["主人，这姿势怎么想都很羞耻吧！喂，别从背后把手伸过来！",0,14.47]],"v_nag_024.mp3":[["主人，你来了。来好好谈谈我们的未来吧。请坐。",0,10.2]],"v_nag_025.mp3":[["眼镜啊……主人也要戴戴看吗？呵呵，还挺合适嘛。",0,13.54]],"v_nag_026.mp3":[["我知道，你是在奉承我吧？哼哼，可惜不会给你什么奖励。……握一下手倒是可以啦。",0,12.87]],"v_nag_027.mp3":[["怎么了？……我只是吓了一跳，又不是想让你抱我。可是主人……那个，能稍微待近一点的话，我会很高兴。",0,30.3]],"v_nag_028.mp3":[["嗯，主人，真是的……太纵容我了。喂，把眼睛闭上。明白了吗？",0,21.04]],"v_nag_029.mp3":[["即使不说话，只是这样并肩待着，也挺舒服的嘛。",0,5.6]],"v_nag_030.mp3":[["就让您瞧瞧长州男儿的本事吧。",0,3.5]],"v_nag_051.mp3":[["来，把接下来的故事继续讲下去吧。",0,3.37]],"v_nag_120.mp3":[["主人，一年之计在于元旦。想好今年要做什么了吗？还没的话，我们一起想吧。",0,13.28]],"v_nag_121.mp3":[["差不多该去初诣了。主人有什么愿望？不管是什么梦想，我一定帮你实现！我的梦想嘛……如果是主人，我可以特别告诉你。",0,17.14]],"v_nag_122.mp3":[["来吧，今年有什么计划？",0,3.56]],"v_not_000.mp3":[["魂これ！",0,1.64]],"v_not_001.mp3":[["主人！　我是能登哟~从今天开始努力进行新娘修行……嗯呀~！　摔倒了啊！",0,11.18]],"v_not_002.mp3":[["嗯呀~！？主人，谢谢你扶住我！我又摔倒了呢，在陆地上行走还真是困难啊！",0,13.51]],"v_not_003.mp3":[["主人，怎么了？工作让我帮忙吧！",0,6.41]],"v_not_004.mp3":[["啊！那里别挠啦，好痒！哈啾！",0,7.72]],"v_not_005.mp3":[["嗯呀，要嫁人，这也是很重要的事呢。",0,8.51]],"v_not_006.mp3":[["我要做一手好菜，成为好新娘！咦？怎么烧得黑乎乎的了？",0,10.21]],"v_not_007.mp3":[["嘿嘿，失败是成功之母嘛。",0,4.783]],"v_not_010.mp3":[["俺去挑门帘喽～",0,3.59]],"v_not_015.mp3":[["游呀游～在暖暖的水里游泳也好舒服呀！",0,8.592]],"v_not_016.mp3":[["嗯……被主人洗着真舒服。可是那里是能收起来的啦……嗯，稍、稍微温柔点洗哦。",0,20.69]],"v_not_024.mp3":[["主人，谢谢你今天过来。让我来招待你吧！",0,8.7]],"v_not_025.mp3":[["嗯呀，主人给我倒的酒，瞧，我全喝光啦！主人也再来一杯！",0,11.47]],"v_not_026.mp3":[["主人，不管什么时候，我都会陪在你身边。",0,10.66]],"v_not_027.mp3":[["先吃饭？先洗澡？还是……先吃我？开玩笑的啦！",0,10.8]],"v_not_028.mp3":[["哎呀，主人看上去真诱人呢！那我就让你瞧瞧我的新娘修行成果吧！",0,21.74]],"v_not_029.mp3":[["啊，咦？刚才做什么来着？跟主人一起喝了酒，然后……嗯，想不起来啦。",0,17.04]],"v_not_030.mp3":[["俺来帮忙。",0,2.61]],"v_not_051.mp3":[["能登啊，连泥土都这般温厚。",0,3.9]],"v_not_113.mp3":[["主人，我会帮你做各种事情哦！",0,7.2]],"v_not_114.mp3":[["好想让主人变得热热的！有什么愿望尽管告诉我，什么都行！",0,9.19]],"v_not_118.mp3":[["主人！",0,1.9]],"v_oki_000.mp3":[["魂、魂これ。",0,2.59]],"v_oki_001.mp3":[["我是山阴道的隐岐……啊，主人……您这样盯着我看，我、我会害羞的……呜呜……",0,11.72]],"v_oki_002.mp3":[["您居然一次又一次地叫我来……我很开心，可是也好害羞……我、我还是躲到后面去吧……！",0,10.37]],"v_oki_003.mp3":[["我、我其实挺喜欢运动的。不过一想到主人正在看着我……嗯……",0,11.97]],"v_oki_004.mp3":[["哥……啊不，主、主人！是主人！",0,6.7]],"v_oki_005.mp3":[["好、好痒！请住手！",0,5.57]],"v_oki_006.mp3":[["现在是休息时间，要不要去稍微活动一下身体呢？",0,5.97]],"v_oki_007.mp3":[["呜、呜呜……我会赶快……把伤治好……",0,6.238]],"v_oki_008.mp3":[["呃，那个……这件事已经做完了！",0,5.06]],"v_oki_009.mp3":[["哇——！",0,2.57]],"v_oki_010.mp3":[["这个真不错……哇，主人？！您、您一直在看啊？呜……",0,8.6]],"v_oki_012.mp3":[["我稍微……有点……习惯了。",0,5.16]],"v_oki_013.mp3":[["呀.....啊嗯......啊....",0,4.8]],"v_oki_014.mp3":[["请转过去。",0,5.36]],"v_oki_015.mp3":[["居然能一个人泡澡，好奢侈呀。",0,6.27]],"v_oki_016.mp3":[["平时被看着就够害羞了，要是光着身子被人看见……我、我可怎么办呀！",0,10.03]],"v_oki_017.mp3":[["呀啊！",0,1.13]],"v_oki_018.mp3":[["对、对不起。",0,2.08]],"v_oki_019.mp3":[["哇，谢谢您。不过您一直看着，我没法换衣服啊。",0,9.61]],"v_oki_020.mp3":[["在！",0,1.5]],"v_oki_021.mp3":[["啊，主人。",0,2.48]],"v_oki_022.mp3":[["诶？……哇啊啊～！？",0,3.02]],"v_oki_023.mp3":[["唔……嗯嗯……",0,2.37]],"v_oki_024.mp3":[["主人，欢迎光临。那个……如果有时间的话，能不能稍微坐一会儿？",0,9.04]],"v_oki_025.mp3":[["哇……我也挺喜欢相扑的。看着丰满的身体互相碰撞，不知不觉就会浑身使劲呢。",0,13.45]],"v_oki_026.mp3":[["啊，主人，那里不行！……我忘记关抽屉，内裤都被看见了。啊，好害羞！",0,11.87]],"v_oki_027.mp3":[["待在主人身边，我好像就会安心下来。",0,6.72]],"v_oki_028.mp3":[["啊，主人……好大，好暖和。那个，请……闭上眼睛。",0,13.46]],"v_oki_029.mp3":[["差不多该给大鲵喂食了。",0,3.5]],"v_oki_030.mp3":[["是、是！我会努力不引人注意的！",0,4.67]],"v_oki_031.mp3":[["那、那个，隐、隐岐要上了。",0,4.49]],"v_oki_032.mp3":[["那个……咦？",0,2.59]],"v_oki_033.mp3":[["看来得熬个通宵了。",0,2.23]],"v_oki_034.mp3":[["与神马一同冲过去！",0,2.7]],"v_oki_035.mp3":[["只要团结起来就没问题。",0,3.2]],"v_oki_036.mp3":[["悄悄瞄准……",0,2.13]],"v_oki_037.mp3":[["乘着潮流前进！",0,2.13]],"v_oki_038.mp3":[["头一下我可不能让给别人！",0,1.96]],"v_oki_039.mp3":[["请等一下。",0,1.86]],"v_oki_040.mp3":[["喝口水吧。",0,1.97]],"v_oki_041.mp3":[["不过我绝对不会把屁股朝过去。",0,4.14]],"v_oki_042.mp3":[["这次就把胜利让给你们吧。",0,3.06]],"v_oki_043.mp3":[["呜、哇！我变得太引人注目了……好难为情……",0,4.59]],"v_oki_044.mp3":[["刚才好险。",0,1.84]],"v_oki_045.mp3":[["也许是妖鲸在作祟……",0,2.19]],"v_oki_046.mp3":[["瞄准！",0,0.85]],"v_oki_047.mp3":[["不行啊！",0,0.8]],"v_oki_048.mp3":[["我要多撒些盐！",0,1.9]],"v_oki_049.mp3":[["最后一下！",0,1.01]],"v_oki_050.mp3":[["谢谢您。",0,1.91]],"v_oki_051.mp3":[["主人，请往里走。",0,4.85]],"v_oki_052.mp3":[["呃，我是隐州的隐岐。隐岐国从北到南，有大陆型、高山型等各种动植物共存，是个神奇的岛。啊，还、还有古典相扑和奉纳歌舞伎，有很多很棒的文化呢！",0,24.13]],"v_oki_057.mp3":[["主人，得到您的支持，我好开心。",0,7.5]],"v_oki_120.mp3":[["那个，年糕烤好了。还有好多岩海苔做的菜。您不介意的话……要一起吃吗？",0,13.58]],"v_oki_121.mp3":[["唉，新年有好多事情要做，真累人呢。所以能这样和主人一起悠闲地待着，我觉得真的很珍贵。",0,21.81]],"v_oki_122.mp3":[["我想去参加左义长烧火祭。",0,2.17]],"v_oki_123.mp3":[["我没关系，给其他人吧……可我还是想穿这件衣服跟主人一起过年。",0,18.45]],"v_oki_128.mp3":[["海底真的好漂亮，想一直看下去呢。",0,5.73]],"v_oki_129.mp3":[["主人喜欢鳄鱼吗？兔子君好像会害怕，不过我其实挺喜欢的。",0,11.6]],"v_oki_130.mp3":[["忍不住把脸转开了……",0,2.31]],"v_oki_131.mp3":[["我是鳄鱼。嗷呜一口！",0,3.143]],"v_osu_000.mp3":[["魂これ！",0,0.78]],"v_osu_001.mp3":[["在下是西海道的大隅，遥望着远方的樱岛。愿竭尽诚心，忠心侍奉主君。",0,8.31]],"v_osu_002.mp3":[["为了我敬爱的主君……就让我尽情施展这份力量吧。",0,5.2]],"v_osu_003.mp3":[["接下来要我帮什么忙？请尽管吩咐。",0,4.14]],"v_osu_004.mp3":[["不愧是主君，完成得真漂亮。",0,3.27]],"v_osu_005.mp3":[["啊，对、对不起，不小心发出了奇怪的声音……",0,4.77]],"v_osu_006.mp3":[["您看起来累了，我已经铺好被褥。",0,4.35]],"v_osu_007.mp3":[["啊，这伤是……那个……我在白砂台地摔了一跤，红薯就‘嚓’地一下……",0,7.657]],"v_osu_008.mp3":[["已经完成了呢。",0,1.4]],"v_osu_009.mp3":[["真不愧是位明君！",0,1.36]],"v_osu_010.mp3":[["要不我来记账吧？",0,2.13]],"v_osu_012.mp3":[["我身上流淌的熊袭之力，是为了守护大家。",0,4.34]],"v_osu_013.mp3":[["呜哇啊……！",0,1.52]],"v_osu_014.mp3":[["嗯？为了主公，无论多少次，我都愿效劳。",0,7.72]],"v_osu_015.mp3":[["那我就先去泡澡了。",0,2.31]],"v_osu_016.mp3":[["有哪里痒吗？……好大呢。触碰着您，就觉得特别安心。",0,13.25]],"v_osu_017.mp3":[["不行……已经……",0,2.1]],"v_osu_018.mp3":[["要上……啊！？",0,1.1]],"v_osu_019.mp3":[["我要换衣服了。可不能看哦。",0,4.01]],"v_osu_020.mp3":[["在。",0,0.71]],"v_osu_021.mp3":[["主公。",0,0.79]],"v_osu_022.mp3":[["主公？",0,3.1]],"v_osu_023.mp3":[["哇啊——",0,1.28]],"v_osu_024.mp3":[["啊，主君……那个，欢、欢迎光临。",0,6.31]],"v_osu_025.mp3":[["我的坏习惯，就是总对自己的事太随便。",0,3.1]],"v_osu_026.mp3":[["啊，请别看！我马上收拾好！",0,4.21]],"v_osu_027.mp3":[["毛摸起来很软吗？请尽管摸吧。",0,6.42]],"v_osu_028.mp3":[["我可能会叫得很大声……会不会传到外面去？啊，主君！",0,9.19]],"v_osu_029.mp3":[["真希望时间就这样停止……",0,3.87]],"v_osu_030.mp3":[["能跟诸位敬重的前辈并肩，我深感荣幸！",0,3.23]],"v_osu_031.mp3":[["我会竭尽全力！",0,1.61]],"v_osu_032.mp3":[["这是红薯吗？",0,3.26]],"v_osu_033.mp3":[["可以摸一下吗？",0,3.5]],"v_osu_034.mp3":[["我们往这边试试吧。",0,1.69]],"v_osu_035.mp3":[["想必您是位有名的妖怪。来，堂堂正正一决胜负！",0,3.45]],"v_osu_036.mp3":[["就是那儿！",0,0.9]],"v_osu_037.mp3":[["樱岛！",0,1.21]],"v_osu_038.mp3":[["弥五郎大人，赐我力量吧！",0,2.45]],"v_osu_039.mp3":[["啊！",0,0.83]],"v_osu_040.mp3":[["我中招了。",0,1.19]],"v_osu_041.mp3":[["果然没那么好对付。",0,3.11]],"v_osu_042.mp3":[["虽是对手，当真了得。",0,3.24]],"v_osu_043.mp3":[["全靠主公的调度，还有各位的通力合作。",0,3.86]],"v_osu_044.mp3":[["瞄得不错。",0,1.35]],"v_osu_045.mp3":[["我来断后。",0,1.4]],"v_osu_046.mp3":[["我来解决。",0,0.91]],"v_osu_047.mp3":[["我不会让牺牲白费的。",0,1.55]],"v_osu_048.mp3":[["我和您一同去。",0,0.92]],"v_osu_049.mp3":[["进展很顺利。",0,1.1]],"v_osu_050.mp3":[["谢谢您。",0,1.28]],"v_osu_051.mp3":[["主公，我们开始吧。",0,2.15]],"v_osu_052.mp3":[["我是大隅，和兄长们一起所在的袭国，曾是熊袭的根据地。日本武尊的名号可是熊袭建给的哦！不过他马上就被从屁股往上劈成两半了……",0,17.39]],"v_oum_000.mp3":[["魂これ！",0,3.11]],"v_oum_001.mp3":[["咱是东山道的近江。那好，就让我在这儿发上一笔财吧！",0,7.78]],"v_oum_002.mp3":[["少爷，承蒙您一直关照！顾问费可不能打折，不过附赠点东西倒是可以哦？",0,6.16]],"v_oum_003.mp3":[["嚯，真是件好货。这下应该能赚上一笔了。",0,6.75]],"v_oum_004.mp3":[["累了就喝这个，保证有效！喏，账单来了，我给你打了点折。",0,8.29]],"v_oum_005.mp3":[["喂、喂，你也太大胆了吧！可别拿大人寻开心啊！",0,7.81]],"v_oum_006.mp3":[["好了，去做生意赚大钱喽！",0,4.92]],"v_oum_007.mp3":[["要不要吃点止痛药呢？不行……那是要卖钱的……",0,5.158]],"v_oum_008.mp3":[["多谢惠顾！",0,1.62]],"v_oum_009.mp3":[["小少爷的财务报表，做得挺漂亮呀。",0,3.62]],"v_oum_010.mp3":[["有时候也得舍得下本钱呀。",0,3.12]],"v_oum_012.mp3":[["销路扩大啦！我也不会输给那些大商号！",0,4.13]],"v_oum_013.mp3":[["啊哈....啊.....",0,6.35]],"v_oum_014.mp3":[["唉，被小少爷看到我难为情的样子了……",0,7.64]],"v_oum_015.mp3":[["嗯～太舒服啦……",0,5.19]],"v_oum_016.mp3":[["少爷，你摸着我的肚子，觉得又滑又软吧？再这么摸下去，我也会摸遍少爷各处哦……嘿嘿。",0,13.01]],"v_oum_017.mp3":[["哈呜啊～～！",0,1.62]],"v_oum_018.mp3":[["这就上了呀！",0,1.62]],"v_oum_019.mp3":[["哎呀，小少爷看得好热切！那我就一口气脱了哦！",0,7.96]],"v_oum_020.mp3":[["哦，怎么啦？",0,1.62]],"v_oum_021.mp3":[["少爷。",0,0.61]],"v_oum_022.mp3":[["现在可不行呀！",0,4.16]],"v_oum_023.mp3":[["嗯～～，嗯嗯。",0,3.74]],"v_oum_024.mp3":[["少爷，欢迎光临！来来，慢慢坐！",0,5.63]],"v_oum_025.mp3":[["要不要牵个手试试？顺便……再进一步也行哦。",0,10.01]],"v_oum_026.mp3":[["呼，出了好多啊。好了，饭还没做好吗？",0,7.95]],"v_oum_027.mp3":[["少爷，我可从不撒谎。心里想什么就会老老实实说出来。",0,7]],"v_oum_028.mp3":[["少爷……那个……想摸我的身体也可以哦。",0,8.22]],"v_oum_029.mp3":[["少爷也渐渐长大，成了了不起的男人呢。",0,6.26]],"v_oum_030.mp3":[["就让我好好赚一笔吧！",0,2.12]],"v_oum_031.mp3":[["天南地北，咱们哪儿都去得！",0,3.13]],"v_oum_032.mp3":[["我就全拿走喽！",0,1.87]],"v_oum_033.mp3":[["可蒙不过我的眼睛哦！",0,2.62]],"v_oum_034.mp3":[["我走过的地方，连根草都不留！",0,3]],"v_oum_035.mp3":[["上喽，近江的千两天平！各位可得加把劲呀！",0,6.13]],"v_oum_036.mp3":[["来喽！",0,0.95]],"v_oum_037.mp3":[["得罪啦！",0,1.11]],"v_oum_038.mp3":[["连骨头都给你啃干净呀～！",0,2.88]],"v_oum_039.mp3":[["真够呛呀～～！",0,2.12]],"v_oum_040.mp3":[["噗呃～～！",0,1.43]],"v_oum_041.mp3":[["回、回不了本啊！",0,3.38]],"v_oum_042.mp3":[["错过好商机啦！",0,3.14]],"v_oum_043.mp3":[["叮叮当当，响起来喽～",0,3.12]],"v_oum_044.mp3":[["还不够呢！",0,0.78]],"v_oum_045.mp3":[["也太不争气了吧！",0,1.61]],"v_oum_046.mp3":[["逮到猎物啦！",0,1.13]],"v_oum_047.mp3":[["我可要加把劲了！",0,1.61]],"v_oum_048.mp3":[["我也顺势来一下！",0,1.11]],"v_oum_049.mp3":[["再送你一下！",0,1.12]],"v_oum_050.mp3":[["多谢啦！",0,1.42]],"v_oum_051.mp3":[["一、二、三，赚了好多呀～！",0,4.79]],"v_oum_052.mp3":[["我是江州的近江。「近淡海」这个别称，指的是离都城很近的淡水湖，也就是琵琶湖。近江商人走遍各地卖东西！我也要好好赚钱呀！",0,18.93]],"v_oum_120.mp3":[["少爷，开店啦！虽说过年了，可这正是商人赚钱的时候，哪能休息啊。少爷也来帮点忙吧，我会给零花钱的。",0,10.06]],"v_oum_121.mp3":[["还剩一瓶屠苏酒，难得有机会，少爷咱俩一起喝吧！来，倒得满满的，把晦气都赶走！",0,13.27]],"v_oum_122.mp3":[["新的一年也请多多惠顾！",0,2.09]],"v_owa_000.mp3":[["魂之所在！",0,1.3]],"v_owa_001.mp3":[["哈哈哈！本大爷是统治天下之人。东海道的尾张！让你见识见识最棒的理想吧！！",0,10.3]],"v_owa_002.mp3":[["哈哈哈！你还想要更多本大爷的力量吗！好啊！",0,6.05]],"v_owa_003.mp3":[["你是本大爷的主人，给我堂堂正正地挺起胸膛！",0,5.21]],"v_owa_004.mp3":[["命运要由自己亲手选择。",0,3.38]],"v_owa_005.mp3":[["摸起来怎么样？尾张的“大萝卜”可是出了名的气派呢！哈哈哈！",0,7.03]],"v_owa_006.mp3":[["哼，竟敢让本大爷久等！",0,3.74]],"v_owa_007.mp3":[["能让本大爷挂彩，真是个了不得的高手……",0,4.176]],"v_owa_008.mp3":[["干得好，值得我夸你一句。",0,2.43]],"v_owa_009.mp3":[["还得请你再加把劲啊。",0,3.3]],"v_owa_010.mp3":[["讲价就交给本大爷！",0,1.55]],"v_owa_012.mp3":[["痛快极了！",0,3.95]],"v_owa_013.mp3":[["唔……嗯……！",0,4.428]],"v_owa_014.mp3":[["快意得都能和夺取天下相比了。我更想要你了。",0,7.09]],"v_owa_015.mp3":[["呼，这水真舒服啊……",0,3.53]],"v_owa_016.mp3":[["主人啊，赏你一个替本大爷冲洗身体的荣幸。先转过身去。……嗯？本大爷还这么精神，你不就不好洗了吗？",0,12.14]],"v_owa_017.mp3":[["唔嗯……喵啊～～",0,2.69]],"v_owa_018.mp3":[["把这当作你的荣幸吧。",0,1.78]],"v_owa_019.mp3":[["要本大爷穿这个？哼，倒也不赖。",0,4.78]],"v_owa_020.mp3":[["哼哈哈哈哈！",0,2.3]],"v_owa_021.mp3":[["主人，原来你在这儿。",0,1.65]],"v_owa_022.mp3":[["嗯喵！？",0,0.73]],"v_owa_023.mp3":[["喵啊？！",0,1.92]],"v_owa_024.mp3":[["欢迎来到我的本丸。尽情享受吧！",0,4.01]],"v_owa_025.mp3":[["本大爷喜欢相扑！快把衣服脱了！",0,3.3]],"v_owa_026.mp3":[["身为将领，偶尔也需要休息身体。就赏你枕一下本大爷的膝盖吧。",0,7.69]],"v_owa_027.mp3":[["想给本大爷揉背？不错的心意。好！喵！太用力啦，蠢货！",0,9.55]],"v_owa_028.mp3":[["接招吧，本大爷的秘技三段连击！给我好好接住……啊！？",0,8.31]],"v_owa_029.mp3":[["真是毫无防备……还露出那种可爱的笑容。",0,5.5]],"v_owa_030.mp3":[["本大爷就助你一臂之力。",0,2.302]],"v_owa_031.mp3":[["哈哈哈哈哈！这指挥不错！",0,3.5]],"v_owa_032.mp3":[["谁想要，本大爷就赏给谁。",0,2.3]],"v_owa_033.mp3":[["派人去看看情况",0,2.05]],"v_owa_034.mp3":[["干什么呢？走这边！",0,2.3]],"v_owa_035.mp3":[["哈哈哈哈！烧光他们！",0,3.33]],"v_owa_036.mp3":[["别把本大爷惹火了。",0,2.3]],"v_owa_037.mp3":[["无趣。",0,1.3]],"v_owa_038.mp3":[["看这把夺得天下的刀！",0,3.47]],"v_owa_039.mp3":[["唔。",0,1.3]],"v_owa_040.mp3":[["喵呜！",0,1.05]],"v_owa_041.mp3":[["……哈哈哈，挺有两下子嘛。",0,5.02]],"v_owa_042.mp3":[["唔！先往后撤……",0,3.46]],"v_owa_043.mp3":[["各位也都干得不错。哈哈哈哈！",0,4]],"v_owa_044.mp3":[["就这点本事？",0,1.53]],"v_owa_045.mp3":[["真不知天高地厚！",0,1.3]],"v_owa_046.mp3":[["致命一击！",0,1.01]],"v_owa_047.mp3":[["太迟了！",0,1.02]],"v_owa_048.mp3":[["剩下的交给我吧",0,1.52]],"v_owa_049.mp3":[["结束了！",0,1.09]],"v_owa_050.mp3":[["我要向你道谢。",0,1.35]],"v_owa_051.mp3":[["哈哈哈，开始吧。",0,3.47]],"v_owa_052.mp3":[["本大爷就是终焉之国尾张。以前还有「名古屋繁华，连京都都相形失色」的说法。不愧是夺得天下的国吧！哈哈哈！什么，三河？……那种装模作样的家伙，本大爷不认识。",0,20.14]],"v_owa_120.mp3":[["嗯，迎来新年了啊。来，出门去！你也赶快换上新年礼服。和本大爷一起看新年第一道日出，可不是寻常体验。",0,13.32]],"v_owa_121.mp3":[["大正月就咱们两个人，还真是别有情趣。来，先吃杂煮吧！炖肉块配清汤果然最棒……喂，你握着我的手，我怎么吃啊？",0,15.55]],"v_owa_122.mp3":[["今年一定要统一天下！",0,2.59]],"v_rko_000.mp3":[["是魂これ呀！",0,1.11]],"v_rko_001.mp3":[["我是东山道的尽头，奥州的陆奥。你就是我的主人吗。弟弟们或许会给你添不少麻烦，就拜托你了！",0,11.11]],"v_rko_002.mp3":[["呼，主人。你找我吗？我正好在锻炼呢。好了，身体也活动开了，来干活吧！有什么事尽管和我说！",0,13.09]],"v_rko_003.mp3":[["一旦决定了，就要坚持到底！有难处也要好好告诉俺，明白吗？",0,7.96]],"v_rko_004.mp3":[["主人，苹果削好了。一起吃吗？好啦，别洒了，张嘴，啊——嗯，对对，真乖。",0,11.83]],"v_rko_005.mp3":[["啊，果然吓到你了。最近老是在忍耐，不小心就有反应了。嘿嘿。",0,11.79]],"v_rko_006.mp3":[["呼……不行，已经到极限了……再超越一次！今天的肌肉训练就到这里！",0,23.72]],"v_rko_007.mp3":[["疼疼疼……呃，主人，现在碰的话……呜、唔，我会忍住的……不过，就到这儿吧……",0,16.729]],"v_rko_010.mp3":[["东西都交给俺拿吧。顺便买点做饭的材料？",0,6.01]],"v_rko_015.mp3":[["我可一定要泡到最后一个才出去！……唔！",0,7.296]],"v_rko_016.mp3":[["主人也一起泡吗？这里有空位。哦，挨得挺紧的呢！啊，到处都碰到了，忍耐一下哦……不，我自己好像都忍不住了。嘿嘿。",0,24.17]],"v_rko_024.mp3":[["哦，主人，来啦！刚锻炼出了一身汗，先换衣服吧。稍、稍等一下啊！",0,13.68]],"v_rko_025.mp3":[["怎么了，累了吗？每天都这么努力呢。今天就在这里慢慢休息吧。乖乖，真是个好孩子。",0,13.43]],"v_rko_026.mp3":[["主人，肚子饿了吗？我做拿手的锅饭给你吃。可好吃了，期待一下吧！",0,8.58]],"v_rko_027.mp3":[["嗯，我正收拾弟弟们的衣服和毛巾呢。顺便也把主人的衣服叠起来吧。别害羞嘛。",0,11.52]],"v_rko_028.mp3":[["主人……俺也是真男人。今天已经忍不住啦。积攒了这么久，你不会说不要吧？",0,25.66]],"v_rko_030.mp3":[["好，大伙儿一块儿蹦起来吧！",0,3.07]],"v_rko_051.mp3":[["哟，没冻着吧？俺来给你暖暖身子。",0,5.03]],"v_sag_000.mp3":[["魂これ！",0,1.47]],"v_sag_001.mp3":[["我、我是东海道的相模。……那个，我还想继续做研究，能不能……别来打扰我……",0,10.9]],"v_sag_002.mp3":[["……那个……请别管我……",0,4.46]],"v_sag_003.mp3":[["那个！给、给我仔细看看！",0,4.92]],"v_sag_004.mp3":[["哦，我研究得太入神，没发现你来了。",0,4.87]],"v_sag_005.mp3":[["要比较一下？好啊，来，快点。",0,8.71]],"v_sag_006.mp3":[["我、我站着都能睡着哦。",0,4.75]],"v_sag_007.mp3":[["呀……希望你别这样。",0,3.43]],"v_sag_008.mp3":[["出了挺多的哦。",0,2.57]],"v_sag_009.mp3":[["记录很重要……对吧。",0,3.26]],"v_sag_010.mp3":[["这个……回去后试试看吧。",0,5.38]],"v_sag_012.mp3":[["身体有反应了。啊，真有意思。",0,5.98]],"v_sag_013.mp3":[["来、来了，来了……",0,3.41]],"v_sag_014.mp3":[["唔……没想到这么舒服。真是个新发现啊。",0,7.95]],"v_sag_015.mp3":[["泡在浴缸里想事情……真开心。",0,4.23]],"v_sag_016.mp3":[["诶……因为我一直在想着你，所以这应该是正常反应吧？",0,11.28]],"v_sag_017.mp3":[["舒服啊……",0,1.78]],"v_sag_018.mp3":[["我、我来帮你开发一下吧！",0,3.34]],"v_sag_019.mp3":[["我穿上了。怎、怎么样，主人？你的反应真不错。",0,8.04]],"v_sag_020.mp3":[["什、什么？",0,2.35]],"v_sag_021.mp3":[["啊，主人。",0,2.14]],"v_sag_022.mp3":[["你也一起来吧！",0,3.94]],"v_sag_023.mp3":[["真舒服呀。",0,3.72]],"v_sag_024.mp3":[["哦，主人？我又忘了锁门。",0,7.15]],"v_sag_025.mp3":[["你看，这个不错吧？我可是拿自己的身体做研究呢。",0,8.28]],"v_sag_026.mp3":[["有关身体的数据，我把大家的都记下来了哦。",0,7.7]],"v_sag_027.mp3":[["主人来到我的研究室……真开心啊。",0,8.16]],"v_sag_028.mp3":[["想观察一下？可以哦，我会乖乖不动的。",0,9.98]],"v_sag_030.mp3":[["请……请多关照……",0,2.62]],"v_sag_031.mp3":[["研究成果必须展示出来",0,2.95]],"v_sag_032.mp3":[["我、我来查一下。",0,2.28]],"v_sag_033.mp3":[["这是什么原理……真让人在意呀！",0,2.57]],"v_sag_034.mp3":[["是按方忌改道时看到的。",0,1.8]],"v_sag_035.mp3":[["啊，实战数据……我要记录下来……",0,4.51]],"v_sag_036.mp3":[["我能检查一下你的身体吗？",0,3.63]],"v_sag_037.mp3":[["哇啊……好有意思的形状。",0,3.17]],"v_sag_038.mp3":[["我已经没兴趣了。",0,1.83]],"v_sag_039.mp3":[["嗯。",0,0.34]],"v_sag_040.mp3":[["好、好疼。",0,1.78]],"v_sag_041.mp3":[["啊，别太抵抗……",0,4.78]],"v_sag_042.mp3":[["我先回去了。",0,1.23]],"v_sag_043.mp3":[["我拿到珍贵的数据了。",0,5.21]],"v_sag_044.mp3":[["往近畿的方向。",0,1.95]],"v_sag_045.mp3":[["嗯……唔。",0,1.59]],"v_sag_046.mp3":[["拿着沉甸甸长竿的人。",0,1.66]],"v_sag_047.mp3":[["正处在发育期的你。",0,1.95]],"v_sag_048.mp3":[["含苞的小家伙。",0,1.35]],"v_sag_049.mp3":[["闪着黑亮光泽的你。",0,1.83]],"v_sag_050.mp3":[["啊，谢谢。",0,2.02]],"v_sag_051.mp3":[["让、让我调查一下哦。",0,2.71]],"v_sag_052.mp3":[["我是相州的相模。镰仓、箱根、小田原，还有湘南的蓝海……哪儿都好。我想，武藏其实说不定是我哥哥……要保密哦。",0,24.94]],"v_sag_106.mp3":[["根据之前调查的数据，我准备了大家可能喜欢的礼物。怎、怎么样？",0,10.22]],"v_sag_107.mp3":[["如果主人也能送我礼物，我会很高兴的。无论什么，我都会试试看。",0,11.78]],"v_sag_111.mp3":[["圣诞快乐……呢。",0,3.35]],"v_sag_128.mp3":[["我也想体验现代文化。我、我也要试试冲浪板！",0,8.2]],"v_sag_129.mp3":[["嗯，这件泳装太紧了。主人，能帮我穿吗？嗯……啊！好像穿进去了！",0,19.33]],"v_sag_130.mp3":[["要是大一点就好了呢。",0,1.51]],"v_san_000.mp3":[["魂之所在！",0,0.93]],"v_san_001.mp3":[["我是南海道、四国的赞岐！主人！我一定会派上用场的！",0,6.7]],"v_san_002.mp3":[["主人！嘿嘿，俺做的乌冬面，你喜欢吗？",0,5.57]],"v_san_003.mp3":[["啊！嘿嘿，是主人啊！",0,4.92]],"v_san_004.mp3":[["别揉俺啦，来揉乌冬面嘛～",0,3.61]],"v_san_005.mp3":[["啊！别摸奇怪的地方啦，真是的！",0,5.15]],"v_san_006.mp3":[["对了，给主人做点乌冬面吧！",0,3.47]],"v_san_007.mp3":[["喉咙好干啊。",0,2.46]],"v_san_008.mp3":[["工作做完啦！",0,1.46]],"v_san_009.mp3":[["主人，好厉害啊！",0,2.85]],"v_san_010.mp3":[["买好多好多吧！",0,1.63]],"v_san_012.mp3":[["我有没有好好变强呢？",0,3.34]],"v_san_013.mp3":[["啊……啊……",0,3.572]],"v_san_014.mp3":[["啊……啊！哈……主人，真厉害啊。俺已经一点劲儿都没有啦……",0,12.89]],"v_san_015.mp3":[["俺的热乌冬做好啦～",0,3.672]],"v_san_016.mp3":[["浴缸挤得满满的……我们都像乌冬面一样缠在一起啦！",0,7.32]],"v_san_017.mp3":[["唔……俺……山药泥乌冬……",0,4.458]],"v_san_018.mp3":[["劲道才要紧嘛。",0,1.881]],"v_san_019.mp3":[["嘿嘿，俺穿着合适吗？",0,2.897]],"v_san_020.mp3":[["好～！",0,0.921]],"v_san_021.mp3":[["主人！",0,1.606]],"v_san_022.mp3":[["哇！这、这是……那个……",0,4.008]],"v_san_023.mp3":[["哇！",0,1.111]],"v_san_024.mp3":[["啊，主人！？踩那里！往这边跳！",0,5.1]],"v_san_025.mp3":[["俺不太会收拾……怕是当不了个好媳妇了吧……",0,5.76]],"v_san_026.mp3":[["靠吃乌冬面省钱的话，就可以买好多衣服了吧？",0,4.46]],"v_san_027.mp3":[["啊，主人，我们好像挨得特别近呢。",0,6.27]],"v_san_028.mp3":[["啊，毕竟只有我们两个人嘛。这种事……只会和主人做哦。",0,9.11]],"v_san_029.mp3":[["我也在主人身边睡吧！",0,3.24]],"v_san_030.mp3":[["俺要好好加油啦！",0,1.82]],"v_san_031.mp3":[["哇哇，俺当队长啦！",0,2.824]],"v_san_032.mp3":[["亮闪闪的呀！",0,2.04]],"v_san_033.mp3":[["是什么呀？",0,1.28]],"v_san_034.mp3":[["这边！……俺是这么想的啦……",0,3.5]],"v_san_035.mp3":[["为了主人，也为了好吃的乌冬面……！",0,3.6]],"v_san_036.mp3":[["嘿呀！",0,1.35]],"v_san_037.mp3":[["要是打疼你了，先说声对不起哦！",0,1.76]],"v_san_038.mp3":[["水神式投球！",0,2.69]],"v_san_039.mp3":[["啊！",0,0.53]],"v_san_040.mp3":[["好疼啊！",0,1.38]],"v_san_041.mp3":[["呜哇！俺才不会输呢！",0,3.57]],"v_san_042.mp3":[["撑不住了……让俺歇一下吧。",0,3.53]],"v_san_043.mp3":[["主人，俺做到了！",0,2.74]],"v_san_044.mp3":[["太好啦！",0,1.55]],"v_san_045.mp3":[["呜哇！",0,1]],"v_san_046.mp3":[["找到啦！",0,1.01]],"v_san_047.mp3":[["你还好吧？",0,1.1]],"v_san_048.mp3":[["包在俺身上！",0,1.19]],"v_san_049.mp3":[["该结束啦！",0,1.17]],"v_san_050.mp3":[["谢谢啦！",0,1.69]],"v_san_051.mp3":[["俺开动啦～！",0,1.62]],"v_san_052.mp3":[["俺是赞州的赞岐！赞岐国雨水少，所以大家修了好多蓄水池，一直都很珍惜用水。说到俺，当然是又滑溜又筋道的乌冬面啦！希望你来吃个饱哦！",0,21.38]],"v_san_106.mp3":[["圣诞快乐，主人！这是圣诞树哦。我想请你把这颗星星挂在树顶，我来挂其他装饰！",0,10.7]],"v_san_107.mp3":[["啊，主人，今天是神圣的日子吧。能和主人一起过这一天，我好开心！",0,13.08]],"v_san_111.mp3":[["铃儿叮当响～！",0,1.2]],"v_san_120.mp3":[["主人，跨年乌冬面准备好了！还有好多，记得多添几碗哦。啊，也可以换个口味！",0,9.89]],"v_san_121.mp3":[["主人，吃年糕和乌冬面可能会长胖，但过年嘛，没关系吧？今天悠闲点，好好吃个够！",0,12.05]],"v_san_122.mp3":[["红豆馅年糕杂煮做好啦～！",0,2.11]],"v_san_128.mp3":[["主人，想去海里游，还是去蓄水池？啊，说错啦，是泳池！俺去哪儿都行，就是想和主人一起去嘛～。",0,11.99]],"v_san_129.mp3":[["玩得精疲力尽了呢，主人。虽然该去冲澡，但这样一起躺着，我也困起来了……啊……",0,19.67]],"v_san_130.mp3":[["我还能潜得更深哦！",0,2.94]],"v_sat_000.mp3":[["魂これ！",0,1.08]],"v_sat_001.mp3":[["我是西海道的萨摩。我不喜欢说废话。有事我来挡，我来扛，这样就好！",0,13.39]],"v_sat_002.mp3":[["西海道、萨摩，应召唤而来。有什么困难就和我说吧。这就是我的职责。",0,12.66]],"v_sat_003.mp3":[["主人，别去俺看不见、也保护不到的地方，明白了吗？",0,10.07]],"v_sat_004.mp3":[["嗯，有事就开口说嘛。……我可没说不让你摸，没关系的。",0,13.45]],"v_sat_005.mp3":[["喂，工作时可不能做这种事，主人。在俺先出手之前，得乖乖等着。",0,12.96]],"v_sat_006.mp3":[["没事发生之前就先待命……嗯？刚才是不是差点睡着了？",0,15.19]],"v_sat_007.mp3":[["嗯？啊，就这点小伤，不用担心。没什么大不了的！",0,9.696]],"v_sat_010.mp3":[["有想买的东西？行，去吧。我帮你看着周围。至于买什么，我不打听。",0,10.74]],"v_sat_015.mp3":[["呼……疲劳一下就散了，真是好汤啊。",0,8.208]],"v_sat_016.mp3":[["主人，帮俺搓搓背吧。嗯，真是舒服极了！接下来轮到俺，你坐那儿，让俺给你洗干净。……喂，别那么看着我呀！嘿嘿。",0,26.95]],"v_sat_024.mp3":[["哦，欢迎！来，进屋坐吧，找个空位就行。俺给你泡茶。",0,10.15]],"v_sat_025.mp3":[["哦，最近越来越熟练了嘛。好好好，以后俺也会仔细教导你的。",0,12.76]],"v_sat_026.mp3":[["主人，稍微换件衣服。嗯？你觉得这个稀奇吗？我也是继承了熊的血脉，毛多自然是理所当然的。",0,15.87]],"v_sat_027.mp3":[["有烦恼尽管说。虽说俺更擅长用行动解决。这样也行？那就说给俺听听。",0,12.72]],"v_sat_028.mp3":[["哦，哈哈！主人净想着那种事嘛！好好好，今天就把你染上俺的颜色。做好准备吧！",0,24.66]],"v_sat_029.mp3":[["俺已经习惯和别人肩并肩躺着了，挤一点才刚刚好。来，再靠近些。",0,12.76]],"v_sat_030.mp3":[["今天起就是同一队的啦，多关照！",0,4.69]],"v_sat_051.mp3":[["主公，来啦？走，跟我来！",0,5.52]],"v_sim_000.mp3":[["魂これ，啊哈哈！",0,2.05]],"v_sim_001.mp3":[["我是东海道的志摩！哥哥你个头好大呀～！哈哈，真让人期待！",0,6.45]],"v_sim_002.mp3":[["哥哥，还要再来一份？我给你盛得满满的！",0,3.41]],"v_sim_003.mp3":[["多吃点，长得再大一些哦！",0,2.65]],"v_sim_004.mp3":[["软乎乎的～！呜啾～！",0,2.73]],"v_sim_005.mp3":[["诶嘿，好痒呀……哇哈哈！",0,3.26]],"v_sim_006.mp3":[["做顿营养满满的大餐吧！",0,2.03]],"v_sim_007.mp3":[["这伤可是我努力过的证明呢。",0,2.500396]],"v_sim_008.mp3":[["哥哥，来啊！",0,1.29]],"v_sim_009.mp3":[["感觉像个大人了！",0,2.27]],"v_sim_010.mp3":[["我想试试这种食材。",0,2.61]],"v_sim_012.mp3":[["我感觉得到，我变强了！",0,2.1]],"v_sim_013.mp3":[["呜呜……",0,2.05]],"v_sim_014.mp3":[["哇哇哇哇～哥，你该不会把我变成大人了吧？……耶！",0,6.36]],"v_sim_015.mp3":[["啊哈哈，我要潜下去啦！",0,2.136]],"v_sim_016.mp3":[["原来大人就是这种感觉啊！诶、诶，好帅！",0,7.46]],"v_sim_017.mp3":[["什么，这东西……",0,1.54]],"v_sim_018.mp3":[["啊，有点不对劲……",0,2.41]],"v_sim_019.mp3":[["哥哥，我穿上啦！你看，你看！",0,2.54]],"v_sim_020.mp3":[["啊哈哈。",0,1.1]],"v_sim_021.mp3":[["哥哥！",0,0.66]],"v_sim_022.mp3":[["被看见啦！",0,3.1]],"v_sim_023.mp3":[["呀啊！",0,0.78]],"v_sim_024.mp3":[["哥哥，哥哥，肚子饿不饿？",0,2.47]],"v_sim_025.mp3":[["越是睡前，越要吃顿丰盛的大餐！",0,2.65]],"v_sim_026.mp3":[["做些什么才会得到夸奖呢？",0,2.13]],"v_sim_027.mp3":[["哥哥，你比以前长得更大了！",0,3.21]],"v_sim_028.mp3":[["啊、呀！咦……那、那是什么？感觉怪怪的……呃、呜……",0,8.863]],"v_sim_029.mp3":[["晚上去厕所好可怕啊……",0,5.33]],"v_sim_030.mp3":[["大家，我好想你们！姆啾——！",0,3.63]],"v_sim_031.mp3":[["我一定努力！",0,1.29]],"v_sim_032.mp3":[["送给哥哥吧。",0,1.09]],"v_sim_033.mp3":[["嗯？",0,2.26]],"v_sim_034.mp3":[["我们去试试看",0,1.66]],"v_sim_035.mp3":[["大家一起战斗，真开心～",0,2.48]],"v_sim_036.mp3":[["我来把你做成菜！",0,1.39]],"v_sim_037.mp3":[["姆啾——！",0,1.09]],"v_sim_038.mp3":[["给我变成今晚的配菜吧！",0,1.89]],"v_sim_039.mp3":[["呀啊～！",0,0.86]],"v_sim_040.mp3":[["疼！",0,0.63]],"v_sim_041.mp3":[["啊……消毒、消毒！",0,3.56]],"v_sim_042.mp3":[["呜，好不甘心啊！",0,2.9]],"v_sim_043.mp3":[["太好啦！我厉不厉害？厉不厉害？嘿嘿。",0,3.65]],"v_sim_044.mp3":[["啊！",0,0.43]],"v_sim_045.mp3":[["骗人！",0,0.99]],"v_sim_046.mp3":[["找到啦！",0,0.74]],"v_sim_047.mp3":[["还给你这一招！",0,0.97]],"v_sim_048.mp3":[["看起来真好吃！",0,0.79]],"v_sim_049.mp3":[["最后了！",0,0.81]],"v_sim_050.mp3":[["谢谢！",0,0.8]],"v_sim_051.mp3":[["快快长大吧！",0,1.53]],"v_sim_052.mp3":[["我是东海道、志州的志摩！作为给朝廷供食的御食国，我们从前向宫里进献海产！为了伊势哥哥，我什么都愿意做！",0,10.61]],"v_sin_000.mp3":[["这里是《魂これ》哦！",0,1.6]],"v_sin_001.mp3":[["东山道的信浓就是我。吃个饭、歇一歇，然后就开始学习喽！",0,6.91]],"v_sin_002.mp3":[["哦，主人，有问题想问？行啊！我最喜欢有干劲的人了！",0,8.01]],"v_sin_003.mp3":[["哦，主人，越来越熟练了嘛！我真高兴！",0,6.3]],"v_sin_004.mp3":[["你们都是好样的！嗯，果然大家一起吃最香啊！",0,9.07]],"v_sin_005.mp3":[["哥、哥哥……这、这种事，我可会为难的！",0,7.73]],"v_sin_006.mp3":[["嗯，我也在学习啊。需要学的东西可多着呢！",0,7.39]],"v_sin_007.mp3":[["蜂蛹、石蝇幼虫，多吃点有营养的东西就没事啦。",0,6.306771]],"v_sin_008.mp3":[["这得给你画个大红花啊。",0,2.3]],"v_sin_009.mp3":[["这就是你的成绩啊！",0,2.83]],"v_sin_010.mp3":[["哦，这一大块肉看着真香啊。",0,4.62]],"v_sin_012.mp3":[["哦～太厉害了。这份恩情，我绝不会忘记！",0,6.7]],"v_sin_013.mp3":[["啊........",0,3.04]],"v_sin_014.mp3":[["呜哦哦……唔……真、真不错啊！我好久没这么心跳加速了。",0,11.55]],"v_sin_015.mp3":[["不会吧，我有那么大味儿吗？去冲个澡吧。",0,4.92]],"v_sin_016.mp3":[["能帮我搓背吗？谢啦。喂喂，那里不用洗啊！喂！",0,10.8]],"v_sin_017.mp3":[["好啦！",0,2.3]],"v_sin_018.mp3":[["实战时间到了啊！",0,2.3]],"v_sin_019.mp3":[["穿上了，真不错啊",0,3.3]],"v_sin_020.mp3":[["哦。",0,1.12]],"v_sin_021.mp3":[["是主人啊。",0,1.3]],"v_sin_022.mp3":[["喂、喂！你在看什么？",0,3.3]],"v_sin_023.mp3":[["呃……唔……哈、唔……哈啊……",0,6.18]],"v_sin_024.mp3":[["来来，进来坐。今天我亲自辅导你学习！",0,7.46]],"v_sin_025.mp3":[["房间里有点热啊，汗都出来了。",0,5.13]],"v_sin_026.mp3":[["嗯，嗯，好吃！果然我还是喜欢味道浓一点的啊。",0,6.09]],"v_sin_027.mp3":[["马的毛色也不错，不过……我也喜欢你摸起来的感觉。",0,7.28]],"v_sin_028.mp3":[["一旦开始，就停不下来啦！",0,7.57]],"v_sin_029.mp3":[["嗯……我的被褥不会有味道吧？",0,6.28]],"v_sin_030.mp3":[["看来能学到不少东西。",0,2.3]],"v_sin_031.mp3":[["好嘞，咱们商量怎么进攻吧",0,3.3]],"v_sin_032.mp3":[["有谁注意到那个东西了吗？",0,2.3]],"v_sin_033.mp3":[["好好观察四周啊",0,2.59]],"v_sin_034.mp3":[["大家别掉队哦。",0,2.3]],"v_sin_035.mp3":[["战术上占了优势，大家别慌，稳住",0,4.39]],"v_sin_036.mp3":[["进攻才是最强的防御啊",0,2.89]],"v_sin_037.mp3":[["大家多看仔细点。",0,2.3]],"v_sin_038.mp3":[["关键时刻，要一口气冲上去！",0,2.34]],"v_sin_039.mp3":[["呜哦！",0,0.9]],"v_sin_040.mp3":[["要吃点什么吗？",0,2.3]],"v_sin_041.mp3":[["哇，衣服撕破了！",0,3.34]],"v_sin_042.mp3":[["对不住，大伙儿。我先回去了。",0,4.3]],"v_sin_043.mp3":[["因为每个人都很到位地完成了自己的职责啊",0,3.93]],"v_sin_044.mp3":[["太可惜了啊！",0,1.66]],"v_sin_045.mp3":[["作战计划要变更了",0,1.88]],"v_sin_046.mp3":[["我瞄着松懈的地方下手！",0,1.88]],"v_sin_047.mp3":[["冲得太前了",0,1.88]],"v_sin_048.mp3":[["集中攻击啊",0,1.88]],"v_sin_049.mp3":[["别松懈啊～",0,1.88]],"v_sin_050.mp3":[["干得不错啊。",0,1.69]],"v_sin_051.mp3":[["好嘞，大家都坐好！",0,2.53]],"v_sin_052.mp3":[["我是信州的信浓。信浓国以前有很多寺子屋。听说这边有「信浓的灯笼学校」，老师们留在学校讨论到深夜。大伙儿都给我好好学习啊！",0,19.69]],"v_sin_106.mp3":[["孩子们，来，上课啦！",0,5.89]],"v_sin_107.mp3":[["想让我教什么呢？老师什么都会教你们！",0,5.5]],"v_sin_111.mp3":[["喂！别在走廊上跑！",0,2.301]],"v_sin_120.mp3":[["哦，主人，要不要去初诣？外头冷，记得穿暖和点！",0,7.78]],"v_sin_121.mp3":[["果然过年还是吃年糕、待在屋里悠闲最好啊。主人也来挨着我一起吧？瞧，我多烤点给你！",0,11.93]],"v_sin_122.mp3":[["今年看来也会是个好年头！",0,3.19]],"v_sin_123.mp3":[["过年也得有过年的打扮嘛。主人，方便的话能帮我挑一身吗？",0,8.3]],"v_sin_128.mp3":[["要练游泳吗？我从下面托着你！",0,4.53]],"v_sin_129.mp3":[["得练练人工呼吸才行。好，能陪我练习一下吗？",0,6.34]],"v_sin_130.mp3":[["别游到离岸太远的地方啊。",0,2.3]],"v_sin_131.mp3":[["大伙儿，游完泳要用淡水冲冲身子啊。来，脱吧脱吧！",0,7.31]],"v_smt_000.mp3":[["魂これ！",0,0.74]],"v_smt_001.mp3":[["东山道，下总。汝便是主人吗？明白了。此后为执行任务，吾将加入部队。",0,9.68]],"v_smt_002.mp3":[["要增强战力吗？明白了。吾愿响应您的召唤。",0,6.42]],"v_smt_003.mp3":[["我正在锻炼。有何贵干？如果不是要紧事，我就继续训练了。",0,7.87]],"v_smt_004.mp3":[["为什么让我负责这种工作？请说明理由。若理由不充分，我会拒绝。",0,8.32]],"v_smt_005.mp3":[["啊，什么事？没事的话，别随便碰我。",0,5.49]],"v_smt_006.mp3":[["嗯，明天去这家店吧。蒜加倍、油多拌……好！",0,8.5]],"v_smt_007.mp3":[["不妨碍执行任务，仍可行动。",0,3.834]],"v_smt_010.mp3":[["你带我来，是要我提东西吗？明白了。",0,4.51]],"v_smt_015.mp3":[["泡澡吗？了解了。",0,2.232]],"v_smt_016.mp3":[["坐下，我来给你擦背。我知道轻重，不会伤到你的皮肤。要是不老实，我可就用蛮力了。很好，来，慢慢开始吧。",0,18.6]],"v_smt_024.mp3":[["想进我的房间？本来想拒绝，不过今天就破例允许吧。",0,8.57]],"v_smt_025.mp3":[["任务里已经见了无数次面，居然还追到我房间来……主君真是个奇怪的男人。",0,7.78]],"v_smt_026.mp3":[["不行，那是训练用的负重。主君拿都拿不起来，小心受伤。",0,8.04]],"v_smt_027.mp3":[["我一直认为主君会正确使用我的力量。……我可以相信你吗？",0,8.9]],"v_smt_028.mp3":[["如果主君希望的话，我并不介意。只是……该、该怎么做才好？",0,12.59]],"v_smt_029.mp3":[["嗯，训练时间到了。我得继续锻炼。你想回去的话，随时都可以走。",0,8.01]],"v_smt_030.mp3":[["明白。为了完成任务，我们通力合作吧。",0,4.02]],"v_smt_051.mp3":[["是你啊。开始执行任务吧。",0,3.67]],"v_smt_106.mp3":[["差不多该出门了。今天去的店我已经选好。主君有空就跟来吧。",0,8.21]],"v_smt_107.mp3":[["今天准备了在房间里吃的美食，叫作“外卖”。来，主人，从喜欢的开始吃吧。",0,9.31]],"v_smt_111.mp3":[["写条点评吧。",0,1.72]],"v_smu_000.mp3":[["魂これ！",0,0.97]],"v_smu_001.mp3":[["噢噢噢噢！我是下总！！！小看我的话可是会受伤的，大佬！",0,10.71]],"v_smu_002.mp3":[["没看见这包上的红胶带吗？想打架啊，我奉陪到底！",0,8.67]],"v_smu_003.mp3":[["干嘛啊，前辈？你瞪我干什么？哼！",0,5.64]],"v_smu_004.mp3":[["我的摩托帅吧？要不要载你兜个风？嘿嘿。",0,5.04]],"v_smu_005.mp3":[["就算你这么做，我也不会改过自新的！所以住手啊，前辈！",0,10.82]],"v_smu_006.mp3":[["前辈不在吗？啧，跑哪儿去了？可恶，一个人还真寂寞。",0,11.57]],"v_smu_007.mp3":[["都、都说了只是拿烟头烫出来的印儿！",0,3.945]],"v_smu_010.mp3":[["喂，难得我肯陪你来，给我买点什么嘛，老师？嘿嘿。",0,7.47]],"v_smu_015.mp3":[["去泡个澡吧！",0,1.881]],"v_smu_016.mp3":[["哇……前辈！你、你别到处乱摸啊！那地方跟人类的不一样啦！",0,19.36]],"v_smu_024.mp3":[["突然来家访啊？我可没藏什么东西！",0,7.42]],"v_smu_025.mp3":[["前辈啊……你有喜欢的人吗？干嘛，我只是随口问问！",0,8.67]],"v_smu_026.mp3":[["下次去游乐园吧！我有年卡，可以带路，保证不会让你无聊！",0,11.07]],"v_smu_027.mp3":[["啊？玩偶怎么了？我就是喜欢可爱的东西，有意见吗？",0,8.33]],"v_smu_028.mp3":[["啊，前辈，还不用急着走吧？我还有精神呢！",0,11.02]],"v_smu_029.mp3":[["前辈……你在就好。没什么，真的没事。",0,8.93]],"v_smu_030.mp3":[["喂，哥几个，一起来吹吹风吧！",0,4.23]],"v_smu_051.mp3":[["老师，走，咱们去兜一圈！",0,3.11]],"v_smu_120.mp3":[["前辈，过年就放松点嘛。我给你做好饭啦！说到新年，果然还是下总杂煮最好吃！嗯，酱油味真香！",0,17.22]],"v_smu_121.mp3":[["怎么，困了啊前辈？大过年的，懒懒散散也不是不行。……我也挨着睡吧，嘿嘿。",0,14.3]],"v_smu_122.mp3":[["今年也请多关照啦！",0,2.79]],"v_suo_000.mp3":[["魂これ啦！",0,1.22]],"v_suo_001.mp3":[["哟，我是山阳道的周防！快派给我任务吧，主人！身体躁动难耐啊！",0,8.98]],"v_suo_002.mp3":[["哦，又在喊我吗？能被你依靠真让人开心啊。来吧，尽管开口！",0,8.47]],"v_suo_003.mp3":[["我不太擅长动脑子，所以才想用自己的身体，支持那些想认真学习的人。",0,7.88]],"v_suo_004.mp3":[["啊，衣服好像有点紧了。毕竟每天都在练嘛。唉，肚子饿了，找点东西吃吧。",0,12.78]],"v_suo_005.mp3":[["哦，要我帮忙吗？当然陪你！今天准备干什么？",0,9.92]],"v_suo_006.mp3":[["啊，今天训练结束啦。出了一身汗，叫主人一起去洗澡吧！",0,10.5]],"v_suo_007.mp3":[["这点伤不算什么。说明我给伙伴们挡下来了嘛。嘿嘿。",0,6.773]],"v_suo_010.mp3":[["东西我来提，想买什么就去买吧。也别忘了给我带份礼物哦！",0,5.69]],"v_suo_015.mp3":[["哟，差不多该去泡个澡了！",0,3.456]],"v_suo_016.mp3":[["呼，真舒服！主人，要不要一起进来？虽然地方有点窄，不过总有办法啦！快来！哦，比想象中贴得还紧呢，嘿嘿。",0,17.21]],"v_suo_024.mp3":[["呀，主人，欢迎欢迎！在我房间里好好放松吧，喜欢哪儿就坐哪儿。",0,7.64]],"v_suo_025.mp3":[["主人，有什么烦恼吗？虽然我不懂那些复杂的事，但我随时都陪在你身边！",0,10.16]],"v_suo_026.mp3":[["啊，还没收拾好……哐当哐当……我也有会害羞的东西嘛！",0,8.9]],"v_suo_027.mp3":[["我准备了好多好吃的！那就开动啦！……啊，这么快就吃完了？哈哈！",0,14.01]],"v_suo_028.mp3":[["主人，有我扶着你，放心把身体交给我吧。",0,12.08]],"v_suo_029.mp3":[["主人……睡着了？啊，我也困得要命了……",0,16.92]],"v_suo_030.mp3":[["好，大家就由我来保护！",0,3.79]],"v_suo_051.mp3":[["好，热好身了，随时可以出发！",0,5.03]],"v_suo_106.mp3":[["哟，主人，我是鬼哦！咦，没带豆子吗？来，拿这个朝我扔！一起把福气迎进门吧！",0,12.94]],"v_suo_107.mp3":[["帮我涂遍每个角落吧！好痒……好，赤鬼脸完成！等等，这个洗一洗能掉吧？",0,12.22]],"v_suo_111.mp3":[["对哦，“鬼出去”……可我就是鬼啊！",0,5.09]],"v_sur_000.mp3":[["正是魂これ。",0,1.41]],"v_sur_001.mp3":[["在下乃东海道骏河。化作足柄山的大熊现于世间。……那么，小熊猫，是何物？",0,11.36]],"v_sur_002.mp3":[["承蒙主公再次召唤，在下万分感激。如巍巍富士屹立于世，必将成为日本第一！",0,8.45]],"v_sur_003.mp3":[["在下定会成为更加强壮的大丈夫，誓死守护主公！",0,7.26]],"v_sur_004.mp3":[["唔，这里的饭菜真是美味，不知不觉吃多了。好了，去工作吧！",0,10.42]],"v_sur_005.mp3":[["主公，在下不熟悉那种礼法……还望您亲自指导。",0,10.06]],"v_sur_006.mp3":[["主公说稍后要谈谈……是认真的谈话吧？好，在下先脱去衣物，做好坦诚相对的准备！",0,13.16]],"v_sur_007.mp3":[["呜……主公，请轻些……唔啊！……主公身上的暖意，真是舒服……",0,12.213]],"v_sur_010.mp3":[["主公驾到，还请让路！",0,3.95]],"v_sur_015.mp3":[["呼……坦诚相见，方见真心啊。",0,5.747]],"v_sur_016.mp3":[["在下这就为您擦洗身体。……主、主公，您竟如此强壮，在、在下该如何应对才好，哇哇！",0,17.39]],"v_sur_024.mp3":[["主公，欢迎莅临寒舍。只有粗茶，还请享用。",0,7.18]],"v_sur_025.mp3":[["主公，觉得在下泡的茶如何？还有续杯，今天一起悠闲地度过吧。",0,9.79]],"v_sur_026.mp3":[["啊，这些东西好像都用不着了。在下这就为主公献上一段裸舞！",0,15.11]],"v_sur_027.mp3":[["哇，主公，您在干什么呀！哈哈哈哈，好痒！已、已经够了，请住手！哈哈哈哈！",0,15.11]],"v_sur_028.mp3":[["嗯，哈……在下的身体属于主公。请您随心所欲地使用吧……啊！",0,18.6]],"v_sur_029.mp3":[["能够在主公身边入眠，是在下最大的幸福。",0,4.86]],"v_sur_030.mp3":[["诸位，打起精神出发！",0,3.22]],"v_sur_051.mp3":[["这就开始了。主公，咱们一同出发吧。",0,4.75]],"v_sur_120.mp3":[["主公，若要去初诣，在下愿意随行。与主公并肩参拜，真叫人期待！",0,10.69]],"v_sur_121.mp3":[["说到吉祥之物，便是一富士、二鹰、三茄子，都是我国的名产。于是为了主公，在下特意准备了初茄子。还请品尝！",0,16.87]],"v_sur_122.mp3":[["恭贺新年！",0,3.74]],"v_taj_000.mp3":[["魂これ！",0,1.11]],"v_taj_001.mp3":[["我是但马。这份恩情，我一定加倍报答！……主人您……是受的那一方吗？嘿嘿。",0,12.45]],"v_taj_002.mp3":[["主人！您居然叫了我这么多次……可是……我到底该拿什么来报答您呢……",0,9.49]],"v_taj_003.mp3":[["诶，啊，我泡了茶……那个……我是不是多此一举了？",0,8.29]],"v_taj_004.mp3":[["非常荣幸！啊，不过我还差得远呢，真的。",0,7.66]],"v_taj_005.mp3":[["主、主人！那种事还是请去找别的孩子吧，我就在旁边偷偷看着……",0,8.65]],"v_taj_006.mp3":[["啊……要是和那孩子的话，主人可能是攻方……",0,6.55]],"v_taj_007.mp3":[["这点小伤，我完全没事。",0,2.969354]],"v_taj_008.mp3":[["总部寄来的小包裹，我给您拿过来了。",0,2.91]],"v_taj_009.mp3":[["啊，是这份文件吧。",0,1.88]],"v_taj_010.mp3":[["您请慢慢逛。",0,1.21]],"v_taj_012.mp3":[["哦，看来我也能努把力呢。",0,3.74]],"v_taj_013.mp3":[["啊哈哈哈。",0,1.76]],"v_taj_014.mp3":[["那、那个，您也会对别的孩子这么做吧？我想看看。",0,10.79]],"v_taj_015.mp3":[["我去洗澡，顺便把浴室打扫一下。",0,2.31]],"v_taj_016.mp3":[["主、主人！这又不是那种情节的漫画，突然这样我可受不了！嗯……啊，好厉害！",0,11.69]],"v_taj_018.mp3":[["不做就出不去的房间！？",0,3.26]],"v_taj_019.mp3":[["好的，这是要给哪位送去？诶，给、给我的？主人～～",0,9.4]],"v_taj_020.mp3":[["在！",0,0.53]],"v_taj_021.mp3":[["主人。",0,0.81]],"v_taj_022.mp3":[["您怎么来这儿了？",0,3.24]],"v_taj_023.mp3":[["啊～～……",0,1.46]],"v_taj_024.mp3":[["您是一个人来的？也可以带别人到我的房间来哦。",0,8.5]],"v_taj_025.mp3":[["要一起看战利品吗？我推荐的，呃……是这本！",0,6.58]],"v_taj_026.mp3":[["竟然对这样的我……这么温柔。",0,4.53]],"v_taj_027.mp3":[["您至今……都经历过些什么呀？",0,5.29]],"v_taj_028.mp3":[["啊，主人，我已经准备好了。随时都可以。",0,8.69]],"v_taj_029.mp3":[["……怎么样？",0,3.81]],"v_taj_030.mp3":[["要是按这个队伍编排……嘿嘿嘿。",0,4.38]],"v_taj_031.mp3":[["如果您觉得我可以，我就接下了。",0,2.65]],"v_taj_032.mp3":[["这个，我带回去",0,2.14]],"v_taj_033.mp3":[["要是出了什么事，就是我的错吧……",0,4.48]],"v_taj_034.mp3":[["去时容易，回来可就吓人了。",0,3.63]],"v_taj_035.mp3":[["大家一起加油吧",0,2.26]],"v_taj_036.mp3":[["我要上了。",0,0.89]],"v_taj_037.mp3":[["你选哪个呢，嘿嘿",0,2.13]],"v_taj_038.mp3":[["要是天御狩的话，应该也会这么做吧。",0,2.56]],"v_taj_039.mp3":[["我忍住啊",0,1.52]],"v_taj_040.mp3":[["啊啊！",0,0.88]],"v_taj_041.mp3":[["果然，我不行了……对吧",0,4.26]],"v_taj_042.mp3":[["呜……拖你们后腿了，对不起……",0,4.911]],"v_taj_043.mp3":[["诶？是不是弄错了？我、我很高兴。",0,5.73]],"v_taj_044.mp3":[["唔……",0,1.11]],"v_taj_045.mp3":[["果然，不行……",0,1.91]],"v_taj_046.mp3":[["逮住了！",0,0.76]],"v_taj_047.mp3":[["加油",0,0.99]],"v_taj_048.mp3":[["我跟上。",0,1.16]],"v_taj_049.mp3":[["这是最后一下。",0,1.84]],"v_taj_050.mp3":[["谢谢。",0,1.05]],"v_taj_051.mp3":[["今天我也会悄悄守着你哦。",0,2.71]],"v_taj_052.mp3":[["我是山阴道、但州的但马。虽然是三丹之一，可人们也常说「两丹」，我就被排除出去啦……反正我就是个没用的家伙……",0,15.55]],"v_taj_106.mp3":[["您想好点什么了吗？隐藏菜单？当然也准备齐全了哦！",0,9.87]],"v_taj_107.mp3":[["主人，您看，这是我最近进的最新书籍！啊，我推荐这对配对，还有这本真的太懂了！",0,18.05]],"v_taj_111.mp3":[["好！作为店长，还得再进点新书！",0,5.5]],"v_taj_128.mp3":[["夏天，清澈的大海……不管怎么发展，都像是会出现在同人本里的情节啊。心跳加速了！",0,11.74]],"v_taj_129.mp3":[["主人，要不要带上心仪的孩子去海边？我会在遮阳伞下静静欣赏的。",0,10.03]],"v_taj_130.mp3":[["那个孩子穿了新泳装啊……是主人的心头好吗？诶……",0,8.12]],"v_taj_131.mp3":[["啊，这儿可不是那种海边啦。",0,3.75]],"v_tnb_000.mp3":[["魂これ！",0,1.31]],"v_tnb_001.mp3":[["我是丹波。大哥哥就是我的主人……对吧……请多关照。",0,7.47]],"v_tnb_002.mp3":[["哇，大哥哥……就算你这么夸我，我也没什么能给你啦……",0,7.28]],"v_tnb_003.mp3":[["哥哥，你在工作啊。好有大人的感觉。",0,6.14]],"v_tnb_004.mp3":[["拜托其他人嘛。可只有我才能……真、真的。",0,7.95]],"v_tnb_005.mp3":[["诶，啊，那个……被摸的时候，我都不知道该怎么办了。",0,8.26]],"v_tnb_006.mp3":[["啊，今晚吃什么呢？",0,6.23]],"v_tnb_007.mp3":[["唔，哥哥……好疼。",0,3.662]],"v_tnb_008.mp3":[["好、好像做完了。",0,3.44]],"v_tnb_009.mp3":[["哥哥，果然厉害啊",0,4.61]],"v_tnb_010.mp3":[["嗅嗅……有好多种味道呀。",0,5.06]],"v_tnb_012.mp3":[["为了长大成人啊……",0,2.2]],"v_tnb_013.mp3":[["唔……唔……",0,6.06]],"v_tnb_014.mp3":[["嗯、呼……呜、哈……那个，哥哥，我是不是像个真正的大人了……嘿嘿。",0,12.64]],"v_tnb_015.mp3":[["嗯，这样就看不见了吧",0,5.95]],"v_tnb_016.mp3":[["哥、哥哥，果然是大人呢。我、我能再看一会儿吗？诶，我不行？",0,13.49]],"v_tnb_017.mp3":[["呜、呜～……好害羞啊……",0,5.39]],"v_tnb_018.mp3":[["不、不要……唔、唔！",0,4.42]],"v_tnb_019.mp3":[["诶、诶，我不要。……好吧，只有这一次哦。",0,10.71]],"v_tnb_020.mp3":[["讨厌啦。",0,1.3]],"v_tnb_021.mp3":[["哥哥……",0,1.6]],"v_tnb_022.mp3":[["你、你干嘛？出、出去。",0,5.06]],"v_tnb_023.mp3":[["呼……嗯、唔……呼——",0,3.83]],"v_tnb_024.mp3":[["哥哥，要进来吗？倒也可以啦，不过有点乱哦。",0,10.26]],"v_tnb_025.mp3":[["我喜欢哥哥的味道……有种大人的感觉。",0,9.52]],"v_tnb_026.mp3":[["特训太努力，困了……你想和我一起睡吗？知道啦。",0,17.39]],"v_tnb_027.mp3":[["我每天都喝牛奶，因为想快点长大。",0,9.71]],"v_tnb_028.mp3":[["嗯，有好多事想请哥哥教我。所以……摸一下也可以哦。",0,13.46]],"v_tnb_029.mp3":[["哦，感觉肌肉稍微长出来一点了。",0,8.49]],"v_tnb_030.mp3":[["我不乐意啦……知道了。",0,2.89]],"v_tnb_031.mp3":[["我也有能做的事吗",0,4.3]],"v_tnb_032.mp3":[["……好像有什么东西。",0,4.39]],"v_tnb_033.mp3":[["这味道……得小心点",0,3.9]],"v_tnb_034.mp3":[["大概就是这边",0,2.4]],"v_tnb_035.mp3":[["战斗……要开始了",0,3.34]],"v_tnb_036.mp3":[["要相信自己！",0,2.21]],"v_tnb_037.mp3":[["想变强",0,1.4]],"v_tnb_038.mp3":[["哥哥，看着我，嘿哟嘿！",0,2.5]],"v_tnb_039.mp3":[["还行",0,1.59]],"v_tnb_040.mp3":[["唔，我还能忍住。",0,1.66]],"v_tnb_041.mp3":[["我、我不会输……我不想输。",0,4.23]],"v_tnb_042.mp3":[["哥哥……对不起",0,3.51]],"v_tnb_043.mp3":[["……成功了！哥哥，我也做到了！",0,5.27]],"v_tnb_044.mp3":[["成功了！",0,0.93]],"v_tnb_045.mp3":[["糟、糟糕了。",0,1.73]],"v_tnb_046.mp3":[["上吧！",0,0.8]],"v_tnb_047.mp3":[["没事吧",0,1.3]],"v_tnb_048.mp3":[["我也来。",0,1]],"v_tnb_049.mp3":[["这样就行",0,1]],"v_tnb_050.mp3":[["谢谢。",0,1.1]],"v_tnb_051.mp3":[["我不乐意啦，不过哥哥既然这么说……",0,4.36]],"v_tnb_052.mp3":[["我是丹州的丹波。筱山的稻荷神讨厌认输。我也绝不想输，所以很能明白他的心情。……至于出云和伊势……有点尴尬吧……嗯……",0,22.6]],"v_tnb_128.mp3":[["防晒霜……要涂这种东西吗？呜……好痒呀！",0,9.91]],"v_tnb_129.mp3":[["你是在夸我的胸部大吗？我不太明白啦。",0,8.48]],"v_tnb_130.mp3":[["嗯……这味道，是氯气吗？",0,4.46]],"v_tnb_131.mp3":[["呵呵，西瓜在这边吧。",0,5.59]],"v_tos_000.mp3":[["魂これ！",0,1.2]],"v_tos_001.mp3":[["南海道，土佐。我要贯穿一切敌人！这就是我所走的道路。",0,7.01]],"v_tos_002.mp3":[["来吧，尽管一次又一次召唤我……每一次，我都会变得更强！",0,5.71]],"v_tos_003.mp3":[["嗯？想和我喝一杯？哼，可以。来，干杯！",0,8.71]],"v_tos_004.mp3":[["我可没打算跟什么人都混在一起。",0,3.22]],"v_tos_005.mp3":[["嗯？你说我的肉体很帅？那当然！很结实吧！好，给你看看。",0,9.98]],"v_tos_006.mp3":[["去茅厕……不，主人吩咐过我在这里等着。",0,7.99]],"v_tos_007.mp3":[["下次我会毫发无伤地回来。",0,2.472]],"v_tos_008.mp3":[["别在这儿停下啊。",0,2.33]],"v_tos_009.mp3":[["继续往前冲！",0,1.99]],"v_tos_010.mp3":[["好酒有多少，我全要了。",0,3.22]],"v_tos_012.mp3":[["我心如身披一领具足的武士，无论何时，我都是主人的长枪！",0,6.17]],"v_tos_013.mp3":[["唔呜呜……",0,3.27]],"v_tos_014.mp3":[["真烫啊。主人，再用那把枪把我刺穿吧。",0,9.87]],"v_tos_015.mp3":[["泡在热水里喝酒……嗯，太舒坦了。",0,5.74]],"v_tos_016.mp3":[["来吧，主人。我们之间没必要在意裸体吧？进来喝一杯！哈哈哈！",0,12.26]],"v_tos_017.mp3":[["真是把好枪。",0,2.21]],"v_tos_018.mp3":[["要上了！",0,1.44]],"v_tos_019.mp3":[["好，我就穿上。你要是在意，留下来看看也行。",0,6.03]],"v_tos_020.mp3":[["什么事？",0,0.94]],"v_tos_021.mp3":[["主人。",0,0.7]],"v_tos_022.mp3":[["哦？主人？",0,1.71]],"v_tos_023.mp3":[["嗯唔……",0,1.8]],"v_tos_024.mp3":[["进来吧，主人！今晚喝个痛快！哈哈哈哈！",0,7.06]],"v_tos_025.mp3":[["什么？我还没醉！相信我！",0,6.17]],"v_tos_026.mp3":[["偶尔睡在夜空下也不错，挺让人平静的。",0,6.7]],"v_tos_027.mp3":[["主人，这是什么？我的酒，别洒了！",0,8.42]],"v_tos_028.mp3":[["主人，接下来交给我吧！我已经忍耐到极限了！",0,11.71]],"v_tos_029.mp3":[["酒给你喝多了吗？哼，你还差得远啊！",0,5.52]],"v_tos_030.mp3":[["哼，我会干好的。",0,1.95]],"v_tos_031.mp3":[["跟不上的话就别跟着了。",0,2.71]],"v_tos_032.mp3":[["太厉害了！",0,1.71]],"v_tos_033.mp3":[["等等！有股不好的味道。",0,3.53]],"v_tos_034.mp3":[["这边！跟我来！",0,2.71]],"v_tos_035.mp3":[["把他们打散！",0,1.2]],"v_tos_036.mp3":[["吃我一枪！",0,2.21]],"v_tos_037.mp3":[["这招太软了！",0,1.2]],"v_tos_038.mp3":[["给我贯穿它！",0,1.2]],"v_tos_039.mp3":[["唔……",0,0.82]],"v_tos_040.mp3":[["喝多了吗？",0,2.21]],"v_tos_041.mp3":[["挺能干嘛，我来劲了。",0,3.55]],"v_tos_042.mp3":[["我不会倒下。我不能倒下……",0,4.59]],"v_tos_043.mp3":[["把酒备好等我。啊，下回当然也会赢。",0,5.5]],"v_tos_044.mp3":[["太慢了！",0,0.89]],"v_tos_045.mp3":[["你说什么？",0,2.07]],"v_tos_046.mp3":[["逼到绝路了！",0,1.66]],"v_tos_047.mp3":[["你在干什么？",0,1.71]],"v_tos_048.mp3":[["交给我。",0,1.2]],"v_tos_049.mp3":[["结束了！",0,1.2]],"v_tos_050.mp3":[["我很感激！",0,1.2]],"v_tos_051.mp3":[["要不要先来一杯？",0,2.33]],"v_tos_052.mp3":[["我是流放之国，土州的土佐，也是英武的建依别之国。南面是海，北面是险峻的四国山地，当真是陆上的孤岛。和萨摩、长州的那些人有段复杂的渊源，不过我要做的事不会变。",0,20.11]],"v_tos_057.mp3":[["主人，多谢你的支持。",0,3.72]],"v_tos_128.mp3":[["主人，这就是你的桨。嗯？还愣着干什么？快去河边！",0,9.69]],"v_tos_129.mp3":[["泡过水以后，有人嘱咐我要在毛尖好好涂护毛霜。嗯，主人……你能帮我涂的话，就太好了。",0,14.68]],"v_tos_130.mp3":[["哼，区区这点程度，可没法让我沉下去！",0,4.01]],"v_tou_000.mp3":[["魂これ！",0,1.37]],"v_tou_001.mp3":[["呵啊~~哦，在叫我吗？我是东海道的远江！主人……啊不，兄弟！今日起就是共饮一杯的交情了，请多关照啊！",0,16.61]],"v_tou_002.mp3":[["哦，又叫我了吗？　兄弟。受你恩情，我必当回报。善后就交给我吧！",0,8.36]],"v_tou_003.mp3":[["天气真好啊。这种日子坐在走廊上发呆、望望云，心情最好了。兄弟也来吗？",0,13.18]],"v_tou_004.mp3":[["又软又让人上瘾？这么说来，女人摸起来也许就是这种感觉吧。",0,9.23]],"v_tou_005.mp3":[["喂，兄弟，别老逗我啦，再这样可就不妙了。我先去休息一会儿，马上回来！",0,12.78]],"v_tou_006.mp3":[["唉，饿了就没法打仗嘛。任务定下来再叫醒我吧。",0,16.64]],"v_tou_007.mp3":[["哎哟疼疼疼，这回伤得可真不轻。算啦，抹点唾沫睡一觉就会好了吧。呼……",0,10.075]],"v_tou_010.mp3":[["肚子饿了，吃点鳗鱼补补劲儿吧。",0,5.65]],"v_tou_015.mp3":[["我去飞快洗个澡就回来。",0,2.424]],"v_tou_016.mp3":[["啊，好热啊！兄弟，借我靠一下。哇，凉凉的真舒服！兄弟，嘿嘿，我也喜欢这样。那咱俩就再亲密点吧！",0,23.76]],"v_tou_024.mp3":[["兄弟，你来了我真高兴！喜欢哪儿就坐哪儿。虽然有点乱，但别在意小事嘛。",0,13.01]],"v_tou_025.mp3":[["唉，今天也不洗澡了吧……明天再洗就行！",0,11.79]],"v_tou_026.mp3":[["兄弟，要吃鳗鱼吗？啊……难道你对我这条鳗鱼更感兴趣？嘿嘿，开玩笑啦！",0,12.48]],"v_tou_027.mp3":[["钓鱼嘛，甩下鱼线，吹着风发发呆，最舒服啦。兄弟要不要一起？",0,12.79]],"v_tou_028.mp3":[["嘿嘿嘿，兄弟，我懂！我也正想好好发泄一下。那就一起痛快地放松吧！",0,13.71]],"v_tou_029.mp3":[["兄弟，睡着了吗？嗯，那我也在旁边睡啦。",0,10.96]],"v_tou_030.mp3":[["一不小心睡过头了。",0,4.36]],"v_tou_051.mp3":[["兄弟，这风吹得真舒服。咱们一边看云，一边睡个午觉吧。",0,8.09]],"v_tou_128.mp3":[["兄弟，准备好去游泳了吗？光着身子也行啊。要是一个人害羞，我也脱光陪你！嘿嘿！",0,9.19]],"v_tou_129.mp3":[["啊，皮都晒脱了。兄弟，要帮我涂晒伤用的乳液吗？啊，冰冰凉凉、滑溜溜的呢！",0,16.57]],"v_tou_130.mp3":[["连里面都沾满沙子了！",0,4.05]],"v_wak_000.mp3":[["《魂これ》！",0,0.67]],"v_wak_001.mp3":[["北陆道，若狭。你的肚子就交给我来填饱吧。",0,4.99]],"v_wak_002.mp3":[["怎么，觉得寂寞啦？过来吧。随时都可以叫我哦。",0,5.99]],"v_wak_003.mp3":[["主人，今天天气真好。闻闻，都是太阳的香味。",0,5.32]],"v_wak_004.mp3":[["主人，怎么了？遇到难过的事了吗？乖乖。",0,4.76]],"v_wak_005.mp3":[["才、才不可爱呢！你再这么说就不给你饭吃了！",0,4.69]],"v_wak_006.mp3":[["主人，是不是长胖了？吃了好多东西，真了不起！",0,4.02]],"v_wak_007.mp3":[["这点伤根本不算……唔！",0,2.739]],"v_wak_008.mp3":[["好好休息一下啊。",0,1.45]],"v_wak_009.mp3":[["我可看见你努力的样子了。",0,2.17]],"v_wak_010.mp3":[["这个也买吧。哎呀，篮子都装不下了。",0,4.49]],"v_wak_012.mp3":[["我想到新菜单啦！嗯？啊，我是不是也变强了？",0,6.16]],"v_wak_013.mp3":[["别、别……啊……",0,2.647]],"v_wak_014.mp3":[["真是的，你这爱撒娇的家伙。只许今天这样哦。",0,6.15]],"v_wak_015.mp3":[["呼，舒服，真舒服。",0,3.22]],"v_wak_016.mp3":[["事先说好，不许做奇怪的事！只是一起洗澡而已。嗯！……喂，你还摸！明明都说不行了！",0,9.12]],"v_wak_017.mp3":[["啊啊……",0,1.42]],"v_wak_018.mp3":[["只能硬着头皮上了吗？",0,1.21]],"v_wak_019.mp3":[["诶，现在就要换衣服？在、在这儿？",0,4.97]],"v_wak_020.mp3":[["嗯？",0,0.31]],"v_wak_021.mp3":[["怎么了，主人？",0,0.94]],"v_wak_022.mp3":[["啊呜！？主人！",0,2.18]],"v_wak_023.mp3":[["不要呀～～",0,1.4]],"v_wak_024.mp3":[["啊，嗯……房间有点乱，就当没看见吧。",0,6.26]],"v_wak_025.mp3":[["主人，再待一会儿吧。偶尔悠闲地休息一下也挺好的。",0,8.19]],"v_wak_026.mp3":[["来，把头枕这儿。我帮你掏耳朵，别乱动。",0,8.01]],"v_wak_027.mp3":[["主人的梦想，还有想做的事……我都会支持你的。",0,4.14]],"v_wak_028.mp3":[["啊，主人……那个，可以照顾你，不过只有今天哦。",0,9.74]],"v_wak_029.mp3":[["……睡个好觉哦。",0,8.52]],"v_wak_030.mp3":[["给大伙儿做饭就交给我吧。",0,1.74]],"v_wak_031.mp3":[["当主厨就交给我吧。诶，不是这事吗？",0,4.08]],"v_wak_032.mp3":[["能吃下吗？",0,1.05]],"v_wak_033.mp3":[["大家稍微等等。",0,1.05]],"v_wak_034.mp3":[["必须得选一个才行啊。",0,1.5]],"v_wak_035.mp3":[["这一仗躲不过了。上吧！",0,2.65]],"v_wak_036.mp3":[["我把你切成三片！",0,1.53]],"v_wak_037.mp3":[["切成丝！",0,1.08]],"v_wak_038.mp3":[["宰鱼可是我的拿手活儿！",0,1.61]],"v_wak_039.mp3":[["啊啊！",0,0.68]],"v_wak_040.mp3":[["你这家伙！",0,0.61]],"v_wak_041.mp3":[["我中招了吗？",0,1.11]],"v_wak_042.mp3":[["对不住，大伙儿，我去给你们做饭。",0,2.94]],"v_wak_043.mp3":[["今晚就做一桌我爱吃的菜吧。",0,3.86]],"v_wak_044.mp3":[["好！",0,0.48]],"v_wak_045.mp3":[["形势不利吗？",0,1.11]],"v_wak_046.mp3":[["我来解决！",0,0.76]],"v_wak_047.mp3":[["小心！",0,0.74]],"v_wak_048.mp3":[["就是那家伙吧！",0,1.23]],"v_wak_049.mp3":[["又留了最后一个给我。",0,2.04]],"v_wak_050.mp3":[["谢谢。",0,0.69]],"v_wak_051.mp3":[["喂，饭做好啦！",0,2.12]],"v_wak_052.mp3":[["我是若州的若狭。若狭湾沿岸出产的盐和海产，过去一直进献给朝廷，所以这里是御食国之一。我挺好奇淡路和志摩会做什么菜呢。",0,14.61]],"v_wsr_000.mp3":[["魂これ！",0,0.78]],"v_wsr_001.mp3":[["东山道岩代，前来赴任！首先请教我这座庄园的规矩吧。我一定严格遵守！",0,10.92]],"v_wsr_002.mp3":[["在下是岩代。有一条规矩：不可为之事，便绝不可为。在下绝不会做违背规矩的事，真的不会！",0,11.08]],"v_wsr_003.mp3":[["哼！我的每日功课就是练习挥刀。主人，请看着我哦！",0,9.8]],"v_wsr_004.mp3":[["主、主人，好痒啊！工作还……咦，已经结束了吗？啊，不，没什么！",0,13.79]],"v_wsr_005.mp3":[["啊，主人，在别人面前可不行啊！啊，不对，这事本身就是不该做的吧……呜呜。",0,12.35]],"v_wsr_006.mp3":[["团子、羊羹、铜锣烧、天妇罗馒头……每样都得尝一尝！其一，试吃也是学习的一部分！",0,12.99]],"v_wsr_007.mp3":[["第一条，不可大意……我犯了规矩。我要受罚了吗？呜呜……",0,11.483]],"v_wsr_008.mp3":[["主人，办完了！",0,2.187]],"v_wsr_009.mp3":[["主人的规矩，我想全都学会！",0,3.517]],"v_wsr_010.mp3":[["这鲜制和果子可真不错，回去我就要尝尝！",0,5.19]],"v_wsr_011.mp3":[["用过的东西要放回原处……好了。主人，今天也辛苦您了。",0,8.409]],"v_wsr_012.mp3":[["哇，主人，快试试我的本事吧！我肯定比以前更能帮上忙！",0,9.823]],"v_wsr_013.mp3":[["呜、哇啊啊！",0,3.456]],"v_wsr_014.mp3":[["哈……哈……我学到了好多。这份恩情，我一定会报答的！",0,9.986]],"v_wsr_015.mp3":[["温温的水真舒服。今天就多泡一会儿吧。",0,6.888]],"v_wsr_016.mp3":[["主人，只洗背就好。哇！肚子可不行，那里很敏感！真是的，主人，您可要负责洗到最后哦。",0,17.664]],"v_wsr_017.mp3":[["哇、哇啊啊！",0,2.76]],"v_wsr_018.mp3":[["我、我来了！",0,2.886]],"v_wsr_019.mp3":[["系得紧紧的，正合适。要是您愿意，也看看后面？哼哼。",0,6.506]],"v_wsr_020.mp3":[["怎么了？",0,1.293]],"v_wsr_021.mp3":[["主人。",0,0.881]],"v_wsr_022.mp3":[["诶，别、别看啊！",0,3.533]],"v_wsr_023.mp3":[["啊……！",0,1.26]],"v_wsr_024.mp3":[["正好到吃点心的时间了。主人也歇一会儿吧？现在还有我亲手做的点心呢。",0,8.47]],"v_wsr_025.mp3":[["唔，肚子好像又大了一点……要不要多练几下挥刀呢？啊，已经开始犯困了……",0,15.71]],"v_wsr_026.mp3":[["主人，那个……味道怎么样？看来还合您的口味。我可是摸清了您的喜好呢，哼哼。也请尝尝其他的吧！",0,15.061]],"v_wsr_027.mp3":[["主人，抽屉可不能擅自打开……哇！尤其那一层，更不能开！",0,8.614]],"v_wsr_028.mp3":[["答、答应我别说出去……其实我也……那个……并不讨厌。啊，主人……",0,13.203]],"v_wsr_029.mp3":[["您睡着了吗？那我就趁现在把主人的衣服洗了吧。嘿咻，嘿咻。",0,11.254]],"v_wsr_030.mp3":[["我会尽一份力的！",0,2.17]],"v_wsr_031.mp3":[["我来担任队长！第一条，所有人一定要一起回来！",0,5.639]],"v_wsr_032.mp3":[["好、好像发现了什么！",0,3.07]],"v_wsr_033.mp3":[["有陷阱！……就看看，就看看……",0,6.155]],"v_wsr_034.mp3":[["不能妄下结论。我们谨慎前进吧。",0,3.918]],"v_wsr_035.mp3":[["镇守西方的白虎，此刻就要亮出獠牙了！",0,5.526]],"v_wsr_036.mp3":[["这就是会津五流的招式！",0,2.686]],"v_wsr_037.mp3":[["我从正面进攻！",0,1.888]],"v_wsr_038.mp3":[["不可为之事，便绝不可为！",0,2.23]],"v_wsr_039.mp3":[["这算什么！",0,1.101]],"v_wsr_040.mp3":[["我只是摔了一跤！",0,1.467]],"v_wsr_041.mp3":[["唔……还没完……我绝不……绝不屈服！",0,6.767]],"v_wsr_042.mp3":[["怎、怎么会……真不甘心啊。",0,6.758]],"v_wsr_043.mp3":[["怎么样，主人？交给我是对的吧？哼哼。",0,6.445]],"v_wsr_044.mp3":[["我早就看穿了！",0,1.386]],"v_wsr_045.mp3":[["不该这样的！",0,1.629]],"v_wsr_046.mp3":[["一个一个，稳稳拿下！",0,2.115]],"v_wsr_047.mp3":[["休想对我的同伴出手！",0,2.093]],"v_wsr_048.mp3":[["我也跟上！",0,1.622]],"v_wsr_049.mp3":[["这是最后一个！",0,1.226]],"v_wsr_050.mp3":[["这份恩情我不会忘记！",0,2.175]],"v_wsr_051.mp3":[["主人，今天也由我来保护您。",0,3.56]],"v_wsr_052.mp3":[["我是东山道岩州的岩代。昔日辽阔的陆奥国一分为五，我们也就成了五兄弟。会津不但尚武，茶道和点心制作也很兴盛。我的手艺一定能让您满意！哼哼。",0,21.354]],"v_yms_000.mp3":[["魂これ！",0,1.03]],"v_yms_001.mp3":[["本公子就是坐拥京都的畿内山城。嗯~你就是声闻士啊。虽然一般不招待生面孔……不过嘛，就由本公子来照顾你吧。这就是高贵之人的责任嘛！ 哼哼！……就这么说定了！",0,21.77]],"v_yms_002.mp3":[["怎么又在呼唤本公子啊？以本公子的身份，是你能随便呼唤吗……算了，就特别允许你了。嘿嘿…………才、才没有高兴呢！",0,13.6]],"v_yms_003.mp3":[["本公子可是身份高贵的人，哪需要做什么工作啊。咦？这个也得由我来做？",0,10.22]],"v_yms_004.mp3":[["差不多该回来了吧？为什么还没回来呀？我、我只是想着一起吃饭而已嘛……",0,11.56]],"v_yms_005.mp3":[["啊，我才不会因为被摸几下就动摇呢。竟、竟然还摸到那种地方……！",0,10.91]],"v_yms_006.mp3":[["你有在听我说话吗？咦，主人？难道把我一个人丢在这里跑了？……我才不寂寞呢！",0,14.18]],"v_yms_007.mp3":[["呜……可能没事吧……",0,6.382]],"v_yms_010.mp3":[["哦，这么好的东西，拿着也不丢脸呀？诶嘿嘿……",0,7.78]],"v_yms_015.mp3":[["那我去泡个澡。哈啊……这水真舒服……",0,6.648]],"v_yms_016.mp3":[["你就那么想帮我洗身子吗？好吧。嗯？你的洗法怎么和平时不一样？我、我也是堂堂男子汉，可不会轻易就……啊啊！",0,21.36]],"v_yms_024.mp3":[["您辛苦了。别一直站着，进来歇歇吧。呀！脚、脚麻了！",0,11.79]],"v_yms_025.mp3":[["难得来到我的房间，你再多夸夸我也可以哦。哼哼！",0,6.66]],"v_yms_026.mp3":[["不行，那里很敏感，别那么粗鲁地摸。温柔一点的话……倒是可以。",0,8.87]],"v_yms_027.mp3":[["再在房间里多待一会儿也行啦。咦？那个……有你在的话，我也……比较自在嘛。",0,10.54]],"v_yms_028.mp3":[["哈啊、哈啊……这种模样我只给你一个人看哦。要是敢告诉别人，我可饶不了你！啊……",0,12.72]],"v_yms_030.mp3":[["有劳各位多多关照。哼哼。",0,3.93]],"v_yms_051.mp3":[["哦，你来啦。呵呵，我、我可没特意等你。",0,7.24]],"v_ymt_000.mp3":[["魂これ！",0,1.3]],"v_ymt_001.mp3":[["吾乃国之胜境，大和。汝便是吾之主人吗？来，把吾当作父亲，尽情撒娇便是。",0,14.31]],"v_ymt_002.mp3":[["……好。既然汝有所求，吾这伟大的父亲便再借汝一份力量！",0,10.73]],"v_ymt_003.mp3":[["真是个不错的走廊啊……嗯？你有疑问？……我刚才睡着了。",0,12.97]],"v_ymt_004.mp3":[["主人，来伟大父亲的膝上休息吧。工作由我来处理。",0,9.33]],"v_ymt_005.mp3":[["想征服为父吗？不再激烈一点，我可不会屈服哦！",0,10.62]],"v_ymt_006.mp3":[["哦，主人懒洋洋地滚来滚去，真可爱呀！",0,6.3]],"v_ymt_007.mp3":[["呜哇啊！伤、伤口刺得慌啊……！不过，倒也……有点舒服……",0,10.38]],"v_ymt_008.mp3":[["吾主真了不起。好孩子，好孩子。",0,6]],"v_ymt_009.mp3":[["吾主真是能干的孩子。为父很自豪。",0,6.73]],"v_ymt_010.mp3":[["给庄园的孩子们挑点礼物吧。为父可是很会替人着想的。",0,5.32]],"v_ymt_012.mp3":[["呜哦哦哦！力量涌出来了！",0,5.36]],"v_ymt_013.mp3":[["唔...",0,5.3]],"v_ymt_014.mp3":[["唔……哈、哈……想不到我竟被征服了……着实吃了一惊。",0,12.77]],"v_ymt_015.mp3":[["那么，我就去慢慢泡个澡。",0,3.36]],"v_ymt_016.mp3":[["就用我这双统领众人的臂膀，帮你从头到脚洗得干干净净！哦，当然只是作为父亲啦！",0,13.63]],"v_ymt_017.mp3":[["嗯……再来……再用力些……",0,3.41]],"v_ymt_018.mp3":[["放松一点嘛",0,2.3]],"v_ymt_019.mp3":[["嗯，穿起来舒服极了",0,4.74]],"v_ymt_020.mp3":[["嗯，就是这儿。",0,2.3]],"v_ymt_021.mp3":[["吾主啊。",0,2.3]],"v_ymt_022.mp3":[["什么！？你说想要我的福神……？",0,6.53]],"v_ymt_023.mp3":[["唔呜！？哦哦哦……！",0,5.88]],"v_ymt_024.mp3":[["欢迎来到我这间懒洋洋的屋子！来，和我一起偷懒吧！",0,8.1]],"v_ymt_025.mp3":[["我喜欢给金鱼喂食。要快快长大哦！",0,6.2]],"v_ymt_026.mp3":[["喂，躺在我这软乎乎的身上吧，我来把你包住。",0,6.18]],"v_ymt_027.mp3":[["可以的话，我真想一直和主人两个人睡在一起。",0,5.92]],"v_ymt_028.mp3":[["主、主人！？这绳子是怎么回事！？我可没有那种癖好……唔、哈啊……真是受不了啊……！",0,10.5]],"v_ymt_029.mp3":[["主人，要出门吗？伟大的父亲什么都给你买！",0,6.29]],"v_ymt_030.mp3":[["嗯，要打仗了！",0,2.92]],"v_ymt_031.mp3":[["为了我们的胜利，出发吧！",0,4.82]],"v_ymt_032.mp3":[["吾主会高兴的。",0,2.3]],"v_ymt_033.mp3":[["停下吧",0,1.3]],"v_ymt_034.mp3":[["路线由大伙儿商量着定。",0,3.3]],"v_ymt_035.mp3":[["上！冲进去！",0,4.3]],"v_ymt_036.mp3":[["乖乖睡觉吧",0,2.3]],"v_ymt_037.mp3":[["嘿、嘿、嘿呀！",0,3.3]],"v_ymt_038.mp3":[["将大口真神的牙印刻在你身上吧！",0,5.62]],"v_ymt_039.mp3":[["舒服啊",0,1.95]],"v_ymt_040.mp3":[["越来越有意思了",0,2.72]],"v_ymt_041.mp3":[["这样我可不能退下……！",0,2.65]],"v_ymt_042.mp3":[["净是....",0,4.32]],"v_ymt_043.mp3":[["嗯，那咱们回去好好歇息吧。",0,5.38]],"v_ymt_044.mp3":[["太嫩了！",0,1.3]],"v_ymt_045.mp3":[["怎么办才好啊",0,2.3]],"v_ymt_046.mp3":[["就是汝！",0,1.3]],"v_ymt_047.mp3":[["在走神吗？",0,1.3]],"v_ymt_048.mp3":[["小事一桩！",0,1.3]],"v_ymt_049.mp3":[["由我来给你最后一击！",0,2.3]],"v_ymt_050.mp3":[["感激不尽。",0,1.92]],"v_ymt_051.mp3":[["是谁把我从睡梦中唤醒……哦，吾主啊，开始吧。",0,8.9]],"v_ymt_052.mp3":[["……吾乃大和，国中最美之地，青山环抱于其中。这里气候温暖，台风等灾害也少，是比京都更古老的都城。就算我睡觉，游客也会来，所以悠哉一点也没人怪我。汝也来拜一次大佛吧。",0,29.78]],"v_ymt_128.mp3":[["真是舒畅！主人也来一起游泳吧！",0,6.04]],"v_ymt_129.mp3":[["这泳装也太紧了吧。嗯，我是不是该稍微减点肥呢？",0,7.3]],"v_ymt_130.mp3":[["这是打水腿的练习哦！",0,3.3]],"v_yzm_000.mp3":[["魂これ啦！",0,1.64]],"v_yzm_001.mp3":[["我是畿内的和泉！我想变得更强，好保护同伴！请多关照啦！",0,7.02]],"v_yzm_002.mp3":[["嗯，尽管相信我吧！我一定会成为最强的，主人！",0,5.14]],"v_yzm_003.mp3":[["失败了也没关系，向前看吧，主人！",0,4.68]],"v_yzm_004.mp3":[["成功啦！真想赶快试试新招式！",0,4.63]],"v_yzm_005.mp3":[["不管什么都能忍受！为了变得更强！",0,7.2]],"v_yzm_006.mp3":[["好累……可现在还不能休息！",0,6.93]],"v_yzm_007.mp3":[["唔……真不甘心啊！下次我还要变得更强、更强！",0,7.409]],"v_yzm_008.mp3":[["主人，还不是很满意是吧？",0,3.42]],"v_yzm_009.mp3":[["主人你真努力啊！我也不甘落后！",0,6]],"v_yzm_010.mp3":[["好厉害！宝贝堆成山了！",0,4.09]],"v_yzm_012.mp3":[["现在的话，我应该能把长枪转得滴水不漏啦！",0,4.97]],"v_yzm_013.mp3":[["呜哇啊啊啊——！",0,1.96]],"v_yzm_014.mp3":[["刚、刚才那是什么……也太厉害了……",0,8.54]],"v_yzm_015.mp3":[["泡泡热水就能好。",0,4.68]],"v_yzm_016.mp3":[["我来帮你擦背吧。来，坐在这里。咻咻咻，唰唰唰！",0,10.03]],"v_yzm_017.mp3":[["撑、撑得住！呜啊！",0,1.86]],"v_yzm_018.mp3":[["交给我吧！",0,1.46]],"v_yzm_019.mp3":[["主人，这件可太适合我啦。看上去很强吧？嘿嘿！",0,6.29]],"v_yzm_020.mp3":[["呜哦——！",0,2.31]],"v_yzm_021.mp3":[["主人！",0,1.05]],"v_yzm_022.mp3":[["哇！等、等一下啊！",0,3.06]],"v_yzm_023.mp3":[["真是的……啊……",0,3.03]],"v_yzm_024.mp3":[["欢迎来到我的特训设施，主人！我们一起变强吧！",0,5.35]],"v_yzm_025.mp3":[["啊，别看那种地方啦！啊，这里……",0,5.27]],"v_yzm_026.mp3":[["主人，要吃橘子吗？我帮你剥皮！",0,4.54]],"v_yzm_027.mp3":[["玩神话扮演游戏？接下来演哪里的神话？咦？我、我来演伊邪那美？",0,7.9]],"v_yzm_028.mp3":[["主人，只要和主人在一起，我完全不讨厌。所以……下次也再来吧。",0,12.44]],"v_yzm_029.mp3":[["呃、那个……今天就尽情释放出来吧！",0,5.46]],"v_yzm_030.mp3":[["哦，我热血沸腾啦！",0,2.51]],"v_yzm_031.mp3":[["和大家一起战斗！",0,2.63]],"v_yzm_032.mp3":[["我吃东西不挑食哦。",0,2.41]],"v_yzm_033.mp3":[["无论发生什么，我们都不会输！",0,3.01]],"v_yzm_034.mp3":[["前进——！",0,1.58]],"v_yzm_035.mp3":[["正面交给我！后方掩护就拜托啦！",0,3.87]],"v_yzm_036.mp3":[["接招！和泉雷电！",0,2.49]],"v_yzm_037.mp3":[["血沼水花！",0,2.3]],"v_yzm_038.mp3":[["呜哦哦——！地车烈焰！",0,4.16]],"v_yzm_039.mp3":[["哇啊～！",0,1]],"v_yzm_040.mp3":[["没事！没事！",0,2.27]],"v_yzm_041.mp3":[["我绝对不会逃！",0,2.201]],"v_yzm_042.mp3":[["我输了吗……可恶啊啊啊！",0,5.24]],"v_yzm_043.mp3":[["太好啦！主人、大伙儿，谢谢！",0,3.88]],"v_yzm_044.mp3":[["好！",0,0.97]],"v_yzm_045.mp3":[["不会吧！",0,0.77]],"v_yzm_046.mp3":[["就是那里！",0,1.16]],"v_yzm_047.mp3":[["住手！",0,1.09]],"v_yzm_048.mp3":[["上啊！",0,1.23]],"v_yzm_049.mp3":[["可别大意！",0,1.2]],"v_yzm_050.mp3":[["谢谢！",0,0.91]],"v_yzm_051.mp3":[["主人，来，我们一起走吧！",0,2.94]],"v_yzm_052.mp3":[["我是畿内泉州的和泉。以前也有过「茅渟」这个名字。为什么呢？神武东征时，五濑命在大阪湾洗过伤口，这片海就有了「血沼海」的名字。血的沼泽……是不是很帅？！",0,20.7]],"v_yzm_128.mp3":[["没有被鲜血染红、湛蓝湛蓝的大海啊。看起来真舒服。",0,4.99]],"v_yzm_129.mp3":[["主人，一起去泳池吧！逆着漂流泳池的水流游，锻炼身体！",0,5.99]],"v_yzm_130.mp3":[["嘶，火辣辣地疼啊！",0,2.75]],"v_yzm_131.mp3":[["盛夏水花大爆发！",0,3.14]]};
