  const VERSION = '1.1.9';
  const LOG = '[tamacolle-subs]';
  const MP3_IN_URL = /\/(v_[a-z0-9]+_\d+(?:_\d+)?)\.mp3(?:[?#]|$)/i;
  const BARE_VOICE = /^(?:.*\/)?(v_[a-z0-9]+_\d+(?:_\d+)?)(?:\.mp3)?$/i;

  // 界面白名单/黑名单（对应 GV.stat.gamenName；来自项目 bundle 的字符串表）
  const SCREEN_ALLOW = ['ROOM', 'TOUCH', 'BATH', 'HIROMA', 'HOME', 'FRIENDSHIP'];
  const SCREEN_DENY = ['STORY', 'SCENARIO', 'NOVEL', 'GACHA', 'GACYA', 'RECRUIT', 'SUMMON', 'SCOUT', 'GAMESTART', 'FIRSTDANJI', 'OPENING_EVENT', 'TITLE', 'LOADING', 'SHOP', 'COLLECTION', 'CLOTH', 'BOND', 'MARRIAGE', 'AZUKIYA'];

  const DEFAULTS = {
    enabled: true,
    position: 'bottom', // bottom | top（相对于游戏画面，不是手机竖屏方向）
    orientationMode: 'auto', // auto: 自动跟随画面；screen: 始终竖屏文字；rotate90: 强制顺时针旋转90度
    fontScale: 1,
    debug: false,
    trace: false, // 最近 32 条播放记录，保留在本页内存
    // 读不到 GV.stat.gamenName 时：'show' 先照常显示，'hide' 一律不出（更保守）
    unknownScreenPolicy: 'show',
    hideDelayMs: 250,
    // 兜底：URL / Cocos Scene 名命中这些片段时不叠加（正常情况下 gamenName 已覆盖）
    suppressRoutes: ['story', 'scenario', 'novel', 'recruit', 'gacha', 'opening', 'episode', 'prologue'],
    suppressScenes: ['story', 'scenario', 'novel', 'recruit', 'gacha', 'opening', 'episode', 'prologue', 'title', 'loading'],
  };

  const KEY = 'tamacolle_cn_subtitles/v1';
  const DEBUG = { last: null, reason: null, gamen: null, route: null, scene: null, hooked: [] };

  // ===== 配置 =====
  function loadCfg() {
    const cfg = JSON.parse(JSON.stringify(DEFAULTS));
    try {
      const raw = localStorage.getItem(KEY);
      if (raw) Object.assign(cfg, JSON.parse(raw));
    } catch (_) {}
    return cfg;
  }
  let cfg = loadCfg();
  function saveCfg() {
    try { localStorage.setItem(KEY, JSON.stringify(cfg)); } catch (_) {}
  }

  // ===== 纯函数（可测试）=====
  function fileFromUrl(url) {
    const m = String(url == null ? '' : url).match(MP3_IN_URL);
    return m ? m[1].toLowerCase() + '.mp3' : null;
  }

  function fileFromName(name) {
    const m = String(name == null ? '' : name).trim().match(BARE_VOICE);
    return m ? m[1].toLowerCase() + '.mp3' : null;
  }

  /**
   * 从 cc.audioEngine 的第一个参数里取语音文件名。
   * 参数可能是 URL 字符串，也可能是 cc.AudioClip（可能带 url / nativeUrl / name / _nativeAsset）。
   */
  function voiceFileFrom(value) {
    if (value == null) return null;
    if (typeof value === 'string') return fileFromUrl(value) || fileFromName(value);
    const cands = [];
    try {
      cands.push(value.url, value.nativeUrl, value.src, value.name);
      const na = value._nativeAsset;
      if (na) cands.push(na.src, na.currentSrc, na.url);
    } catch (_) {}
    for (let i = 0; i < cands.length; i++) {
      const f = fileFromUrl(cands[i]) || fileFromName(cands[i]);
      if (f) return f;
    }
    return null;
  }

  function entryFor(file) {
    if (!file) return null;
    const row = SUBTITLE_DB[file];
    if (!Array.isArray(row) || !Array.isArray(row[0])) return null;
    const zh = String(row[0][0] || '').trim();
    if (!zh) return null;
    const duration = Number(row[0][2]);
    if (!isFinite(duration) || duration <= 0) return null;
    return { zh: zh, durationMs: Math.round(duration * 1000) };
  }

  function matchRule(rule, haystack) {
    if (!rule || !haystack) return false;
    return String(haystack).toLowerCase().indexOf(String(rule).toLowerCase()) !== -1;
  }

  function screenDecision(gamen) {
    if (!gamen) return null;
    for (let i = 0; i < SCREEN_DENY.length; i++) {
      if (matchRule(SCREEN_DENY[i], gamen)) return { allow: false, reason: 'gamen_deny:' + gamen };
    }
    for (let i = 0; i < SCREEN_ALLOW.length; i++) {
      if (matchRule(SCREEN_ALLOW[i], gamen)) return { allow: true, reason: null };
    }
    return cfg.unknownScreenPolicy === 'hide'
      ? { allow: false, reason: 'gamen_unknown:' + gamen }
      : { allow: true, reason: null };
  }

  // ===== 画面 =====
  let overlay = null;
